console.log("SCRIPT START");
const RANKEDCOACH_APP_BUILD_ID = "20260804-uncapped-backfill-01";
globalThis.RankedCoachBuild = Object.freeze({ id: RANKEDCOACH_APP_BUILD_ID });

// ========================
// CORE UTILITIES (EARLY LOAD FIX)
