function updatePeakRankAfterMatchSave(profile = getActiveProfile()) {
  const activeProfile = profile || getActiveProfile();
  if (!activeProfile?.id) {
    return { isNewPeak: false, peakData: computePeakProfileProgress(activeProfile) };
  }
  const peakData = computePeakProfileProgress(activeProfile);
  const nextPeakRR = safeNumber(peakData?.peakRR);
  const previousPeakRR = safeNumber(activeProfile?.peakRR);
  const hasPreviousPeak = previousPeakRR > 0;
  const shouldPersistPeak = nextPeakRR > previousPeakRR || !hasPreviousPeak;
  const isNewPeak = hasPreviousPeak && nextPeakRR > previousPeakRR;
  if (shouldPersistPeak) {
    updateProfile(activeProfile.id, { peakRR: nextPeakRR });
  }
  return {
    isNewPeak,
    peakData: { ...peakData, peakRR: nextPeakRR },
    previousPeakRR
  };
}

function onMatchSaved(record, options = {}) {
  const importedCount = Math.max(1, Math.round(safeNumber(options.importedCount) || 1));
  const { variant } = getPremiumFeedbackTheme();
  refreshActiveProfileDataSurfaces?.({
    chartAnimationMode: options.mode === "refresh" ? CHART_ANIMATION_MODE_LATEST_ONLY : null,
    animatePlaceholders: false
  });
  const hasPeakEventOverride = Boolean(options.peakData) || options.isNewPeak != null;
  const peakEvent = hasPeakEventOverride
    ? {
        isNewPeak: Boolean(options.isNewPeak),
        peakData: options.peakData || computePeakProfileProgress(getActiveProfile())
      }
    : updatePeakRankAfterMatchSave(options.profile || getActiveProfile());
  const peakData = peakEvent.peakData || computePeakProfileProgress(getActiveProfile());
  const result = String(record?.result || record?.metadata?.result || "").trim().toLowerCase();
  if (peakEvent.isNewPeak) {
    showToast(`Peak reached: ${peakData?.tierLabel || "New personal best"}.`, {
      title: "New peak rank!",
      iconUrl: peakData?.rankIconUrl || "",
      variant
    });
    triggerPremiumMoment("peak", { result });
    openMatchSummaryModalBeforeBroadcast(record, { ...options, isPeakEvent: true, delayMs: 40 });
    pulsePremiumAvatarCelebration();
    scheduleProfileStreakAnnouncement(1150);
    return;
  }
  const title = importedCount > 1 ? "History updated" : "Match saved";
  const message = importedCount > 1
    ? `${importedCount} matches imported into this profile.`
    : "Match report saved to this profile.";
  showToast(message, { title, variant });
  if (result === "win" || result === "loss") {
    triggerPremiumMoment("result", { result });
  }
  openMatchSummaryModalBeforeBroadcast(record, { ...options, delayMs: 40 });
  scheduleProfileStreakAnnouncement(1150);
}

function getCanonicalMatchRecordCount() {
  const records = window.RankedCoachMatchRecord?.getRuntimeRecords?.({
    matches,
    logEntries: getProfileLogEntries(activeProfileId, { authoredOnly: true }),
    profile: getActiveProfile()
  }) || [];
  return records.filter(isRankedPerformanceMatch).length;
}

const COACH_READINESS_UNLOCKS = [
  { key: "match-impact", label: "Post-match impact", requiredMatches: 1 },
  { key: "recent-trends", label: "Recent trends", requiredCurrentSeasonMatches: 5 },
  { key: "stats-confidence", label: "Stats confidence", requiredCurrentSeasonMatches: 10 },
  { key: "deep-insights", label: "Deep insights", requiredMatches: 20, requiredCurrentSeasonMatches: 10, requiredLogs: 5 }
];

function getCoachReadinessModel() {
  const profile = getActiveProfile();
  const matchCount = getCanonicalMatchRecordCount();
  const authoredLogCount = getProfileLogEntries(activeProfileId, { authoredOnly: true }).length;
  const profileMatches = Array.isArray(profile?.matches) ? profile.matches : [];
  const rankedProfileMatches = profileMatches.filter(isRankedPerformanceMatch);
  const currentSeasonKey = getStatsSelectedActKey(profile, { ignoreActiveSelection: true, matches: rankedProfileMatches });
  const currentSeasonMatchCount = currentSeasonKey
    ? rankedProfileMatches.filter(match => matchBelongsToSelectedStatsAct(match, currentSeasonKey, { profile })).length
    : 0;
  const recentMatches = getSortedMatches(rankedProfileMatches).slice(-20);
  const completeMatches = recentMatches.filter(match => {
    const core = getMatchCore(match);
    return core.map && core.map !== "Unknown"
      && core.agent && core.agent !== "Unknown"
      && Number.isFinite(Number(core.kills))
      && Number.isFinite(Number(core.deaths))
      && ["win", "loss", "draw"].includes(String(core.result || "").toLowerCase());
  }).length;
  const historyProgress = Math.min(1, matchCount / 20);
  const currentSeasonProgress = Math.min(1, currentSeasonMatchCount / 10);
  const reflectionProgress = Math.min(1, authoredLogCount / 5);
  const completenessProgress = recentMatches.length ? completeMatches / recentMatches.length : 0;
  const percent = Math.round(
    (historyProgress * 40)
    + (currentSeasonProgress * 25)
    + (reflectionProgress * 25)
    + (completenessProgress * 10)
  );
  const unlocks = COACH_READINESS_UNLOCKS.map(item => {
    const requirements = [];
    if (item.requiredMatches) {
      requirements.push({ current: matchCount, required: item.requiredMatches, label: "games" });
    }
    if (item.requiredCurrentSeasonMatches) {
      requirements.push({ current: currentSeasonMatchCount, required: item.requiredCurrentSeasonMatches, label: "season" });
    }
    if (item.requiredLogs) {
      requirements.push({ current: authoredLogCount, required: item.requiredLogs, label: "logs" });
    }
    const complete = requirements.every(requirement => requirement.current >= requirement.required);
    const progress = requirements.length
      ? Math.min(...requirements.map(requirement => Math.min(100, Math.round((requirement.current / requirement.required) * 100))))
      : 0;
    const progressLabel = requirements
      .filter(requirement => requirement.current < requirement.required)
      .map(requirement => `${Math.min(requirement.current, requirement.required)}/${requirement.required} ${requirement.label}`)
      .join(" · ");
    return { ...item, complete, progress, progressLabel };
  });
  const nextUnlock = unlocks.find(item => !item.complete);
  const unlocked = unlocks.filter(item => item.complete);
  const copyParts = [`${matchCount} ranked matches imported`];
  copyParts.push(`${currentSeasonMatchCount}/10 current-season matches`);
  copyParts.push(`${authoredLogCount}/5 reflection logs`);
  const copy = nextUnlock
    ? `${copyParts.join(". ")}. Next: ${nextUnlock.label} (${nextUnlock.progressLabel}).`
    : `${copyParts.join(". ")}. Match-driven reads are unlocked; rating grows with current-season play and your own reflections.`;
  return {
    matchCount,
    authoredLogCount,
    currentSeasonMatchCount,
    completenessProgress,
    percent,
    copy,
    nextUnlock,
    unlocked,
    unlocks
  };
}

function getReadinessLockedMarkup(required, label) {
  const model = getCoachReadinessModel();
  const remaining = Math.max(0, required - model.matchCount);
  const progress = Math.min(100, Math.round((model.matchCount / Math.max(1, required)) * 100));
  return `
    <div class="coach-readiness-locked" data-required="${required}">
      <div class="coach-readiness-locked-title">${escapeHtml(label)}</div>
      <div class="coach-readiness-locked-copy">
        ${model.matchCount}/${required} games logged${remaining ? `. Add ${remaining} more to unlock this read.` : "."}
      </div>
      <div class="coach-readiness-locked-bar"><span style="--profile-progress:${progress};width:${progress}%"></span></div>
    </div>
  `;
}

function renderCoachReadinessUI() {
  const card = document.getElementById("coachReadinessCard");
  const widget = document.getElementById("profileRatingWidget");
  if (!card && !widget) return;
  const model = getCoachReadinessModel();

  const writeUnlocks = (target, options = {}) => {
    if (!target) return;
    target.innerHTML = model.unlocks.map(item => `
      <div class="profile-rating-unlock coach-readiness-unlock ${item.complete ? "is-complete" : "is-locked"}">
        <span>${escapeHtml(item.label)}</span>
        <strong>${item.complete ? "Unlocked" : escapeHtml(item.progressLabel)}</strong>
        <div class="coach-readiness-mini-bar"><span style="--profile-progress:${item.progress};width:${item.progress}%"></span></div>
      </div>
    `).join("") + (options.includeActivity ? buildProfileActivityHeatmapMarkup(getActiveProfile?.()) : "");
  };

  if (card) {
    const value = document.getElementById("coachReadinessValue");
    const copy = document.getElementById("coachReadinessCopy");
    const fill = document.getElementById("coachReadinessFill");
    const unlocks = document.getElementById("coachReadinessUnlocks");

    card.dataset.readinessPercent = String(model.percent);
    card.classList.toggle("is-ready", model.percent >= 100);
    if (value) value.textContent = `${model.percent}%`;
    if (copy) copy.textContent = model.copy;
    if (fill) {
      fill.style.setProperty("--profile-progress", String(model.percent));
      fill.style.width = `${model.percent}%`;
    }
    writeUnlocks(unlocks);
  }

  if (widget) {
    const widgetValue = document.getElementById("profileRatingValue");
    const dropdownValue = document.getElementById("profileRatingDropdownValue");
    const copy = document.getElementById("profileRatingCopy");
    const fill = document.getElementById("profileRatingFill");
    const unlocks = document.getElementById("profileRatingUnlocks");
    widget.dataset.readinessPercent = String(model.percent);
    widget.classList.toggle("is-ready", model.percent >= 100);
    if (widgetValue) widgetValue.textContent = `${model.percent}%`;
    if (dropdownValue) dropdownValue.textContent = `${model.percent}%`;
    if (copy) copy.textContent = model.copy;
    if (fill) {
      fill.style.setProperty("--profile-progress", String(model.percent));
      fill.style.width = `${model.percent}%`;
    }
    writeUnlocks(unlocks, { includeActivity: true });
  }

  writeMobileProfileRating?.(model);
  scheduleProfileStreakAnnouncement(1300);
}

function setProfileRatingDropdownOpen(open) {
  const widget = document.getElementById("profileRatingWidget");
  const dropdown = document.getElementById("profileRatingDropdown");
  if (!dropdown) return;
  const shouldOpen = Boolean(open);
  dropdown.hidden = !shouldOpen;
  dropdown.classList.toggle("open", shouldOpen);
  widget?.classList.toggle("open", shouldOpen);
  widget?.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
  if (shouldOpen) {
    positionProfileRatingDropdown();
  }
}

function positionProfileRatingDropdown() {
  const dropdown = document.getElementById("profileRatingDropdown");
  if (!dropdown || dropdown.hidden) return;

  if (isMobileLayoutViewport?.()) {
    ["position", "top", "left", "right", "width", "max-height"].forEach(property => {
      dropdown.style.removeProperty(property);
    });
    return;
  }

  const navRight = document.querySelector(".nav-right");
  const anchor = document.querySelector(".profile-rating-anchor");
  const rect = navRight?.getBoundingClientRect?.() || anchor?.getBoundingClientRect?.();
  if (!rect) return;

  const viewportWidth = window.innerWidth || document.documentElement.clientWidth || 0;
  const viewportHeight = window.innerHeight || document.documentElement.clientHeight || 0;
  const width = Math.min(340, Math.max(280, viewportWidth - 24));
  const left = Math.min(Math.max(8, rect.left), Math.max(8, viewportWidth - width - 8));
  const top = Math.min(Math.max(8, rect.bottom + 8), Math.max(8, viewportHeight - 220));

  dropdown.style.setProperty("position", "fixed", "important");
  dropdown.style.setProperty("left", `${left}px`, "important");
  dropdown.style.setProperty("right", "auto", "important");
  dropdown.style.setProperty("top", `${top}px`, "important");
  dropdown.style.setProperty("width", `${width}px`, "important");
  dropdown.style.setProperty("max-height", `${Math.max(220, viewportHeight - top - 12)}px`, "important");
}

