const STORAGE_KEY_PROFILES = "valtracker_profiles_v1";
const STORAGE_KEY_ACTIVE_ID = "valtracker_active_profile_id";
const STORAGE_KEY_LOG_ENTRIES = "valtracker_log_entries_v2";
const STORAGE_KEY_LOG_ENTRIES_LEGACY = "valtracker_log_entries_v1";
const STORAGE_KEY_LAST_BACKEND_SYNC = "valtracker_last_backend_sync_v1";
const STORAGE_KEY_INSIGHT_FEEDBACK = "rankedcoach_insight_feedback_v1";
const STORAGE_KEY_PENDING_LOADOUT_ROLLS = "rankedcoach_pending_loadout_rolls_v1";
const STORAGE_KEY_LAST_SEEN_APP_BUILD = "rankedcoach_last_seen_app_build_v1";
const STORAGE_KEY_LAST_AUTH_USER = "rankedcoach_last_auth_user_v1";
const STORAGE_KEY_PENDING_LOG_DELETES = "rankedcoach_pending_log_deletes_v1";
const RIOT_SYNC_TIMEOUT_MS = 45 * 1000;
const AUTH_INIT_TIMEOUT_MS = Math.max(800, Number(globalThis.RANKEDCOACH_AUTH_INIT_TIMEOUT_MS) || 3500);
const AUTH_ACTION_TIMEOUT_MS = Math.max(1200, Number(globalThis.RANKEDCOACH_AUTH_ACTION_TIMEOUT_MS) || 6500);
const RANKED_MATCH_PLACEHOLDER_WINDOW_DAYS = 30;
const LOG_FEED_ALL_HISTORY_MAX_SESSIONS = 14;
const LOG_FEED_ALL_HISTORY_MAX_ENTRIES = 80;

const backendSyncState = {
  applyingRemote: false,
  hydratingUserId: "",
  saveTimer: null,
  savePromise: null,
  pendingSaveReason: "",
  lastSaveReason: "",
  lastError: null,
  lastSaveMetrics: null,
  lastSaveFailures: [],
  lastLocalSaveAt: 0,
  normalizedRowsUserId: "",
  normalizedMatchRowsInitialized: false,
  normalizedLogRowsInitialized: false,
  pendingNormalizedMatchRowIds: new Set(),
  pendingNormalizedLogRowIds: new Set()
};

let persistentAccountRealtimeChannel = null;
let persistentAccountRealtimeUserId = "";
let persistentAccountRealtimeReloadTimer = 0;
let persistentAccountRealtimeNoticeShown = false;
let persistentAccountSaveNoticeLastShownAt = 0;
let persistentAccountSaveRetryTimer = 0;
let authReachabilityNoticeLastShownAt = 0;
let authReachabilityOfflineUntil = 0;
let rankedCoachAppUpdateCheckTimer = 0;
let rankedCoachAppUpdateCheckInFlight = false;
let rankedCoachAppUpdateNoticeShown = false;
let rankedCoachLastAppUpdateCheckAt = 0;

function readPendingPersistentLogDeleteIds() {
  try {
    const parsed = JSON.parse(localStorage.getItem(STORAGE_KEY_PENDING_LOG_DELETES) || "[]");
    return new Set((Array.isArray(parsed) ? parsed : [])
      .map(value => String(value || "").trim())
      .filter(Boolean));
  } catch (_error) {
    return new Set();
  }
}

const pendingPersistentLogDeleteIds = readPendingPersistentLogDeleteIds();

function persistPendingPersistentLogDeleteIds() {
  try {
    localStorage.setItem(STORAGE_KEY_PENDING_LOG_DELETES, JSON.stringify([...pendingPersistentLogDeleteIds]));
  } catch (_error) {
    // The in-memory set still lets this page finish the retry when storage is unavailable.
  }
}

function queuePersistentLogDeletion(id = "") {
  const entryId = String(id || "").trim();
  if (!entryId) return;
  pendingPersistentLogDeleteIds.add(entryId);
  persistPendingPersistentLogDeleteIds();
}

function resolvePersistentLogDeletion(id = "") {
  const entryId = String(id || "").trim();
  if (!entryId) return;
  pendingPersistentLogDeleteIds.delete(entryId);
  persistPendingPersistentLogDeleteIds();
}

function ensureNormalizedRowSyncState(userId = "") {
  const normalizedUserId = String(userId || "").trim();
  if (!normalizedUserId || backendSyncState.normalizedRowsUserId === normalizedUserId) return;
  backendSyncState.normalizedRowsUserId = normalizedUserId;
  backendSyncState.normalizedMatchRowsInitialized = false;
  backendSyncState.normalizedLogRowsInitialized = false;
  backendSyncState.pendingNormalizedMatchRowIds = new Set();
  backendSyncState.pendingNormalizedLogRowIds = new Set();
}

function markPersistentLogRowsDirty(entryIds = []) {
  const userId = String(currentAuthUser?.id || "").trim();
  if (!userId) return;
  ensureNormalizedRowSyncState(userId);
  (Array.isArray(entryIds) ? entryIds : [entryIds]).forEach(entryId => {
    const normalizedId = String(entryId || "").trim();
    if (normalizedId) backendSyncState.pendingNormalizedLogRowIds.add(normalizedId);
  });
}

function markPersistentMatchRowsDirty(rowIds = []) {
  const userId = String(currentAuthUser?.id || "").trim();
  if (!userId) return;
  ensureNormalizedRowSyncState(userId);
  (Array.isArray(rowIds) ? rowIds : [rowIds]).forEach(rowId => {
    const normalizedId = String(rowId || "").trim();
    if (normalizedId) backendSyncState.pendingNormalizedMatchRowIds.add(normalizedId);
  });
}

function markNormalizedRowsSaved(userId = "", type = "", rows = []) {
  ensureNormalizedRowSyncState(userId);
  const normalizedType = String(type || "").toLowerCase();
  const target = normalizedType === "match"
    ? backendSyncState.pendingNormalizedMatchRowIds
    : backendSyncState.pendingNormalizedLogRowIds;
  (Array.isArray(rows) ? rows : []).forEach(row => target.delete(String(row?.id || "").trim()));
  if (normalizedType === "match") backendSyncState.normalizedMatchRowsInitialized = true;
  if (normalizedType === "log") backendSyncState.normalizedLogRowsInitialized = true;
}

let insightFeedbackEntries = readInsightFeedbackEntries();

function createAuthTimeoutError(label = "Auth request", timeoutMs = AUTH_ACTION_TIMEOUT_MS) {
  const seconds = Math.max(1, Math.round(timeoutMs / 1000));
  const error = new Error(`${label} did not respond within ${seconds} seconds.`);
  error.name = "RankedCoachAuthTimeoutError";
  error.code = "AUTH_TIMEOUT";
  error.timeoutMs = timeoutMs;
  error.playerMessage = "Having trouble reaching your account right now — continuing with your local data.";
  return error;
}

function isAuthTimeoutError(error = {}) {
  return error?.name === "RankedCoachAuthTimeoutError" || error?.code === "AUTH_TIMEOUT";
}

function isAbortError(error = {}) {
  return error?.name === "AbortError" || error?.code === "ABORT_ERR";
}

function notifyAuthReachabilityIssue(message = "", options = {}) {
  if (options.silent) return;
  const now = Date.now();
  if (!options.force && now - authReachabilityNoticeLastShownAt < 30000) return;
  authReachabilityNoticeLastShownAt = now;
  showToast(message || "Having trouble reaching your account right now — continuing with your local data.", {
    title: options.title || "Account check delayed",
    variant: "warning",
    durationMs: options.durationMs || 5000
  });
}

function markAuthReachabilityOffline(timeoutMs = AUTH_ACTION_TIMEOUT_MS) {
  const cooldownMs = Math.max(15000, Math.min(60000, Number(timeoutMs || AUTH_ACTION_TIMEOUT_MS) * 4));
  authReachabilityOfflineUntil = Math.max(authReachabilityOfflineUntil, Date.now() + cooldownMs);
}

function isAuthReachabilityOfflineCooldownActive() {
  return Date.now() < authReachabilityOfflineUntil;
}

function shouldSkipAuthRequestForOfflineCooldown(options = {}) {
  return options.allowDuringAuthCooldown !== true && isAuthReachabilityOfflineCooldownActive();
}

function getPlayerFacingAuthErrorMessage(error = {}, fallback = "Unable to reach the account service. Please try again.") {
  if (isAuthTimeoutError(error)) {
    return error.playerMessage || fallback;
  }
  return error?.message || fallback;
}

function normalizeCachedAuthUser(user = {}) {
  if (!user || typeof user !== "object") return null;
  const id = String(user.id || user.sub || "").trim();
  const email = String(user.email || "").trim();
  if (!id && !email) return null;
  return {
    ...user,
    id: id || email,
    email,
    user_metadata: user.user_metadata && typeof user.user_metadata === "object" ? user.user_metadata : {},
    app_metadata: user.app_metadata && typeof user.app_metadata === "object" ? user.app_metadata : {}
  };
}

function extractCachedAuthUserFromPayload(payload = {}) {
  if (!payload || typeof payload !== "object") return null;
  const direct = normalizeCachedAuthUser(payload.user);
  if (direct) return direct;
  const candidates = [
    payload.currentSession?.user,
    payload.session?.user,
    payload.data?.session?.user,
    payload.data?.user
  ];
  for (const candidate of candidates) {
    const user = normalizeCachedAuthUser(candidate);
    if (user) return user;
  }
  return null;
}

function getSupabaseAuthLocalStorageKeys() {
  const keys = [];
  const ref = rankedCoachSupabaseAuthOrigin
    ? rankedCoachSupabaseAuthOrigin.replace(/^https?:\/\//, "").split(".")[0]
    : "";
  if (ref) keys.push(`sb-${ref}-auth-token`);
  try {
    for (let index = 0; index < localStorage.length; index += 1) {
      const key = localStorage.key(index) || "";
      if (!key || keys.includes(key)) continue;
      if (/^sb-[a-z0-9]+-auth-token$/i.test(key) || key.includes("-auth-token")) keys.push(key);
    }
  } catch (_error) {
    // Local storage may be unavailable in hardened/private contexts.
  }
  return keys;
}

function readCachedAuthUserFromLocalStorage() {
  const keys = [STORAGE_KEY_LAST_AUTH_USER, ...getSupabaseAuthLocalStorageKeys()];
  for (const key of keys) {
    try {
      const raw = localStorage.getItem(key);
      if (!raw) continue;
      const parsed = JSON.parse(raw);
      const user = key === STORAGE_KEY_LAST_AUTH_USER
        ? extractCachedAuthUserFromPayload(parsed) || normalizeCachedAuthUser(parsed)
        : extractCachedAuthUserFromPayload(parsed);
      if (user) return { user, source: key };
    } catch (_error) {
      // Ignore stale or non-JSON values and keep checking other known keys.
    }
  }
  return null;
}

function cacheLastKnownAuthUser(user = null) {
  const normalized = normalizeCachedAuthUser(user);
  if (!normalized) return;
  try {
    localStorage.setItem(STORAGE_KEY_LAST_AUTH_USER, JSON.stringify({
      user: normalized,
      cachedAt: nowISO()
    }));
  } catch (_error) {
    // Auth cache is a convenience fallback; never block real auth on it.
  }
}

function clearLastKnownAuthUser() {
  try {
    localStorage.removeItem(STORAGE_KEY_LAST_AUTH_USER);
  } catch (_error) {
    // Ignore local storage failures.
  }
}

function withAuthRequestTimeout(request, options = {}) {
  const timeoutMs = Math.max(250, Number(options.timeoutMs) || AUTH_ACTION_TIMEOUT_MS);
  const label = options.label || "Auth request";
  const controller = typeof AbortController === "function" ? new AbortController() : null;
  const abortSignal = controller?.signal || null;
  if (controller) rankedCoachActiveAuthControllers.add(controller);
  return new Promise((resolve, reject) => {
    let settled = false;
    const cleanup = () => {
      window.clearTimeout(timer);
      if (controller) rankedCoachActiveAuthControllers.delete(controller);
    };
    const timer = window.setTimeout(() => {
      if (settled) return;
      settled = true;
      const timeoutError = createAuthTimeoutError(label, timeoutMs);
      abortRankedCoachActiveAuthControllers(timeoutError);
      cleanup();
      reject(timeoutError);
    }, timeoutMs);
    const runRequest = () => {
      const runner = typeof request === "function" ? request : () => request;
      if (!abortSignal) return runner({});
      rankedCoachAuthAbortSignalStack.push(abortSignal);
      try {
        return runner({ signal: abortSignal, abortSignal, controller });
      } finally {
        rankedCoachAuthAbortSignalStack.pop();
      }
    };
    Promise.resolve()
      .then(runRequest)
      .then(value => {
        if (settled) return;
        settled = true;
        cleanup();
        resolve(value);
      })
      .catch(error => {
        if (settled) return;
        settled = true;
        cleanup();
        reject(error);
      });
  });
}

async function runAuthRequestWithTimeout(request, options = {}) {
  try {
    return await withAuthRequestTimeout(request, options);
  } catch (error) {
    if (isAbortError(error) && isAuthReachabilityOfflineCooldownActive()) {
      return { data: null, error: null };
    }
    if (isAuthTimeoutError(error)) {
      markAuthReachabilityOffline(error.timeoutMs);
      console.warn(`${options.label || "Auth request"} timed out`, {
        timeoutMs: error.timeoutMs,
        reason: options.reason || ""
      });
      notifyAuthReachabilityIssue(options.playerMessage || error.playerMessage, options);
    }
    throw error;
  }
}

async function getSupabaseUser(options = {}) {
  if (!supabaseClient?.auth?.getUser) return null;
  if (shouldSkipAuthRequestForOfflineCooldown(options)) return null;
  const result = await runAuthRequestWithTimeout(
    () => supabaseClient.auth.getUser(),
    {
      label: options.label || "Supabase auth user check",
      reason: options.reason || "get-user",
      timeoutMs: options.timeoutMs || AUTH_ACTION_TIMEOUT_MS,
      playerMessage: options.playerMessage || "Having trouble reaching your account right now — continuing with your local data.",
      silent: options.silent === true
    }
  );
  const error = result?.error || null;
  if (error) {
    backendSyncState.lastError = error;
    return null;
  }
  return result?.data?.user || null;
}

async function getSupabaseSession(options = {}) {
  if (!supabaseClient?.auth?.getSession) return null;
  if (shouldSkipAuthRequestForOfflineCooldown(options)) return null;
  const result = await runAuthRequestWithTimeout(
    () => supabaseClient.auth.getSession(),
    {
      label: options.label || "Supabase cached session check",
      reason: options.reason || "get-session",
      timeoutMs: options.timeoutMs || AUTH_INIT_TIMEOUT_MS,
      playerMessage: options.playerMessage || "Having trouble reaching your account right now — continuing with your local data.",
      silent: options.silent === true
    }
  );
  const error = result?.error || null;
  if (error) {
    backendSyncState.lastError = error;
    return null;
  }
  return result?.data?.session || null;
}

function readInsightFeedbackEntries() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY_INSIGHT_FEEDBACK);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch (_error) {
    return [];
  }
}

function saveInsightFeedbackEntries(options = {}) {
  try {
    localStorage.setItem(STORAGE_KEY_INSIGHT_FEEDBACK, JSON.stringify(insightFeedbackEntries || []));
  } catch (error) {
    console.warn("Unable to save local insight feedback", error);
  }

  if (!options.skipBackend) {
    queuePersistentAccountSave("insight-feedback");
  }
}

function getInsightSignature(insight = {}) {
  return [
    insight.title,
    insight.type,
    insight.focus,
    insight.what,
    insight.action
  ]
    .map(part => String(part || "").trim().toLowerCase())
    .filter(Boolean)
    .join("|")
    .slice(0, 420);
}

function getLatestInsightFeedback(signature = "") {
  const key = String(signature || "").trim();
  if (!key) return null;
  return (insightFeedbackEntries || [])
    .slice()
    .reverse()
    .find(entry => entry.signature === key) || null;
}

function recordInsightFeedback(insight = {}, rating = "helpful") {
  const signature = getInsightSignature(insight);
  if (!signature) return null;

  const model = getPlayerModel();
  const entry = {
    id: uuid(),
    signature,
    rating,
    title: insight.title || "",
    type: insight.type || "",
    focus: insight.focus || model?.focus || "",
    priority: safeNumber(insight.priority),
    confidenceScore: safeNumber(model?.confidenceScore),
    currentAct: model?.currentAct || "Current Window",
    profileId: activeProfileId || "",
    sourceCount: Array.isArray(insight.sources) ? insight.sources.length : 0,
    context: {
      matchesPlayed: safeNumber(model?.overview?.matchesPlayed),
      winrate: safeNumber(model?.overview?.winrate),
      kd: safeNumber(model?.overview?.kd),
      bestAgent: model?.agents?.[0]?.agent || "",
      strongestMap: model?.maps?.[0]?.map || "",
      weaponReliance: model?.coachingContext?.relianceFlags || []
    },
    createdAt: nowISO()
  };

  insightFeedbackEntries = [
    ...(insightFeedbackEntries || []).filter(item => item.signature !== signature),
    entry
  ].slice(-300);
  saveInsightFeedbackEntries();
  return entry;
}

function getInsightFeedbackSummary() {
  const entries = insightFeedbackEntries || [];
  const helpful = entries.filter(entry => entry.rating === "helpful").length;
  const inaccurate = entries.filter(entry => entry.rating === "inaccurate").length;
  return {
    total: entries.length,
    helpful,
    inaccurate,
    helpfulRate: entries.length ? safeDivide(helpful * 100, entries.length) : 0
  };
}

function getLogEntriesStorageKey(user = currentAuthUser) {
  const owner = String(user?.id || "guest").replace(/[^a-z0-9_-]/gi, "_");
  return `${STORAGE_KEY_LOG_ENTRIES}:${owner}`;
}

function sanitizeStoredLogEntries(entries = [], options = {}) {
  return globalThis.RankedCoachLogPolicy?.sanitizeLogEntries?.(entries, {
    signedIn: options.signedIn ?? Boolean(currentAuthUser),
    profileId: options.profileId || activeProfileId || getActiveProfile?.()?.id || ""
  }) || (Array.isArray(entries) ? entries : []);
}

function isPlayerAuthoredLogEntry(entry = {}) {
  return globalThis.RankedCoachLogPolicy?.isPlayerAuthored?.(entry) !== false;
}

function isMatchPlaceholderLogEntry(entry = {}) {
  return globalThis.RankedCoachLogPolicy?.isMatchPlaceholder?.(entry) === true;
}

function getProfileLogEntries(profileId = activeProfileId, options = {}) {
  const targetProfileId = String(profileId || "").trim();
  return (logEntries || []).filter(entry => {
    const entryProfileId = String(entry?.profileId || "").trim();
    if (targetProfileId && !entryProfileId) return false;
    if (targetProfileId && entryProfileId !== targetProfileId) return false;
    return options.authoredOnly ? isPlayerAuthoredLogEntry(entry) : true;
  });
}

function getMatchPlaceholderTimestamp(match = {}) {
  // Do not use getMatchCore here: its display-friendly fallback is `nowISO()`,
  // which would incorrectly turn an undated historical record into a new
  // reflection prompt.
  const rawDate = match?.matchRecord?.playedAt
    || match?.matchRecord?.createdAt
    || match?.metadata?.playedAt
    || match?.metadata?.createdAt
    || match?.playedAt
    || match?.createdAt
    || "";
  const timestamp = new Date(rawDate).getTime();
  return Number.isFinite(timestamp) ? timestamp : 0;
}

function isRecentRankedMatchForPlaceholder(match = {}, options = {}) {
  if (!isRankedPerformanceMatch(match)) return false;
  const windowDays = Math.max(
    1,
    Math.min(90, safeNumber(options.placeholderWindowDays, RANKED_MATCH_PLACEHOLDER_WINDOW_DAYS))
  );
  const cutoff = Date.now() - (windowDays * 86400000);
  return getMatchPlaceholderTimestamp(match) >= cutoff;
}

function syncRankedMatchPlaceholderLogs(matchList = [], profile = getActiveProfile(), options = {}) {
  const policy = globalThis.RankedCoachLogPolicy;
  const profileId = String(profile?.id || "").trim();
  if (!policy?.syncMatchPlaceholders || !profileId) return 0;
  const existingEntryIds = new Set((logEntries || []).map(entry => String(entry?.id || "")).filter(Boolean));

  const placeholderMatches = (Array.isArray(matchList) ? matchList : [])
    // Stats retain the complete upstream archive. Logging only creates a
    // reflection prompt for recent games, so a historical backfill cannot
    // flood the player with hundreds of unsolicited cards.
    .filter(match => isRecentRankedMatchForPlaceholder(match, options))
    .map(match => {
    const core = getMatchCore(match);
    const seasonIdentity = getMatchSeasonIdentity(match);
    const placeholderRr = isVerifiedHenrikRrMatch(match)
      ? getOptionalFiniteNumber(match?.verifiedRrDelta ?? match?.matchRecord?.rank?.rrDelta ?? match?.rr)
      : getOptionalFiniteNumber(match?.rr);
    return {
      id: match?.matchId || match?.id || match?.metadata?.matchId || "",
      createdAt: core.createdAt || match?.createdAt || match?.metadata?.playedAt || "",
      result: core.result || match?.result || match?.metadata?.result || "",
      rr: Number.isFinite(placeholderRr) ? placeholderRr : null,
      isPlacementMatch: isPlacementRankedMatch(match),
      agent: core.agent,
      role: core.role,
      map: core.map,
      seasonKey: seasonIdentity?.key || "",
      act: seasonIdentity?.label || "",
      roleImpact: buildStoredRoleImpactSnapshot(match, profile?.trackerAnalytics || null)
    };
  });
  const synced = policy.syncMatchPlaceholders(logEntries, placeholderMatches, profileId, {
    pendingLoadoutRoll: getPendingLoadoutRoll(profile)
  });
  logEntries = sanitizeStoredLogEntries(synced.entries, {
    signedIn: Boolean(currentAuthUser),
    profileId
  });
  if (synced.added > 0 || synced.reconciled > 0) {
    const changedEntryIds = logEntries
      .filter(entry => String(entry?.profileId || "") === profileId)
      .filter(entry => {
        const entryId = String(entry?.id || "");
        return !existingEntryIds.has(entryId)
          || (synced.reconciledEntryIds || []).includes(entryId);
      })
      .map(entry => entry.id);
    markPersistentLogRowsDirty(changedEntryIds);
  }
  if (!options.skipSave && options.animate !== false && (synced.added > 0 || synced.reconciled > 0)) {
    const reconciledEntryIds = new Set(synced.reconciledEntryIds || []);
    logEntries
      .filter(entry => String(entry?.profileId || "") === profileId)
      .filter(entry => entry?.id && (
        !existingEntryIds.has(String(entry.id)) ||
        reconciledEntryIds.has(String(entry.id))
      ))
      .forEach(entry => queueLoggingEntryReveal(entry.id, "sync"));
  }
  if (!options.skipSave) {
    saveLogEntries({ skipBackend: options.skipBackend === true });
  }
  return synced.added;
}

function shouldSyncStatsLoggingParityForProfile(profile = {}, options = {}) {
  if (!profile || typeof profile !== "object") return false;
  if (options.syncPlaceholders === false) return false;
  const source = [options.source, profile.lastSyncSource, profile.importSource]
    .map(value => String(value || "").toLowerCase())
    .join(" ");
  if (source.includes("demo")) return false;
  if (profile.isDemoProfile === true || profile.demoProfile === true) return false;
  return Boolean(String(profile.id || "").trim());
}

function commitProfileMatchesWithLoggingParity(profile, nextMatches = [], options = {}) {
  if (!profile || typeof profile !== "object") return [];
  const previousMatches = Array.isArray(profile.matches) ? profile.matches.slice() : [];
  const committed = (Array.isArray(nextMatches) ? nextMatches : []).filter(Boolean);
  profile.matches = committed.slice();
  markChangedPersistentMatchRows(profile, previousMatches, committed);
  if (String(profile.id || "") === String(activeProfileId || "")) {
    matches = committed.slice();
  }
  if (shouldSyncStatsLoggingParityForProfile(profile, options)) {
    syncRankedMatchPlaceholderLogs(committed, profile, {
      animate: options.animatePlaceholders !== false,
      skipBackend: options.skipBackend === true,
      skipSave: options.skipLogSave === true
    });
  }
  return committed;
}

function repairStatsLoggingParityForProfiles(profileList = profiles, options = {}) {
  if (!Array.isArray(profileList) || !profileList.length) return 0;
  const beforeRepair = options.skipSave === true ? "" : JSON.stringify(logEntries || []);
  let added = 0;
  profileList.forEach(profile => {
    if (!shouldSyncStatsLoggingParityForProfile(profile, options)) return;
    const profileMatches = Array.isArray(profile?.matches) ? profile.matches : [];
    if (!profileMatches.length) return;
    added += syncRankedMatchPlaceholderLogs(profileMatches, profile, {
      animate: false,
      skipSave: true
    }) || 0;
  });
  const changed = options.skipSave !== true && (added > 0 || beforeRepair !== JSON.stringify(logEntries || []));
  if (changed) {
    saveLogEntries({ skipBackend: options.skipBackend === true });
  }
  return added;
}

function hasPlayerReflectionDraft() {
  if (editingLogEntryId) return true;
  if (selectedLogRating != null || selectedLogMood || selectedLogTeamComms != null || selectedLogSelfComms != null) return true;
  const values = [
    document.getElementById("logNotes")?.value,
    document.getElementById("logFocusSelect")?.value
  ];
  return values.some(value => {
    const cleaned = String(value || "").trim();
    return cleaned && !["select focus", "other"].includes(cleaned.toLowerCase());
  });
}

function prefillLatestImportedReflection(options = {}) {
  const profileId = String(options.profileId || activeProfileId || "").trim();
  if (!profileId || hasPlayerReflectionDraft()) return null;
  const today = formatLocalDateKey(new Date());
  const latest = getProfileLogEntries(profileId)
    .filter(entry => isMatchPlaceholderLogEntry(entry) && getTrainingEntryDate(entry) === today)
    .sort((a, b) => new Date(b?.createdAt || 0).getTime() - new Date(a?.createdAt || 0).getTime())[0] || null;
  if (!latest) return null;
  activeLogSessionFilter = today;
  editLogEntry(latest.id, { scroll: false });
  if (options.animate !== false) {
    window.setTimeout(() => animatePostgameAutofillFields(null, { entry: latest }), 80);
  }
  return latest;
}

function readLocalLogEntries(options = {}) {
  try {
    const storageKey = getLogEntriesStorageKey(options.user ?? currentAuthUser);
    const legacyRaw = !currentAuthUser ? localStorage.getItem(STORAGE_KEY_LOG_ENTRIES_LEGACY) : null;
    const raw = localStorage.getItem(storageKey) || legacyRaw;
    const parsed = raw ? JSON.parse(raw) : [];
    return sanitizeStoredLogEntries(parsed, {
      signedIn: options.signedIn ?? Boolean(currentAuthUser),
      profileId: options.profileId
    });
  } catch (_error) {
    return [];
  }
}

function saveLogEntries(options = {}) {
  logEntries = sanitizeStoredLogEntries(logEntries, {
    signedIn: Boolean(currentAuthUser),
    profileId: activeProfileId
  });
  try {
    localStorage.setItem(getLogEntriesStorageKey(), JSON.stringify(logEntries || []));
    if (currentAuthUser) localStorage.removeItem(STORAGE_KEY_LOG_ENTRIES_LEGACY);
  } catch (error) {
    console.warn("Unable to save local log cache", error);
  }

  if (!options.skipBackend) {
    queuePersistentAccountSave("logs");
  }
}

function compactProfilesForCloudAccountState(source = []) {
  const normalized = (Array.isArray(source) ? source : []).map(normalizeProfileRecord);
  return globalThis.RankedCoachPersistencePolicy?.compactProfilesForCloudAccountState?.(normalized)
    || normalized.map(profile => ({ ...profile, matches: [] }));
}

function serializePersistentAccountState(options = {}) {
  const normalizedProfiles = (profiles || []).map(normalizeProfileRecord);
  return {
    schemaVersion: 1,
    savedAt: nowISO(),
    activeProfileId,
    profiles: options.cloudAccountState ? compactProfilesForCloudAccountState(normalizedProfiles) : normalizedProfiles,
    logEntries: logEntries || [],
    insightFeedbackEntries: insightFeedbackEntries || [],
    themeBuilderState: THEME_BUILDER_LAUNCH_LOCKED ? {} : (typeof themeBuilderState !== "undefined" ? themeBuilderState : {}),
    themeBuilderUiState: THEME_BUILDER_LAUNCH_LOCKED ? {} : (typeof themeBuilderUiState !== "undefined" ? themeBuilderUiState : {}),
    currentThemeKey: getActiveProfile()?.themeKey || getCurrentThemeBuilderThemeKey?.() || "default"
  };
}

function measurePersistentJsonPayloadBytes(value) {
  const policyMeasure = globalThis.RankedCoachPersistencePolicy?.measureJsonPayloadBytes;
  if (typeof policyMeasure === "function") return policyMeasure(value);
  let json = "";
  try {
    json = JSON.stringify(value ?? null);
  } catch (_error) {
    return 0;
  }
  if (typeof TextEncoder === "function") {
    try {
      return new TextEncoder().encode(json).length;
    } catch (_error) {
      return json.length;
    }
  }
  return json.length;
}

function summarizePersistentAccountSaveMetrics(input = {}) {
  const state = input.state || {};
  const fullState = input.fullState || state;
  const activeProfile = input.activeProfile || null;
  const compactActiveProfile = input.compactActiveProfile || null;
  const logRows = Array.isArray(input.logRows) ? input.logRows : [];
  const matchRows = Array.isArray(input.matchRows) ? input.matchRows : [];
  const totalLogRows = Math.max(0, safeNumber(input.totalLogRows, logRows.length));
  const totalMatchRows = Math.max(0, safeNumber(input.totalMatchRows, matchRows.length));
  const shouldMeasureFullArchive = input.measureFullArchive === true;
  const fullProfilesBytes = shouldMeasureFullArchive
    ? measurePersistentJsonPayloadBytes(fullState.profiles || [])
    : null;
  const cloudProfilesBytes = measurePersistentJsonPayloadBytes(state.profiles || []);
  return {
    reason: input.reason || "state",
    profiles: Array.isArray(state.profiles) ? state.profiles.length : 0,
    logRows: logRows.length,
    matchRows: matchRows.length,
    totalLogRows,
    totalMatchRows,
    skippedLogRows: Math.max(0, totalLogRows - logRows.length),
    skippedMatchRows: Math.max(0, totalMatchRows - matchRows.length),
    fullProfilesBytes,
    cloudProfilesBytes,
    cloudProfilesReductionBytes: Number.isFinite(fullProfilesBytes)
      ? Math.max(0, fullProfilesBytes - cloudProfilesBytes)
      : null,
    activeProfileBytes: measurePersistentJsonPayloadBytes(activeProfile || {}),
    compactActiveProfileBytes: measurePersistentJsonPayloadBytes(compactActiveProfile || {}),
    appStatePayloadBytes: measurePersistentJsonPayloadBytes({
      active_profile_id: activeProfileId || null,
      profiles_json: state.profiles || [],
      log_entries_json: state.logEntries || [],
      theme_builder_json: state.themeBuilderState || {},
      theme_builder_ui_json: state.themeBuilderUiState || {},
      current_theme_key: state.currentThemeKey || "default"
    }),
    logRowsPayloadBytes: measurePersistentJsonPayloadBytes(logRows),
    matchRowsPayloadBytes: measurePersistentJsonPayloadBytes(matchRows)
  };
}

function getPersistentSupabaseErrorDetails(error, extra = {}) {
  const normalized = error && typeof error === "object" ? error : {};
  return {
    ...extra,
    name: normalized.name || "",
    code: normalized.code || normalized.statusCode || "",
    message: normalized.message || String(error || "Unknown Supabase error"),
    details: normalized.details || "",
    hint: normalized.hint || "",
    status: normalized.status || normalized.statusCode || normalized.cause?.status || "",
    statusText: normalized.statusText || normalized.cause?.statusText || ""
  };
}

function notifyPersistentAccountSaveIssue(details = {}) {
  const now = Date.now();
  if (now - persistentAccountSaveNoticeLastShownAt < 30000) return;
  persistentAccountSaveNoticeLastShownAt = now;
  showToast("RankedCoach kept your changes locally and will keep retrying cloud save in the background.", {
    title: "Cloud save delayed",
    variant: "warning",
    durationMs: 4800
  });
}

function schedulePersistentAccountSaveRetry(reason = "cloud-save-retry") {
  if (persistentAccountSaveRetryTimer) return;
  persistentAccountSaveRetryTimer = window.setTimeout(() => {
    persistentAccountSaveRetryTimer = 0;
    queuePersistentAccountSave(reason);
  }, 12000);
}

function reportPersistentAccountSaveFailure(label, error, extra = {}) {
  const details = getPersistentSupabaseErrorDetails(error, extra);
  backendSyncState.lastError = error || details;
  backendSyncState.lastSaveFailures = [
    ...(Array.isArray(backendSyncState.lastSaveFailures) ? backendSyncState.lastSaveFailures : []),
    details
  ].slice(-12);
  console.warn(label, details);
  notifyPersistentAccountSaveIssue(details);
  publishRankedCoachSyncDiagnostics?.("cloud-save-failed");
  return details;
}

function mergePersistentRowsById(left = [], right = []) {
  const merged = new Map();
  [...(Array.isArray(left) ? left : []), ...(Array.isArray(right) ? right : [])].forEach((item, index) => {
    if (!item || typeof item !== "object") return;
    const key = String(item.id || item.matchId || item.metadata?.matchId || `row-${index}`).trim();
    merged.set(key, item);
  });
  return [...merged.values()];
}

function mergePersistentAccountStateWithNormalizedTables(appState = {}, normalizedState = null) {
  if (!normalizedState || typeof normalizedState !== "object") return appState;
  const appProfiles = Array.isArray(appState.profiles) ? appState.profiles : [];
  const normalizedProfiles = Array.isArray(normalizedState.profiles) ? normalizedState.profiles : [];
  const normalizedById = new Map(normalizedProfiles.map(profile => [String(profile?.id || ""), profile]));
  const seenProfileIds = new Set();
  const mergedProfiles = appProfiles.map(profile => {
    const profileId = String(profile?.id || "");
    seenProfileIds.add(profileId);
    const recovered = normalizedById.get(profileId);
    if (!recovered) return profile;
    const recoveredMatches = Array.isArray(recovered.matches) ? recovered.matches : [];
    const appMatches = Array.isArray(profile.matches) ? profile.matches : [];
    return {
      ...recovered,
      ...profile,
      matches: recoveredMatches.length ? recoveredMatches : appMatches
    };
  });
  normalizedProfiles.forEach(profile => {
    const profileId = String(profile?.id || "");
    if (!profileId || seenProfileIds.has(profileId)) return;
    mergedProfiles.push(profile);
  });
  return {
    ...appState,
    activeProfileId: appState.activeProfileId || normalizedState.activeProfileId,
    profiles: mergedProfiles.length ? mergedProfiles : normalizedProfiles,
    logEntries: mergePersistentRowsById(appState.logEntries, normalizedState.logEntries)
  };
}

function applyPersistentAccountState(state = {}) {
  if (!state || typeof state !== "object") return;

  let shouldPersistMergedPlaylistWatchHistory = false;
  backendSyncState.applyingRemote = true;
  try {
    if (Array.isArray(state.profiles) && state.profiles.length) {
      const remoteProfiles = mergeLocalPlaylistWatchHistoryIntoRemoteProfiles(state.profiles);
      const remoteHistoryByIdentity = new Map((state.profiles || []).map(profile => [
        getPlaylistWatchHistoryProfileIdentity(profile),
        normalizeWatchedPlaylistVideos(profile?.watchedPlaylistVideos)
      ]));
      shouldPersistMergedPlaylistWatchHistory = remoteProfiles.some(profile => {
        const identity = getPlaylistWatchHistoryProfileIdentity(profile);
        return JSON.stringify(normalizeWatchedPlaylistVideos(profile?.watchedPlaylistVideos))
          !== JSON.stringify(remoteHistoryByIdentity.get(identity) || []);
      });
      const consolidated = globalThis.RankedCoachPersistencePolicy?.consolidateProfiles?.(
        remoteProfiles,
        state.activeProfileId
      ) || { profiles: remoteProfiles, activeProfileId: state.activeProfileId, idMap: {} };
      profiles = consolidated.profiles.map(profile => {
        const normalized = normalizeProfileRecord(profile);
        hydratePendingLoadoutRoll(normalized);
        return normalized;
      });
      activeProfileId = consolidated.activeProfileId || profiles[0]?.id || activeProfileId;
      persistProfilesToLocalCache();
      if (Array.isArray(state.logEntries)) {
        state = {
          ...state,
          logEntries: state.logEntries.map(entry => ({
            ...entry,
            profileId: consolidated.idMap?.[String(entry?.profileId || "")] || entry?.profileId
          }))
        };
      }
    }

    if (Array.isArray(state.logEntries)) {
      logEntries = sanitizeStoredLogEntries(state.logEntries, {
        signedIn: true,
        profileId: activeProfileId
      });
      saveLogEntries({ skipBackend: true });
    }

    if (Array.isArray(state.insightFeedbackEntries)) {
      const mergedFeedback = new Map();
      [...readInsightFeedbackEntries(), ...state.insightFeedbackEntries].forEach((entry) => {
        if (!entry || typeof entry !== "object") return;
        const id = String(entry.id || uuid());
        mergedFeedback.set(id, { ...entry, id });
      });
      insightFeedbackEntries = [...mergedFeedback.values()]
        .sort((a, b) => new Date(a?.createdAt || 0).getTime() - new Date(b?.createdAt || 0).getTime())
        .slice(-300);
      saveInsightFeedbackEntries({ skipBackend: true });
    }

    if (state.themeBuilderState && typeof state.themeBuilderState === "object" && typeof themeBuilderState !== "undefined") {
      if (THEME_BUILDER_LAUNCH_LOCKED) {
        archiveThemeBuilderLocalStorageForLaunchLock();
      } else {
      const mergedThemeBuilderState = mergeLocalAndRemoteThemeBuilderState(
        themeBuilderState,
        state.themeBuilderState
      );
      themeBuilderState = normalizeLoadedThemeBuilderState(
        mergeBakedThemeBuilderState(mergedThemeBuilderState)
      );
      localStorage.setItem(THEME_BUILDER_STORAGE_KEY, JSON.stringify(themeBuilderState));
      applyThemeBuilderFontImports?.();
      applyThemeBuilderRuntimeStyles?.();
      }
    }

    repairStatsLoggingParityForProfiles(profiles, {
      source: "remote-state",
      skipBackend: true
    });

    const active = getActiveProfile();
    matches = active?.matches ? active.matches.slice() : [];
    recomputeFromMatches?.();
    renderProfilesUI?.();
    rebuildProfileListUI?.();
    updateProfileHeaderUI?.();
    updateDisplays?.();
    applyPendingLoadoutRollToHome?.(active);
    initStatsPage?.();
    renderStatsAgents?.();
    renderStatsMaps?.();
    renderStatsWeapons?.();
    renderInsights?.();
    renderLogFeed?.();
    refreshLatestRRMatchPanel?.();
    renderChart?.(currentSize);
    syncAccountSupportUI?.();
    notifyPlaylistWatchHistoryChanged();
  } finally {
    backendSyncState.applyingRemote = false;
  }
  if (shouldPersistMergedPlaylistWatchHistory) {
    queuePersistentAccountSave("playlist-watch-history-merge");
  }
}

function getLoadedRankedCoachScriptVersion() {
  const script = Array.from(document.scripts || [])
    .map(item => item?.getAttribute?.("src") || item?.src || "")
    .find(src => /(?:^|\/)app\.js(?:\?|$)/i.test(src));
  if (!script) return RANKEDCOACH_APP_BUILD_ID;
  try {
    const url = new URL(script, window.location.href);
    return url.searchParams.get("v") || RANKEDCOACH_APP_BUILD_ID;
  } catch (_error) {
    const match = String(script || "").match(/[?&]v=([^&]+)/i);
    return match ? decodeURIComponent(match[1]) : RANKEDCOACH_APP_BUILD_ID;
  }
}

function noteRankedCoachLoadedBuild() {
  try {
    const previous = localStorage.getItem(STORAGE_KEY_LAST_SEEN_APP_BUILD) || "";
    if (previous && previous !== RANKEDCOACH_APP_BUILD_ID) {
      showToast("The newest RankedCoach build is now loaded.", {
        title: "App update applied",
        variant: "success",
        durationMs: 3200
      });
    }
    localStorage.setItem(STORAGE_KEY_LAST_SEEN_APP_BUILD, RANKEDCOACH_APP_BUILD_ID);
  } catch (_error) {
    // Local build tracking is best-effort only.
  }
}

async function checkRankedCoachAppUpdate(options = {}) {
  if (rankedCoachAppUpdateCheckInFlight) return;
  const minInterval = options.force ? 0 : 5 * 60 * 1000;
  if (!options.force && rankedCoachLastAppUpdateCheckAt && Date.now() - rankedCoachLastAppUpdateCheckAt < minInterval) return;
  rankedCoachAppUpdateCheckInFlight = true;
  rankedCoachLastAppUpdateCheckAt = Date.now();
  try {
    const response = await fetch(`./?rankedcoach-update-check=${Date.now()}`, {
      cache: "no-store",
      credentials: "same-origin"
    });
    const html = await response.text();
    const match = html.match(/app\.js\?v=([^"'<>\s]+)/i);
    const remoteVersion = match ? decodeURIComponent(match[1]) : "";
    const loadedVersion = getLoadedRankedCoachScriptVersion();
    if (remoteVersion && loadedVersion && remoteVersion !== loadedVersion && !rankedCoachAppUpdateNoticeShown) {
      rankedCoachAppUpdateNoticeShown = true;
      setAppLoadingEventBanner("update");
      showToast("Refresh when ready to load the newest RankedCoach build.", {
        title: "App update available",
        variant: "warning",
        durationMs: 4200
      });
    }
  } catch (error) {
    console.warn("RankedCoach update check failed", error);
  } finally {
    rankedCoachAppUpdateCheckInFlight = false;
  }
}

function startRankedCoachAppUpdateChecks() {
  if (rankedCoachAppUpdateCheckTimer) return;
  rankedCoachAppUpdateCheckTimer = window.setInterval(() => {
    if (document.visibilityState === "visible") void checkRankedCoachAppUpdate();
  }, 5 * 60 * 1000);
}

function teardownPersistentAccountRealtime() {
  if (persistentAccountRealtimeReloadTimer) {
    window.clearTimeout(persistentAccountRealtimeReloadTimer);
    persistentAccountRealtimeReloadTimer = 0;
  }
  const channel = persistentAccountRealtimeChannel;
  persistentAccountRealtimeChannel = null;
  persistentAccountRealtimeUserId = "";
  if (channel && supabaseClient?.removeChannel) {
    try {
      void supabaseClient.removeChannel(channel);
    } catch (error) {
      console.warn("Supabase realtime unsubscribe failed", error);
    }
  } else if (channel?.unsubscribe) {
    try {
      void channel.unsubscribe();
    } catch (error) {
      console.warn("Supabase realtime unsubscribe failed", error);
    }
  }
  publishRankedCoachSyncDiagnostics?.("realtime-disconnected");
}

function notifyPersistentAccountRealtimeIssue(status = "") {
  if (persistentAccountRealtimeNoticeShown) return;
  persistentAccountRealtimeNoticeShown = true;
  console.warn("Supabase realtime subscription unavailable", status);
  showToast("Live cross-device sync could not stay connected. RankedCoach will keep checking in the background.", {
    title: "Live sync unavailable",
    variant: "warning",
    durationMs: 4200
  });
}

function getRankedCoachSyncDiagnostics() {
  const profile = getActiveProfile?.();
  const signedIn = Boolean(currentAuthUser?.id);
  const activeUserId = String(currentAuthUser?.id || "").trim();
  const realtimeSubscribed = Boolean(
    signedIn
    && persistentAccountRealtimeChannel
    && persistentAccountRealtimeUserId
    && persistentAccountRealtimeUserId === activeUserId
  );
  const hasRiotId = Boolean(String(profile?.riotId || "").trim());
  return {
    mode: signedIn ? "signed-in" : "guest",
    signedIn,
    guestMode: !signedIn,
    activeUserId,
    activeProfileId: String(profile?.id || activeProfileId || "").trim(),
    riotId: String(profile?.riotId || "").trim(),
    hasRiotId,
    realtimeSubscribed,
    crossDeviceRealtimeAvailable: Boolean(signedIn && realtimeSubscribed),
    crossDeviceSyncRequiresSignIn: Boolean(!signedIn && hasRiotId),
    backendSavePending: Boolean(backendSyncState.savePromise || backendSyncState.saveTimer),
    lastBackendSaveMetrics: backendSyncState.lastSaveMetrics || null,
    lastBackendSaveFailures: Array.isArray(backendSyncState.lastSaveFailures)
      ? backendSyncState.lastSaveFailures.slice(-4)
      : [],
    lastBackendSync: (() => {
      try {
        return localStorage.getItem(STORAGE_KEY_LAST_BACKEND_SYNC) || "";
      } catch (_error) {
        return "";
      }
    })()
  };
}

function publishRankedCoachSyncDiagnostics(reason = "state") {
  const diagnostics = getRankedCoachSyncDiagnostics();
  diagnostics.reason = reason;
  diagnostics.updatedAt = nowISO();
  globalThis.RankedCoachSyncDiagnosticsState = diagnostics;
  globalThis.RankedCoachSyncDiagnostics = {
    getMode: getRankedCoachSyncDiagnostics,
    refresh: publishRankedCoachSyncDiagnostics
  };
  const root = document.documentElement;
  const body = document.body;
  if (root) {
    root.dataset.syncMode = diagnostics.mode;
    root.dataset.syncRealtime = diagnostics.realtimeSubscribed ? "active" : "inactive";
  }
  if (body) {
    body.dataset.syncMode = diagnostics.mode;
    body.dataset.syncRealtime = diagnostics.realtimeSubscribed ? "active" : "inactive";
  }
  return diagnostics;
}

function maybeShowGuestCrossDeviceSyncNotice(options = {}) {
  const diagnostics = publishRankedCoachSyncDiagnostics("guest-riot-sync-check");
  if (!diagnostics.crossDeviceSyncRequiresSignIn) return false;
  return true;
}

function schedulePersistentAccountRealtimeReload(payload = {}) {
  const userId = String(payload?.new?.user_id || payload?.old?.user_id || "").trim();
  if (!currentAuthUser?.id || (userId && userId !== String(currentAuthUser.id))) return;
  if (backendSyncState.hydratingUserId || backendSyncState.applyingRemote) return;
  if (backendSyncState.savePromise || backendSyncState.saveTimer) {
    window.clearTimeout(persistentAccountRealtimeReloadTimer);
    persistentAccountRealtimeReloadTimer = window.setTimeout(() => schedulePersistentAccountRealtimeReload(payload), 900);
    return;
  }
  if (backendSyncState.lastLocalSaveAt && Date.now() - backendSyncState.lastLocalSaveAt < 1800) return;

  window.clearTimeout(persistentAccountRealtimeReloadTimer);
  persistentAccountRealtimeReloadTimer = window.setTimeout(async () => {
    persistentAccountRealtimeReloadTimer = 0;
    if (!currentAuthUser?.id || backendSyncState.savePromise || backendSyncState.saveTimer) return;
    const table = String(payload?.table || "").trim();
    const isMatchUpdate = table === "match_snapshots";
    setAppLoadingEventBanner(isMatchUpdate ? "game" : "cloud");
    try {
      await loadPersistentAccountState(currentAuthUser);
      refreshActiveProfileDataSurfaces?.({
        reason: "realtime-sync",
        animate: false,
        preserveActivePage: true
      });
      markAccountStateLoadComplete();
      if (isMatchUpdate) {
        showToast("New match data was pulled into this device.", {
          title: "New Game Data Detected",
          variant: "success",
          durationMs: 3600
        });
      }
    } catch (error) {
      backendSyncState.lastError = error;
      console.warn("Supabase realtime account refresh failed", error);
    }
  }, 650);
}

function subscribePersistentAccountRealtime(user = currentAuthUser) {
  const userId = String(user?.id || "").trim();
  if (!userId || !supabaseClient?.channel) {
    publishRankedCoachSyncDiagnostics?.(userId ? "realtime-unavailable" : "guest-mode");
    return;
  }
  if (persistentAccountRealtimeChannel && persistentAccountRealtimeUserId === userId) return;
  teardownPersistentAccountRealtime();
  persistentAccountRealtimeUserId = userId;
  const channel = supabaseClient.channel(`rankedcoach-account-sync-${userId}`);
  ["vip_app_state", "users_profiles", "reflection_logs", "match_snapshots"].forEach(table => {
    channel.on(
      "postgres_changes",
      { event: "*", schema: "public", table, filter: `user_id=eq.${userId}` },
      payload => schedulePersistentAccountRealtimeReload(payload)
    );
  });
  persistentAccountRealtimeChannel = channel;
  try {
    channel.subscribe(status => {
      if (status === "SUBSCRIBED") {
        persistentAccountRealtimeNoticeShown = false;
        publishRankedCoachSyncDiagnostics?.("realtime-subscribed");
      } else if (["CHANNEL_ERROR", "TIMED_OUT", "CLOSED"].includes(status)) {
        notifyPersistentAccountRealtimeIssue(status);
        publishRankedCoachSyncDiagnostics?.(`realtime-${String(status || "").toLowerCase()}`);
      }
    });
  } catch (error) {
    persistentAccountRealtimeChannel = null;
    persistentAccountRealtimeUserId = "";
    notifyPersistentAccountRealtimeIssue(error?.message || "subscribe-failed");
  }
}

function queuePersistentAccountSave(reason = "state") {
  if (backendSyncState.applyingRemote || backendSyncState.hydratingUserId || !currentAuthUser?.id || !supabaseClient?.auth) return;

  backendSyncState.lastSaveReason = reason;
  window.clearTimeout(backendSyncState.saveTimer);
  backendSyncState.saveTimer = window.setTimeout(() => {
    void savePersistentAccountState(reason);
  }, 550);
}

function buildLogRowsForSupabase(userId, options = {}) {
  const onlyRowIds = options.onlyRowIds instanceof Set ? options.onlyRowIds : null;
  return (logEntries || [])
    .filter(entry => !onlyRowIds || onlyRowIds.has(String(entry?.id || "").trim()))
    .map((entry) => ({
      id: String(entry.id || uuid()),
      user_id: userId,
      profile_id: String(entry.profileId || activeProfileId || "default"),
      match_id: entry.matchId || null,
      agent: entry.agent || null,
      role: entry.role || null,
      map: entry.map || null,
      focus: entry.focus || null,
      rating: Number.isFinite(Number(entry.rating)) ? Number(entry.rating) : null,
      mood: entry.mood || null,
      team_comms: entry.teamComms || null,
      self_comms: entry.selfComms || null,
      notes: entry.notes || "",
      warmup: Boolean(entry.warmup),
      entry_json: entry,
      created_at: entry.createdAt || nowISO(),
      updated_at: nowISO()
    }));
}

function getPersistentMatchArchiveIdentity(profile = {}, match = {}, index = 0) {
  const source = match?.source || match?.metadata?.source || profile.importSource || "app";
  const sourceKey = String(source || "").toLowerCase();
  const riotMatchId = String(
    match?.metadata?.matchId ||
    match?.matchId ||
    (sourceKey === "henrik_sync" ? match?.id : "") ||
    ""
  ).trim();
  const matchId = String(riotMatchId || match?.id || `${profile.id}_${index}`);
  return { source, riotMatchId, matchId };
}

function buildPersistentMatchArchiveRowId(userId = "", profile = {}, match = {}, index = 0) {
  const identity = getPersistentMatchArchiveIdentity(profile, match, index);
  const profileId = String(profile?.id || "default");
  return (
    globalThis.RankedCoachPersistencePolicy?.buildMatchArchiveRowId ||
    globalThis.RankedCoachPersistencePolicy?.buildScopedMatchRowId
  )?.(
    String(userId || ""),
    profileId,
    identity.matchId,
    identity.riotMatchId
  ) || `${userId}:${profileId}:${identity.matchId}`;
}

function getPersistentMatchFingerprint(match = {}) {
  try {
    return JSON.stringify(match || {});
  } catch (_error) {
    return String(match?.id || match?.matchId || "");
  }
}

function markChangedPersistentMatchRows(profile = {}, previousMatches = [], nextMatches = []) {
  const userId = String(currentAuthUser?.id || "").trim();
  if (!userId || !profile?.id) return;
  const previousByRowId = new Map((Array.isArray(previousMatches) ? previousMatches : []).map((match, index) => [
    buildPersistentMatchArchiveRowId(userId, profile, match, index),
    match
  ]));
  const changedRowIds = (Array.isArray(nextMatches) ? nextMatches : [])
    .map((match, index) => ({
      id: buildPersistentMatchArchiveRowId(userId, profile, match, index),
      match
    }))
    .filter(({ id, match }) => {
      const previous = previousByRowId.get(id);
      return !previous || (previous !== match && getPersistentMatchFingerprint(previous) !== getPersistentMatchFingerprint(match));
    })
    .map(({ id }) => id);
  markPersistentMatchRowsDirty(changedRowIds);
}

function buildMatchRowsForSupabase(userId, options = {}) {
  const rows = [];
  const onlyRowIds = options.onlyRowIds instanceof Set ? options.onlyRowIds : null;
  const sourceProfiles = Array.isArray(options.profiles) ? options.profiles : profiles;
  (sourceProfiles || []).forEach((profile) => {
    (profile.matches || []).forEach((match, index) => {
      const { source, riotMatchId } = getPersistentMatchArchiveIdentity(profile, match, index);
      const profileId = String(profile.id || "default");
      const rowId = buildPersistentMatchArchiveRowId(userId, profile, match, index);
      if (onlyRowIds && !onlyRowIds.has(rowId)) return;
      const core = getMatchCore(match);
      const rawRrChange = match?.rr;
      rows.push({
        id: rowId,
        user_id: userId,
        profile_id: profileId,
        riot_match_id: riotMatchId || null,
        source,
        map: core?.map || match?.map || match?.metadata?.map || null,
        agent: core?.agent || match?.agent || match?.metadata?.agent || null,
        role: match?.role || null,
        result: match?.result || match?.metadata?.result || null,
        rr_change: rawRrChange !== null
          && rawRrChange !== undefined
          && String(rawRrChange).trim() !== ""
          && Number.isFinite(Number(rawRrChange))
            ? Number(rawRrChange)
            : null,
        kills: Number.isFinite(core?.kills) ? core.kills : safeNumber(match?.kills, null),
        deaths: Number.isFinite(core?.deaths) ? core.deaths : safeNumber(match?.deaths, null),
        assists: Number.isFinite(core?.assists) ? core.assists : safeNumber(match?.assists, null),
        acs: Number.isFinite(core?.acs) ? core.acs : safeNumber(match?.acs, null),
        match_json: match,
        played_at: match?.createdAt || match?.metadata?.playedAt || nowISO(),
        updated_at: nowISO()
      });
    });
  });
  return globalThis.RankedCoachPersistencePolicy?.dedupeRowsById?.(rows) || rows;
}

// A signed-in device normally downloads the normalized archive before it
// writes anything. Treat those downloaded ids as the save baseline so a
// cosmetic preference change does not re-upload every retained match and log.
// Rows created locally during hydration (for example, a fresh recent-match
// reflection prompt) stay dirty and are sent on the next save.
function primeNormalizedRowSyncStateFromRemote(userId = "", normalizedState = null) {
  if (!userId || !normalizedState?.recoveredFromNormalizedTables) return;
  ensureNormalizedRowSyncState(userId);
  const remoteLogIds = new Set((normalizedState.normalizedLogRowIds || []).map(id => String(id || "").trim()).filter(Boolean));
  const remoteMatchIds = new Set((normalizedState.normalizedMatchRowIds || []).map(id => String(id || "").trim()).filter(Boolean));
  const localLogRows = buildLogRowsForSupabase(userId);
  const localMatchRows = buildMatchRowsForSupabase(userId);

  backendSyncState.pendingNormalizedLogRowIds = new Set(
    localLogRows
      .map(row => String(row?.id || "").trim())
      .filter(id => id && !remoteLogIds.has(id))
  );
  backendSyncState.pendingNormalizedMatchRowIds = new Set(
    localMatchRows
      .map(row => String(row?.id || "").trim())
      .filter(id => id && !remoteMatchIds.has(id))
  );
  backendSyncState.normalizedLogRowsInitialized = true;
  backendSyncState.normalizedMatchRowsInitialized = true;
}

async function savePersistentAccountState(reason = "state") {
  if (isAuthReachabilityOfflineCooldownActive()) {
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    schedulePersistentAccountSaveRetry?.("auth-offline-cooldown");
    return null;
  }
  if (backendSyncState.savePromise) {
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    return backendSyncState.savePromise;
  }

  const savePromise = performPersistentAccountStateSave(reason);
  backendSyncState.savePromise = savePromise;
  try {
    return await savePromise;
  } catch (error) {
    // A queued background save must never surface an uncaught rejection.
    // Keep the local write, tell the player once, and retry when the service
    // becomes reachable again.
    reportPersistentAccountSaveFailure("Persistent account save failed unexpectedly", error, { reason });
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    schedulePersistentAccountSaveRetry("cloud-save-unexpected-error");
    return false;
  } finally {
    backendSyncState.savePromise = null;
    const pendingReason = backendSyncState.pendingSaveReason;
    backendSyncState.pendingSaveReason = "";
    if (pendingReason) {
      if (isAuthReachabilityOfflineCooldownActive()) {
        backendSyncState.pendingSaveReason = pendingReason;
        schedulePersistentAccountSaveRetry?.("auth-offline-cooldown");
      } else {
        queueMicrotask(() => void savePersistentAccountState(pendingReason));
      }
    }
  }
}

async function performPersistentAccountStateSave(reason = "state") {
  if (backendSyncState.applyingRemote || backendSyncState.hydratingUserId || !currentAuthUser?.id || !supabaseClient?.auth) return;
  if (isAuthReachabilityOfflineCooldownActive()) {
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    schedulePersistentAccountSaveRetry?.("auth-offline-cooldown");
    return;
  }

  let user = null;
  try {
    user = await getSupabaseUser({ reason: "persistent-account-save" });
  } catch (error) {
    backendSyncState.lastError = error;
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    notifyAuthReachabilityIssue(getPlayerFacingAuthErrorMessage(
      error,
      "Having trouble reaching your account right now — continuing with your local data."
    ));
    schedulePersistentAccountSaveRetry("auth-save-timeout");
    publishRankedCoachSyncDiagnostics?.("cloud-save-auth-delayed");
    return false;
  }
  if (!user) {
    // getSupabaseUser returns null for a transient Supabase error response as
    // well as during the offline cooldown. Either way, the local save is safe
    // and a later retry is preferable to losing the queued cloud update.
    backendSyncState.pendingSaveReason = reason || backendSyncState.pendingSaveReason || "state";
    if (backendSyncState.lastError) {
      notifyAuthReachabilityIssue(getPlayerFacingAuthErrorMessage(
        backendSyncState.lastError,
        "Having trouble reaching your account right now — continuing with your local data."
      ));
    }
    schedulePersistentAccountSaveRetry("auth-save-unavailable");
    publishRankedCoachSyncDiagnostics?.("cloud-save-auth-unavailable");
    return false;
  }

  logEntries = sanitizeStoredLogEntries(logEntries, {
    signedIn: true,
    profileId: activeProfileId
  });

  ensureNormalizedRowSyncState(user.id);
  const cloudState = serializePersistentAccountState({ cloudAccountState: true });
  const active = getActiveProfile();
  const compactActiveProfile = active ? compactProfilesForCloudAccountState([active])[0] || null : null;
  const totalLogRows = (logEntries || []).length;
  const totalMatchRows = (profiles || []).reduce((sum, profile) => sum + (Array.isArray(profile?.matches) ? profile.matches.length : 0), 0);
  const logRowIdsToSave = backendSyncState.normalizedLogRowsInitialized
    ? new Set(backendSyncState.pendingNormalizedLogRowIds)
    : null;
  const matchRowIdsToSave = backendSyncState.normalizedMatchRowsInitialized
    ? new Set(backendSyncState.pendingNormalizedMatchRowIds)
    : null;
  const logRows = buildLogRowsForSupabase(user.id, { onlyRowIds: logRowIdsToSave });
  const matchRows = buildMatchRowsForSupabase(user.id, { onlyRowIds: matchRowIdsToSave });
  const saveMetrics = summarizePersistentAccountSaveMetrics({
    reason,
    state: cloudState,
    activeProfile: active,
    compactActiveProfile,
    logRows,
    matchRows,
    totalLogRows,
    totalMatchRows
  });
  backendSyncState.lastSaveMetrics = saveMetrics;
  backendSyncState.lastSaveFailures = [];
  let allWritesSaved = true;

  const { error: appStateError } = await supabaseClient
    .from("vip_app_state")
    .upsert({
      user_id: user.id,
      active_profile_id: activeProfileId || null,
      profiles_json: cloudState.profiles,
      log_entries_json: cloudState.logEntries,
      theme_builder_json: cloudState.themeBuilderState,
      theme_builder_ui_json: cloudState.themeBuilderUiState,
      current_theme_key: cloudState.currentThemeKey,
      last_save_reason: reason,
      updated_at: nowISO()
    }, { onConflict: "user_id" });

  if (appStateError) {
    allWritesSaved = false;
    reportPersistentAccountSaveFailure("Supabase app-state save failed", appStateError, {
      table: "vip_app_state",
      operation: "upsert",
      reason,
      appStatePayloadBytes: saveMetrics.appStatePayloadBytes,
      cloudProfilesBytes: saveMetrics.cloudProfilesBytes,
      fullProfilesBytes: saveMetrics.fullProfilesBytes,
      cloudProfilesReductionBytes: saveMetrics.cloudProfilesReductionBytes
    });
  }

  if (active) {
    const { error: profileError } = await supabaseClient
      .from("users_profiles")
      .upsert({
        user_id: user.id,
        riot_id: active.riotId || null,
        region: active.region || "NA",
        profile_json: compactActiveProfile || active,
        updated_at: nowISO()
      }, { onConflict: "user_id" });
    if (profileError) {
      allWritesSaved = false;
      reportPersistentAccountSaveFailure("Supabase profile save failed", profileError, {
        table: "users_profiles",
        operation: "upsert",
        reason,
        profilePayloadBytes: saveMetrics.compactActiveProfileBytes,
        fullProfilePayloadBytes: saveMetrics.activeProfileBytes
      });
    }
  }

  const attemptedLogRowUpsert = logRows.length > 0;
  let logRowsSaved = true;
  if (logRows.length) {
    const { error } = await supabaseClient
      .from("reflection_logs")
      .upsert(logRows, { onConflict: "id" });
    if (error) {
      logRowsSaved = false;
      allWritesSaved = false;
      reportPersistentAccountSaveFailure("Supabase log save failed", error, {
        table: "reflection_logs",
        operation: "upsert",
        reason,
        rowCount: logRows.length,
        logRowsPayloadBytes: saveMetrics.logRowsPayloadBytes
      });
    }
  }
  if (logRowsSaved) {
    markNormalizedRowsSaved(user.id, "log", logRows);
    // Reconciliation only runs when a log row actually changed. Passing the
    // complete current ids keeps its demo-row cleanup behavior without
    // treating a delta-only save as permission to delete the rest of history.
    if (attemptedLogRowUpsert) {
      await reconcilePersistentLogRows(user.id, buildLogRowsForSupabase(user.id));
    }
  }
  const pendingLogDeletesSaved = await flushPendingPersistentLogDeletes(user.id, reason);
  if (!pendingLogDeletesSaved) {
    allWritesSaved = false;
  }

  const matchRowsSaved = await upsertPersistentMatchRows(matchRows, {
    reason,
    matchRowsPayloadBytes: saveMetrics.matchRowsPayloadBytes
  });
  if (!matchRowsSaved) {
    allWritesSaved = false;
  } else {
    markNormalizedRowsSaved(user.id, "match", matchRows);
  }
  // match_snapshots is the permanent archive. Do not prune older rows just
  // because the current client profile window got compacted or Henrik's
  // rolling retention stopped returning a match later.

  if (!allWritesSaved) {
    publishRankedCoachSyncDiagnostics?.("cloud-save-partial");
    schedulePersistentAccountSaveRetry("cloud-save-retry");
    return false;
  }

  if (persistentAccountSaveRetryTimer) {
    window.clearTimeout(persistentAccountSaveRetryTimer);
    persistentAccountSaveRetryTimer = 0;
  }
  localStorage.setItem(STORAGE_KEY_LAST_BACKEND_SYNC, nowISO());
  backendSyncState.lastError = null;
  backendSyncState.lastSaveFailures = [];
  backendSyncState.lastLocalSaveAt = Date.now();
  markAccountStateLoadComplete();
  publishRankedCoachSyncDiagnostics?.("cloud-save-complete");
  return true;
}

async function deletePersistentLogEntry(id) {
  if (!id || !supabaseClient?.auth) return;
  try {
    const user = await getSupabaseUser({ reason: "persistent-log-delete" });
    if (!user) return;

    const { error } = await supabaseClient
      .from("reflection_logs")
      .delete()
      .eq("user_id", user.id)
      .eq("id", String(id));

    if (error) {
      console.warn("Supabase log delete failed", error);
      schedulePersistentAccountSaveRetry("log-delete-retry");
      return false;
    }
    resolvePersistentLogDeletion(id);
    return true;
  } catch (error) {
    // The local deletion has already succeeded. A later account save will
    // reconcile the cloud row once auth is reachable again.
    backendSyncState.pendingSaveReason = "log-delete";
    notifyAuthReachabilityIssue(getPlayerFacingAuthErrorMessage(
      error,
      "Having trouble reaching your account right now — continuing with your local data."
    ));
    schedulePersistentAccountSaveRetry("log-delete-auth-delayed");
    return false;
  }
}

async function flushPendingPersistentLogDeletes(userId = "", reason = "state") {
  const ids = [...pendingPersistentLogDeleteIds];
  if (!userId || !ids.length || !supabaseClient?.from) return true;
  const { error } = await supabaseClient
    .from("reflection_logs")
    .delete()
    .eq("user_id", userId)
    .in("id", ids);
  if (error) {
    reportPersistentAccountSaveFailure("Supabase pending log deletion failed", error, {
      table: "reflection_logs",
      operation: "delete",
      reason,
      rowCount: ids.length
    });
    return false;
  }
  ids.forEach(resolvePersistentLogDeletion);
  return true;
}

async function upsertPersistentMatchRows(rows = [], diagnostics = {}) {
  const batches = globalThis.RankedCoachPersistencePolicy?.chunkRows?.(rows, 6)
    || (rows.length ? [rows] : []);
  for (let index = 0; index < batches.length; index += 1) {
    const { error } = await supabaseClient
      .from("match_snapshots")
      .upsert(batches[index], { onConflict: "id" });
    if (error) {
      reportPersistentAccountSaveFailure("Supabase match save failed", error, {
        table: "match_snapshots",
        operation: "upsert",
        batch: index + 1,
        batchCount: batches.length,
        rowCount: batches[index].length,
        ...diagnostics
      });
      return false;
    }
  }
  return true;
}

async function reconcilePersistentMatchRows(userId, rows = []) {
  if (!userId || !supabaseClient?.from) return;
  const { data, error } = await supabaseClient
    .from("match_snapshots")
    .select("id")
    .eq("user_id", userId);
  if (error) {
    console.warn("Supabase match reconciliation read failed", error);
    return;
  }

  const keepIds = new Set((rows || []).map(row => String(row?.id || "")).filter(Boolean));
  const staleIds = (data || [])
    .map(row => String(row?.id || ""))
    .filter(id => id && !keepIds.has(id));
  const batches = globalThis.RankedCoachPersistencePolicy?.chunkRows?.(staleIds, 100)
    || (staleIds.length ? [staleIds] : []);
  for (const batch of batches) {
    const { error: deleteError } = await supabaseClient
      .from("match_snapshots")
      .delete()
      .eq("user_id", userId)
      .in("id", batch);
    if (deleteError) {
      console.warn("Supabase stale match cleanup failed", deleteError);
      return;
    }
  }
}

async function reconcilePersistentLogRows(userId, rows = []) {
  if (!userId || !supabaseClient?.from) return;
  const { data, error } = await supabaseClient
    .from("reflection_logs")
    .select("id, entry_json")
    .eq("user_id", userId);
  if (error) {
    console.warn("Supabase log reconciliation read failed", error);
    return;
  }

  const keepIds = new Set((rows || []).map(row => String(row.id || "")).filter(Boolean));
  const staleIds = (data || [])
    .filter(row => globalThis.RankedCoachLogPolicy?.isSyntheticDemoLog?.(row?.entry_json || {}))
    .map(row => String(row?.id || ""))
    .filter(id => id && !keepIds.has(id));
  for (let index = 0; index < staleIds.length; index += 100) {
    const batch = staleIds.slice(index, index + 100);
    const { error: deleteError } = await supabaseClient
      .from("reflection_logs")
      .delete()
      .eq("user_id", userId)
      .in("id", batch);
    if (deleteError) {
      console.warn("Supabase synthetic log cleanup failed", deleteError);
      return;
    }
  }
}

function restorePersistentLogRow(row = {}) {
  if (row?.entry_json && typeof row.entry_json === "object") return row.entry_json;
  return {
    id: String(row.id || uuid()),
    profileId: String(row.profile_id || ""),
    matchId: row.match_id || null,
    agent: row.agent || "",
    role: row.role || "",
    map: row.map || "",
    focus: row.focus || "",
    rating: row.rating,
    mood: row.mood || "",
    teamComms: row.team_comms,
    selfComms: row.self_comms,
    notes: row.notes || "",
    warmup: row.warmup === true,
    createdAt: row.created_at || nowISO()
  };
}

async function loadNormalizedPersistentAccountState(user) {
  if (!user?.id || !supabaseClient?.from) return null;
  const [profileResult, logsResult, matchesResult] = await Promise.all([
    supabaseClient.from("users_profiles").select("*").eq("user_id", user.id).maybeSingle(),
    supabaseClient.from("reflection_logs").select("*").eq("user_id", user.id).order("created_at", { ascending: true }),
    supabaseClient.from("match_snapshots").select("*").eq("user_id", user.id).order("played_at", { ascending: true })
  ]);
  const profileRow = profileResult?.data || null;
  const logRows = Array.isArray(logsResult?.data) ? logsResult.data : [];
  const matchRows = Array.isArray(matchesResult?.data) ? matchesResult.data : [];
  if (!profileRow && !logRows.length && !matchRows.length) return null;

  const baseProfile = profileRow?.profile_json && typeof profileRow.profile_json === "object"
    ? { ...profileRow.profile_json }
    : null;
  const profileIds = new Set(matchRows.map(row => String(row?.profile_id || "").trim()).filter(Boolean));
  if (baseProfile?.id) profileIds.add(String(baseProfile.id));
  logRows.forEach(row => {
    const profileId = String(row?.profile_id || "").trim();
    if (profileId) profileIds.add(profileId);
  });
  if (!profileIds.size && baseProfile) profileIds.add(String(baseProfile.id || uuid()));

  const recoveredProfiles = [...profileIds].map((profileId, index) => {
    const profile = index === 0 && baseProfile
      ? { ...baseProfile, id: profileId }
      : {
          id: profileId,
          name: index === 0 ? "Main Profile" : `Profile ${index + 1}`,
          accountName: getUserAccountName(user),
          riotId: index === 0 ? profileRow?.riot_id || "" : "",
          region: index === 0 ? profileRow?.region || "NA" : "NA"
        };
    const recoveredMatches = matchRows
      .filter(row => String(row?.profile_id || "") === profileId)
      .map(row => row?.match_json)
      .filter(match => match && typeof match === "object");
    return normalizeProfileRecord({ ...profile, matches: recoveredMatches.length ? recoveredMatches : profile.matches });
  });

  return {
    activeProfileId: baseProfile?.id || recoveredProfiles[0]?.id || null,
    profiles: recoveredProfiles,
    logEntries: logRows.map(restorePersistentLogRow),
    normalizedLogRowIds: logRows.map(row => String(row?.id || "")).filter(Boolean),
    normalizedMatchRowIds: matchRows.map(row => String(row?.id || "")).filter(Boolean),
    recoveredFromNormalizedTables: true
  };
}

async function loadPersistentAccountState(user) {
  if (!user || !supabaseClient) return { shouldSave: false, loadedRemote: false };

  const appStatePromise = supabaseClient
    .from("vip_app_state")
    .select("*")
    .eq("user_id", user.id)
    .maybeSingle();
  const normalizedStatePromise = loadNormalizedPersistentAccountState(user).catch(normalizedError => {
    backendSyncState.lastError = normalizedError;
    console.warn("Supabase normalized account recovery failed", getPersistentSupabaseErrorDetails(normalizedError, {
      table: "normalized_account_state",
      operation: "select"
    }));
    return null;
  });

  const [{ data, error }, normalizedState] = await Promise.all([appStatePromise, normalizedStatePromise]);

  if (error) {
    backendSyncState.lastError = error;
    console.warn("Supabase app-state load failed", getPersistentSupabaseErrorDetails(error, {
      table: "vip_app_state",
      operation: "select"
    }));
  }

  if (data) {
    const mergedState = mergePersistentAccountStateWithNormalizedTables({
      activeProfileId: data.active_profile_id,
      profiles: data.profiles_json,
      logEntries: Array.isArray(data.log_entries_json) ? data.log_entries_json : [],
      themeBuilderState: data.theme_builder_json,
      themeBuilderUiState: data.theme_builder_ui_json
    }, normalizedState);
    applyPersistentAccountState(mergedState);
    primeNormalizedRowSyncStateFromRemote(user.id, normalizedState);
    return { shouldSave: true, loadedRemote: true, reason: "auth-merge" };
  }

  const recoveredState = normalizedState;
  if (recoveredState) {
    applyPersistentAccountState(recoveredState);
    primeNormalizedRowSyncStateFromRemote(user.id, recoveredState);
    return { shouldSave: true, loadedRemote: true, reason: "auth-normalized-recovery" };
  }

  if (error) return { shouldSave: false, loadedRemote: false };
  return { shouldSave: true, loadedRemote: false, reason: "auth-initial-save" };
}

async function handleSignedInUser(user) {
  window.clearTimeout(backendSyncState.saveTimer);
  backendSyncState.saveTimer = null;
  currentAuthUser = user || null;
  if (user) {
    cacheLastKnownAuthUser(user);
    logEntries = readLocalLogEntries({
      user,
      signedIn: true,
      profileId: activeProfileId
    });
    renderLogFeed?.({ force: true });
  }
  updateAuthUI(user || null);
  if (!user) {
    clearLastKnownAuthUser();
    backendSyncState.hydratingUserId = "";
    lastAccountStateLoadAt = 0;
    stopPersistentAccountAutoRefresh();
    teardownPersistentAccountRealtime();
    refreshRiotProfilePrompt?.();
    return;
  }
  backendSyncState.hydratingUserId = String(user.id || "");
  let loadResult = null;
  try {
    loadResult = await loadPersistentAccountState(user);
  } finally {
    backendSyncState.hydratingUserId = "";
  }
  if (loadResult?.shouldSave) {
    await savePersistentAccountState(loadResult.reason || "auth-merge");
  }
  const active = getActiveProfile();
  const accountName = getUserAccountName(user);
  if (active && (!active.accountName || active.accountName === "Guest")) {
    active.accountName = accountName;
    active.name = active.name || accountName;
    saveProfiles();
  }
  updateProfileHeaderUI?.();
  refreshRiotProfilePrompt?.();
  markAccountStateLoadComplete();
  startPersistentAccountAutoRefresh();
  subscribePersistentAccountRealtime(user);
}

let accountStateFocusRefreshPromise = null;
let accountStateAutoRefreshTimer = 0;

function stopPersistentAccountAutoRefresh() {
  if (!accountStateAutoRefreshTimer) return;
  window.clearInterval(accountStateAutoRefreshTimer);
  accountStateAutoRefreshTimer = 0;
}

function startPersistentAccountAutoRefresh() {
  stopPersistentAccountAutoRefresh();
  if (!currentAuthUser?.id || !supabaseClient?.auth) return;
  accountStateAutoRefreshTimer = window.setInterval(() => {
    if (document.visibilityState !== "visible") return;
    void refreshPersistentAccountStateOnFocus("auto");
  }, ACCOUNT_STATE_RELOAD_SLEEP_MS);
}

async function refreshPersistentAccountStateOnFocus(reason = "focus") {
  if (!currentAuthUser?.id || !supabaseClient?.auth) return;
  if (isAuthReachabilityOfflineCooldownActive()) return;
  if (backendSyncState.hydratingUserId || backendSyncState.applyingRemote) return;
  if (backendSyncState.saveTimer || backendSyncState.savePromise) return;
  if (shouldSkipRecentAccountStateReload(currentAuthUser)) return;
  if (accountStateFocusRefreshPromise) return accountStateFocusRefreshPromise;

  accountStateFocusRefreshPromise = (async () => {
    const user = await getSupabaseUser();
    if (!user) return;
    if (shouldSkipRecentAccountStateReload(user)) return;
    await loadPersistentAccountState(user);
    markAccountStateLoadComplete();
    updateAuthUI?.(user);
  })().catch(error => {
    backendSyncState.lastError = error;
    console.warn(`Supabase app-state ${reason} refresh failed`, error);
  }).finally(() => {
    accountStateFocusRefreshPromise = null;
  });

  return accountStateFocusRefreshPromise;
}

window.addEventListener("focus", () => {
  void refreshPersistentAccountStateOnFocus("window-focus");
  void checkRankedCoachAppUpdate();
});

document.addEventListener("visibilitychange", () => {
  if (document.visibilityState === "visible") {
    void refreshPersistentAccountStateOnFocus("visibility");
    void checkRankedCoachAppUpdate();
  }
});

async function initializeSignedInAccount(user, options = {}) {
  if (!user) return;
  if (loginInitializationInFlight) return;
  captureGuestRiotMigrationSnapshot?.(options.reason || "sign-in");

  loginInitializationInFlight = true;
  showLoginInitializationOverlay(
    "Opening your RankedCoach account.",
    "Saved profiles with more matches and notes can take a little longer to load back in."
  );

  try {
    setLoginInitializationProgress(
      18,
      "Loading your saved profiles, match history, and customization.",
      "Profile",
      "Larger accounts take longer here because we rebuild your saved pages from your full account history."
    );
    const profileLoadPromise = handleSignedInUser(user);
    const securityLoadPromise = hydrateSecuritySettingsFromBackend?.();

    setLoginInitializationProgress(
      46,
      "Checking your security settings and sign-in preferences.",
      "Security",
      "This runs alongside your profile load so returning accounts get back in faster."
    );
    await Promise.all([profileLoadPromise, securityLoadPromise]);
    const migratedGuestRiotProfile = applyPendingGuestRiotMigration?.(user);
    if (migratedGuestRiotProfile) {
      setLoginInitializationProgress(
        62,
        "Moving your guest Riot profile into this account.",
        "Profile",
        "Your local match history stays intact, then RankedCoach saves it under your signed-in account."
      );
      await savePersistentAccountState("guest-riot-migration");
    }

    const active = getActiveProfile();
    if (active?.riotId) {
      setLoginInitializationProgress(
        70,
        "Checking for fresh Riot profile data.",
        "Coach",
        "If your Riot profile is linked, we confirm the latest account read before opening your pages."
      );
      await syncProfileRetainedHistory({
        mode: "refresh",
        onProgress: progress => setLoginInitializationProgress(
          Math.min(86, 70 + Math.round((Math.max(0, Math.min(100, safeNumber(progress.percent))) / 100) * 16)),
          progress.message,
          "Riot history",
          "RankedCoach is finishing the retained competitive history before opening your dashboard."
        )
      });
    } else {
      setLoginInitializationProgress(
        72,
        "No Riot profile is linked yet. Your coaching pages will still load.",
        "Coach",
        "You can add a Riot ID later from Account & Support when you are ready."
      );
      showRiotProfilePrompt({ force: true });
    }

    setLoginInitializationProgress(
      92,
      "Preparing your coaching pages.",
      "Ready",
      "Rendering your dashboard, charts, and notes now."
    );
    updateProfileHeaderUI?.();
    renderInsights?.();
    initStatsPage?.();
    renderLogFeed?.();
    renderChart?.(currentSize);
    queuePersistentAccountSave?.(options.reason || "login-initialization");
    markAccountStateLoadComplete();
  } finally {
    hideLoginInitializationOverlay();
    loginInitializationInFlight = false;
  }
  runPendingPostAuthAction?.(user);
}

