function animateText(el, value) {
  if (!el) return;

  el.textContent = value;
  el.classList.remove("text-anim");
  void el.offsetWidth;
  el.classList.add("text-anim");
  scheduleLoadoutValueTextFit();
}

function fitLoadoutValueText(el, { maxPx = null, minPx = 9 } = {}) {
  if (!el || !el.isConnected) return;

  const availableWidth = Math.max(
    el.clientWidth || 0,
    Math.floor(el.getBoundingClientRect?.().width || 0)
  );

  if (!availableWidth) return;

  const computedFontSize = Number.parseFloat(getComputedStyle(el).fontSize || "0");
  const baseFontSize = Number.isFinite(computedFontSize) && computedFontSize > 0
    ? computedFontSize
    : 16;
  const targetMaxPx = Number.isFinite(maxPx) && maxPx > 0 ? maxPx : baseFontSize;

  const applyFitFontSize = (fontSize) => {
    const rounded = Math.round(fontSize * 100) / 100;
    el.style.setProperty("font-size", `${rounded}px`, "important");
    el.style.setProperty("--tb-auto-fit-font-size", `${rounded}px`);
    el.setAttribute("data-tb-auto-fit", "1");
  };

  applyFitFontSize(targetMaxPx);

  if (el.scrollWidth <= availableWidth + 1) {
    return;
  }

  let low = minPx;
  let high = targetMaxPx;
  let best = minPx;

  while (low <= high) {
    const mid = Math.floor((low + high) / 2);
    applyFitFontSize(mid);

    if (el.scrollWidth <= availableWidth + 1) {
      best = mid;
      low = mid + 1;
    } else {
      high = mid - 1;
    }
  }

  applyFitFontSize(best);
}

const LOADOUT_ROLE_TEXT_COLORS = {
  duelist: "#ff4d5a",
  initiator: "#6dd6ff",
  controller: "#c084fc",
  sentinel: "#4ade80"
};

function applyLoadoutRoleTextColor(el) {
  if (!el || !el.isConnected) return;
  const role = Object.keys(LOADOUT_ROLE_TEXT_COLORS).find((roleKey) => (
    el.classList?.contains(`role-${roleKey}`)
  ));
  if (!role) return;
  el.style.setProperty("color", LOADOUT_ROLE_TEXT_COLORS[role], "important");
}

function syncLoadoutRoleTextColors() {
  [
    agentName,
    focusDisplay,
    document.getElementById("logAgentText"),
    document.getElementById("logFocusSelect"),
    document.getElementById("focusPreviewText"),
    document.getElementById("loggingLiveFocus"),
    document.getElementById("logFocusCustomTrigger"),
    document.getElementById("logFocusCustomValue")
  ].filter(Boolean).forEach(applyLoadoutRoleTextColor);
}

function syncLoggingRoleTone(roleName = activeRole) {
  const normalizedRole = String(roleName || "").toLowerCase();
  const role = ["duelist", "controller", "initiator", "sentinel"].includes(normalizedRole)
    ? normalizedRole
    : "";
  const roleClasses = ["role-duelist", "role-controller", "role-initiator", "role-sentinel"];
  [
    document.getElementById("logAgentText"),
    document.getElementById("logFocusSelect"),
    document.getElementById("focusPreviewText"),
    document.getElementById("loggingLiveFocus"),
    document.getElementById("logFocusCustomTrigger"),
    document.getElementById("logFocusCustomValue")
  ].filter(Boolean).forEach((target) => {
    target.classList.remove(...roleClasses);
    if (role) target.classList.add(`role-${role}`);
  });
  syncLogFocusCustomDropdown?.();
  syncLoadoutRoleTextColors();
  scheduleLoadoutValueTextFit();
}

function flushLoadoutValueTextFit() {
  loadoutValueTextFitRaf = 0;
  syncLoadoutRoleTextColors();
  const targets = [
    agentName,
    focusDisplay,
    ...document.querySelectorAll("#page-home .home-loadout-pill .pill-label"),
    document.getElementById("logAgentText"),
    document.getElementById("focusPreviewText")
  ].filter(Boolean);

  targets.forEach((target) => {
    const isLabel = target.classList?.contains("pill-label");
    fitLoadoutValueText(target, { minPx: isLabel ? 9 : 7 });
  });
  syncLoadoutRoleTextColors();
}

function scheduleLoadoutValueTextFit() {
  if (loadoutValueTextFitRaf) return;
  loadoutValueTextFitRaf = window.requestAnimationFrame(flushLoadoutValueTextFit);
}

function bindLoadoutValueTextFitObservers() {
  if (loadoutValueTextMutationObserver) {
    loadoutValueTextMutationObserver.disconnect();
    loadoutValueTextMutationObserver = null;
  }

  if (loadoutValueTextResizeObserver) {
    loadoutValueTextResizeObserver.disconnect();
    loadoutValueTextResizeObserver = null;
  }

  const targets = [
    agentName,
    focusDisplay,
    ...document.querySelectorAll("#page-home .home-loadout-pill .pill-label"),
    document.getElementById("logAgentText"),
    document.getElementById("focusPreviewText")
  ].filter(Boolean);
  if (!targets.length) return;

  if (typeof MutationObserver === "function") {
    loadoutValueTextMutationObserver = new MutationObserver(() => {
      scheduleLoadoutValueTextFit();
    });

    targets.forEach((target) => {
      loadoutValueTextMutationObserver.observe(target, {
        childList: true,
        characterData: true,
        subtree: true
      });
    });
  }

  if (typeof ResizeObserver === "function") {
    loadoutValueTextResizeObserver = new ResizeObserver(() => {
      scheduleLoadoutValueTextFit();
    });

    targets.forEach((target) => {
      loadoutValueTextResizeObserver.observe(target);
      const pill = target.closest(".home-loadout-pill");
      if (pill) {
        loadoutValueTextResizeObserver.observe(pill);
      }
    });
  }

  scheduleLoadoutValueTextFit();
}

