function setRandomSilhouette(){

  const img = document.getElementById("placeholderSilhouette");
  if(!img) return;

  const keys = Object.keys(AGENT_SIL_MAP);
  if(!keys.length) return;

  const index = Math.floor(Math.random() * keys.length);
  const agent = keys[index];

  img.src = getAgentIconUrl(agent);

}

function stopSilhouetteShuffle() {
  if (silhouetteShuffleTimer) {
    clearTimeout(silhouetteShuffleTimer);
    silhouetteShuffleTimer = null;
  }
  agentPlaceholder?.classList.remove("is-spinning");
}

function startSilhouetteShuffle() {
  const img = document.getElementById("placeholderSilhouette");
  if (!img) return;

  stopSilhouetteShuffle();
  agentPlaceholder?.classList.add("is-spinning");

  let delay = 120;

  const tick = () => {
    const pool = allAgents?.length ? allAgents : Object.keys(AGENT_SIL_MAP);
    if (pool?.length) {
      const agent = pool[Math.floor(Math.random() * pool.length)];
      img.src = getAgentIconUrl(agent);
    }

    delay = Math.max(38, delay - 8);
    silhouetteShuffleTimer = setTimeout(tick, delay);
  };

  tick();
}

function resetPlaceholder() {
  const frame = document.getElementById("agentFrame");
  if (agentPlaceholder) {
    agentPlaceholder.classList.remove("placeholder-glitch", "placeholder-fadeout");
    agentPlaceholder.style.display = "flex";
    agentPlaceholder.style.opacity = "1";
  }
  stopSilhouetteShuffle();
  clearAgentFxRuntime();
  frame?.classList.remove("agent-selected", "reel-active");

  const reel = document.getElementById("agentReel");
  if (reel) {
    reel.classList.remove("reel-spinning");
    reel.classList.add("reel-placeholder");
    const strip = reel.querySelector(".reel-strip");
    if (strip) {
      strip.style.transition = "none";
      strip.style.transform = "translateY(0px)";
    }
  }

  const sil = document.getElementById("placeholderSilhouette");
  if (sil) {
    sil.classList.remove("silhouette-reveal");
    sil.style.opacity = "0.25";
    sil.style.transform = "scale(1.1)";
  }
}

function runPlaceholderExitAnimation() {
  const ph = agentPlaceholder;
  if (!ph) return;

  startSilhouetteShuffle();
  ph.classList.add("placeholder-glitch");

  setTimeout(() => {
    ph.classList.remove("placeholder-glitch");
    ph.classList.add("placeholder-fadeout");
  }, 140);

  setTimeout(() => {
    stopSilhouetteShuffle();
    ph.style.display = "none";
  }, spinDuration - 150);
}

function applyAgentRoleFrame(role) {
  const frame = document.getElementById("agentFrame");
  if (!frame || !role) return;

  frame.classList.remove("duelist", "controller", "initiator", "sentinel");

  const cls = role.toLowerCase();
  if (["duelist", "controller", "initiator", "sentinel"].includes(cls)) {
    frame.classList.add(cls);
  }
}

function getAgentFrameArtState(agentNameStr = "") {
  const key = String(agentNameStr || "").trim().toLowerCase();
  const art = AGENT_FRAME_ART[key] || {};
  return {
    image: getAgentIconUrl(agentNameStr),
    x: Number(art.x || 0),
    y: Number(art.y || 0),
    s: Number(art.s || 1)
  };
}

function getAgentFrameUnitSize(frame = document.getElementById("agentFrame")) {
  if (!frame) return 232;

  const style = getComputedStyle(frame);
  const clientSizes = [
    Math.round(frame.clientWidth || 0),
    Math.round(frame.clientHeight || 0)
  ].filter(size => size > 0);
  const computedSizes = [
    Math.round(Number.parseFloat(style?.width || "0")),
    Math.round(Number.parseFloat(style?.height || "0"))
  ].filter(size => size > 0);
  const rect = frame.getBoundingClientRect?.();
  const rectSizes = [
    Math.round(rect?.width || 0),
    Math.round(rect?.height || 0)
  ].filter(size => size > 0);

  const size = clientSizes.length
    ? Math.min(...clientSizes)
    : computedSizes.length
      ? Math.min(...computedSizes)
      : rectSizes.length
        ? Math.min(...rectSizes)
        : 232;

  return Math.max(1, Math.round(size || 232));
}

function getAgentFrameScaleCompensation(frame = document.getElementById("agentFrame")) {
  const loadoutCard = frame?.closest?.(".loadout-card");
  if (!loadoutCard) return 1;

  const style = getComputedStyle(loadoutCard);
  const scaleX = safeNumber(style?.getPropertyValue("--parent-card-content-scale-x").trim(), 1);
  const scaleY = safeNumber(style?.getPropertyValue("--parent-card-content-scale-y").trim(), 1);
  const compensation = safeDivide(scaleY, scaleX) || 1;

  if (!Number.isFinite(compensation) || compensation <= 0) return 1;
  if (Math.abs(compensation - 1) < 0.01) return 1;
  return Math.max(0.75, Math.min(1.5, compensation));
}

function syncAgentUnifiedFrameGeometry(frame = document.getElementById("agentFrame")) {
  if (!frame) return 232;

  const size = getAgentFrameUnitSize(frame);
  const nextSize = `${size}px`;
  const compensationX = String(getAgentFrameScaleCompensation(frame));

  if (frame.style.getPropertyValue("--agent-frame-unit") !== nextSize) {
    frame.style.setProperty("--agent-frame-unit", nextSize);
  }
  if (frame.style.getPropertyValue("--agent-reel-step") !== nextSize) {
    frame.style.setProperty("--agent-reel-step", nextSize);
  }
  if (frame.style.getPropertyValue("--agent-art-offset-scale") !== "1") {
    frame.style.setProperty("--agent-art-offset-scale", "1");
  }
  if (frame.style.getPropertyValue("--agent-frame-compensation-x") !== compensationX) {
    frame.style.setProperty("--agent-frame-compensation-x", compensationX);
  }
  return size;
}

function updateAgentFrameMetrics(frame = document.getElementById("agentFrame")) {
  if (!frame) return;

  syncAgentUnifiedFrameGeometry(frame);
}

function bindAgentFrameMetrics() {
  const frame = document.getElementById("agentFrame");
  if (!frame) return;

  if (agentFrameResizeAnimationFrame) {
    cancelAnimationFrame(agentFrameResizeAnimationFrame);
    agentFrameResizeAnimationFrame = 0;
  }

  if (agentFrameResizeObserver) {
    agentFrameResizeObserver.disconnect();
    agentFrameResizeObserver = null;
  }

  if (typeof ResizeObserver === "function") {
    agentFrameResizeObserver = new ResizeObserver((entries = []) => {
      const observedFrame = entries[0]?.target || frame;
      if (agentFrameResizeAnimationFrame) {
        cancelAnimationFrame(agentFrameResizeAnimationFrame);
      }
      agentFrameResizeAnimationFrame = requestAnimationFrame(() => {
        agentFrameResizeAnimationFrame = 0;
        updateAgentFrameMetrics(observedFrame);
      });
    });
    agentFrameResizeObserver.observe(frame);
  }

  updateAgentFrameMetrics(frame);
}

function renderAgentFrameArt(agentNameStr = "") {
  const frame = document.getElementById("agentFrame");
  if (!agentFrameArt || !frame) return;

  syncAgentUnifiedFrameGeometry(frame);
  const art = getAgentFrameArtState(agentNameStr);
  const key = String(agentNameStr || "").toLowerCase();
  if (agentRevealArt) {
    agentRevealArt.innerHTML = "";
    if (art.image) {
      const revealImg = document.createElement("img");
      revealImg.src = art.image;
      revealImg.alt = `${agentNameStr} reveal`;
      revealImg.draggable = false;
      agentRevealArt.appendChild(revealImg);
    }
  }
  agentFrameArt.innerHTML = "";
  agentFrameArt.style.backgroundImage = "none";
  agentFrameArt.style.setProperty("--agent-art-x", `${art.x}px`);
  agentFrameArt.style.setProperty("--agent-art-y", `${art.y}px`);
  agentFrameArt.style.setProperty("--agent-art-scale", `${art.s}`);
  frame.style.setProperty("--agent-art-x", `${art.x}px`);
  frame.style.setProperty("--agent-art-y", `${art.y}px`);
  frame.style.setProperty("--agent-art-scale", `${art.s}`);
  frame.style.setProperty("--agent-prism-art", art.image ? `url(${art.image})` : "none");
  frame.dataset.agent = key;
  agentFrameArt.dataset.agent = key;
  if (agentRevealArt) agentRevealArt.dataset.agent = key;
  frame.classList.add("agent-selected");

  return art;
}

function clearAgentFxRuntime() {
  const frame = document.getElementById("agentFrame");

  if (agentFrameArt) {
    agentFrameArt.innerHTML = "";
    agentFrameArt.style.backgroundImage = "none";
    agentFrameArt.style.removeProperty("--agent-art-x");
    agentFrameArt.style.removeProperty("--agent-art-y");
    agentFrameArt.style.removeProperty("--agent-art-scale");
    delete agentFrameArt.dataset.agent;
  }
  if (agentRevealArt) {
    agentRevealArt.innerHTML = "";
    delete agentRevealArt.dataset.agent;
  }

  frame?.style.removeProperty("--agent-art-x");
  frame?.style.removeProperty("--agent-art-y");
  frame?.style.removeProperty("--agent-art-scale");
  frame?.style.removeProperty("--agent-prism-art");
  frame?.removeAttribute("data-fx-engine");
  if (frame) {
    delete frame.dataset.agent;
  }
  frame?.classList.remove("agent-selected");
}

function applyAgentFx(agentNameStr) {
  if (!agentFrameArt) return;

  clearAgentFxRuntime();
  const art = renderAgentFrameArt(agentNameStr);
  const frame = document.getElementById("agentFrame");
  if (frame) frame.dataset.fxEngine = "none";
  return art;
}

