function openRiotModal() {
  if (!requestSignInForRiotConnection?.({
    resumeAction: "riot-link",
    source: "riot-modal",
    reason: "riot-modal-open"
  })) {
    return false;
  }
  showModalById("riotModal");
  return true;
}

function closeRiotModal() {
  hideModalById("riotModal");
}

function getImpactOpportunityAction(componentKey = "", roleKey = "unknown") {
  const roleLabel = roleKey === "unknown" ? "your role" : roleKey;
  const actions = {
    acs: `Raise combat output through traded damage and cleaner multi-kill conversion; avoid chasing low-value damage after the round is already decided.`,
    kd: `Take more tradeable or escapeable fights and slow the next duel after the first kill so fight value rises without adding deaths.`,
    opening: `Use setup utility and a planned exit for first contact. One fewer untraded first death improves this component more reliably than forcing extra openings.`,
    hs: `Keep crosshair placement at head level through common clears, while preserving the body-shot damage that still converts the round.`,
    deaths: `Preserve your life after utility or site value is delivered; for ${roleLabel}, surviving to the next decision protects this weighted component.`,
    assists: `Layer utility immediately before a teammate's contact and stay close enough to trade so setup value becomes a recorded assist or KAST event.`,
    kast: `Increase rounds with a kill, assist, survival, or trade by staying connected to the team through the first and last fight.`,
    econ: `Convert full-buy credits into repeatable rifle-and-utility rounds and avoid low-probability rebuy patterns that suppress economy value.`
  };
  return actions[componentKey] || `Improve the lowest weighted component while keeping the stronger parts of the role report stable.`;
}

function renderImpactOpportunityPullout({ roleWeightEntries = [], componentMap = {}, roleKey = "unknown" } = {}) {
  const list = document.getElementById("impactOpportunityList");
  if (!list) return;

  const opportunities = roleWeightEntries
    .filter(entry => entry.key !== "result" && componentMap?.[entry.key])
    .map(entry => {
      const component = componentMap[entry.key];
      const score = Math.round(clampScore(component.score));
      const weight = safeNumber(entry.weight);
      const componentGain = Math.min(10, Math.max(0, 100 - score));
      return {
        ...entry,
        score,
        weightedGap: (100 - score) * weight,
        projectedGain: componentGain * weight,
        action: getImpactOpportunityAction(entry.key, roleKey)
      };
    })
    .sort((left, right) => right.weightedGap - left.weightedGap || left.score - right.score)
    .slice(0, 3);

  list.innerHTML = opportunities.length ? opportunities.map((item, index) => `
    <article class="impact-opportunity-item${index === 0 ? " is-primary" : ""}">
      <div><span>${index === 0 ? "Best weighted target" : `Next target ${index + 1}`}</span><strong>${escapeHtml(item.label)}</strong></div>
      <dl>
        <div><dt>Current</dt><dd>${item.score}/100</dd></div>
        <div><dt>Weight</dt><dd>${Math.round(item.weight * 100)}%</dd></div>
        <div><dt>If +10</dt><dd>+${item.projectedGain.toFixed(1)} impact</dd></div>
      </dl>
      <p>${escapeHtml(item.action)}</p>
    </article>
  `).join("") : `<p class="impact-opportunity-empty">This match does not contain enough component data to calculate a score opportunity yet.</p>`;

  setImpactOpportunityPulloutOpen(false);
}

function setLensWeightingCollapsed(shouldCollapse = true) {
  const section = document.getElementById("lensWeightingSection");
  const toggle = document.getElementById("lensWeightingToggle");
  const block = document.getElementById("lensWeightingBlock");
  const symbol = toggle?.querySelector("[data-lens-collapse-symbol]");
  const collapsed = Boolean(shouldCollapse);
  section?.classList.toggle("is-collapsed", collapsed);
  if (block) block.hidden = collapsed;
  toggle?.setAttribute("aria-expanded", collapsed ? "false" : "true");
  if (symbol) symbol.textContent = collapsed ? "+" : "−";
}

function setImpactOpportunityPulloutOpen(shouldOpen) {
  const pullout = document.getElementById("impactOpportunityPullout");
  const tab = document.getElementById("impactOpportunityTab");
  const close = document.getElementById("impactOpportunityClose");
  if (!pullout || !tab) return;

  pullout.classList.toggle("is-open", Boolean(shouldOpen));
  tab.setAttribute("aria-expanded", shouldOpen ? "true" : "false");
  close?.toggleAttribute("hidden", !shouldOpen);

  const symbol = tab.querySelector("span");
  if (symbol) symbol.textContent = shouldOpen ? "−" : "+";
  const labelNode = [...tab.childNodes].find(node => node.nodeType === Node.TEXT_NODE);
  if (labelNode) labelNode.textContent = shouldOpen ? "Close " : "Score Opportunities ";
}

function openImpactModal() {
  const modal = document.getElementById("lensModalOverlay");
  const list = document.getElementById("lensStatsList");
  const title = document.getElementById("lensModalTitle");
  const weightingBlock = document.getElementById("lensWeightingBlock");
  const weightingTitle = document.getElementById("lensModalWeightingTitle");
  const statsTitle = document.getElementById("lensModalStatsTitle");
  const researchCallout = document.getElementById("impactResearchCallout");

  if (!modal || !list) return;

  const model = getPlayerModel();
  const impactSnapshots = model?.scoring?.impactSnapshots || [];
  const selectedMatchIndex = Number(impactRolePill?.dataset?.matchIndex);
  const selectedDisplayIndex = Number(impactRolePill?.dataset?.displayIndex);
  const fallbackIndex = matches.length - 1;
  const matchIndex = Number.isInteger(selectedMatchIndex) && selectedMatchIndex >= 0
    ? selectedMatchIndex
    : fallbackIndex;
  const match = matches[matchIndex] || matches[fallbackIndex] || null;
  const snapshot = findImpactSnapshotForMatch(match, matchIndex, impactSnapshots) || impactSnapshots[impactSnapshots.length - 1] || null;
  const core = getMatchCore(match || {});
  const resultLabel = String(core?.result || snapshot?.result || "draw").toLowerCase();
  const impactScore = Math.round(safeNumber(snapshot?.impactScore));
  const impactTier = snapshot?.impactTier || getImpactTierMeta(impactScore).tier;
  const roleLabel = getImpactRoleLabel(match, matchIndex, Number.isInteger(selectedDisplayIndex) ? selectedDisplayIndex : null);
  const roleKey = snapshot?.impactRoleKey || getCompassRoleKey(core?.role || snapshot?.role);
  const roleWeightEntries = Array.isArray(snapshot?.impactWeights) && snapshot.impactWeights.length
    ? snapshot.impactWeights
    : getRoleImpactWeightEntries(roleKey);
  const componentMap = snapshot?.impactComponents || {};
  const openingComponent = componentMap?.opening || null;
  const openingRawValue = openingComponent?.rawValue || null;
  const impactWeights = roleWeightEntries.map(entry => [
    entry.label,
    `${Math.round(safeNumber(entry.weight) * 100)}%`,
    componentMap?.[entry.key]?.formula || `${entry.label} is part of the selected match role-impact formula.`
  ]);
  const componentStats = roleWeightEntries
    .map(entry => componentMap?.[entry.key])
    .filter(Boolean)
    .map(component => ({
      label: component.label,
      value: `${Math.round(safeNumber(component.score))}/100`,
      formula: component.formula
    }));
  const impactStats = [
    { label: "Role Impact", value: `${impactScore}%`, formula: snapshot?.impactFormula || "Final weighted role-impact score after the selected role components are combined." },
    { label: "How It Looked", value: impactTier, formula: "Carry starts at 85+. Solid starts at 60+. Result matters, but a strong loss can still rate well." },
    { label: "Role Context", value: roleLabel || "Current role", formula: "Role label inferred from the selected match agent and current role mapping." },
    { label: "Map", value: snapshot?.map || core.map || "--", formula: "Direct map label from the selected match snapshot." },
    { label: "Agent", value: snapshot?.agent || core.agent || "--", formula: "Direct agent label from the selected match snapshot." },
    { label: "Match Result", value: resultLabel.replace(/^./, (char) => char.toUpperCase()), formula: "Direct result label from the selected match." }
  ].concat(componentStats);

  if (openingRawValue) {
    impactStats.push(
      {
        label: "First Bloods",
        value: `${Math.round(safeNumber(openingRawValue.firstBloods))}`,
        formula: "Direct first-blood count from the selected match."
      },
      {
        label: "First Deaths",
        value: `${Math.round(safeNumber(openingRawValue.firstDeaths))}`,
        formula: "Direct first-death count from the selected match."
      },
      {
        label: "First Contact Ratio",
        value: formatFirstContactRatioDisplay(openingRawValue),
        formula: "First bloods divided by first deaths, with the raw first-blood to first-death count shown in parentheses."
      }
    );
  }

  if (title) title.textContent = "Selected Match Impact";
  if (weightingTitle) weightingTitle.textContent = "Score Category Weights";
  if (statsTitle) statsTitle.textContent = "Impact Category Scores";
  setLensWeightingCollapsed(true);

  list.innerHTML = "";
  if (weightingBlock) weightingBlock.innerHTML = "";

  impactWeights.forEach(([label, value, formula]) => {
    if (!weightingBlock) return;
    weightingBlock.appendChild(createLensWeightPill({
      label,
      value,
      formula,
      prefixWeighted: true
    }));
  });
  wireLensWeightPills(weightingBlock);

  impactStats.forEach((item) => {
    const row = document.createElement("li");
    row.className = `lens-stat${item.formula ? " lens-stat-has-formula" : ""}`;
    if (item.formula) {
      row.dataset.formula = item.formula;
    }
    row.innerHTML = `
      <span>${escapeHtml(item.label)}</span>
      <strong>${escapeHtml(item.value)}</strong>
    `;
    list.appendChild(row);
  });

  renderImpactResearchCallout(researchCallout, { match, snapshot, impactScore });

  renderImpactOpportunityPullout({ roleWeightEntries, componentMap, roleKey });

  showModalById("lensModalOverlay");

}

function renderImpactResearchCallout(node, { match, snapshot, impactScore } = {}) {
  if (!node) return;
  node.hidden = true;
  node.innerHTML = "";
  if (impactScore >= 60) return;

  const core = getMatchCore(match || {});
  const agent = String(snapshot?.agent || core?.agent || "").trim();
  const map = String(snapshot?.map || core?.map || "").trim();
  const flags = match?.roundMetrics?.situationalFlags
    || globalThis.RankedCoachRoundMetrics?.deriveSituationalCoachingFlags?.(match)
    || [];
  if (!agent || !map || !flags.length) return;

  const expectedEntity = `${agent} \u00b7 ${map}`.toLowerCase();
  const knowledge = globalThis.RankedCoachGamesenseLibrary?.getPublishedKnowledge?.() || [];
  const item = knowledge.find(entry => entry?.category === "agent-map"
    && String(entry?.entity || "").trim().toLowerCase() === expectedEntity);
  if (!item?.wording) return;

  const evidence = Array.isArray(item.evidence) ? item.evidence.slice(0, 2) : [];
  node.hidden = false;
  node.innerHTML = `
    <div class="impact-research-callout__eyebrow">RankedCoach Research</div>
    <strong>${escapeHtml(item.topic || `${agent} on ${map}`)}</strong>
    <p>${escapeHtml(item.wording)}</p>
    ${evidence.length ? `<div class="impact-research-callout__evidence">${evidence.map((source, index) => `<a href="${escapeHtml(source.url || "#")}" target="_blank" rel="noopener noreferrer">Source ${index + 1}</a>`).join("")}</div>` : ""}
  `;
}

// ========================
// AGENT MODAL RENDER
// ========================

function renderAgentModal(){
  if(!agentGrid){
    agentGrid = document.getElementById("agentModalGrid");
  }

  if(!agentGrid) return;
  agentGrid.style.pointerEvents = "auto";

  agentGrid.innerHTML = "";

  allAgents.forEach(agent => {

    if(agentRoles[agent] !== activeRole) return;

    const card = document.createElement("div");
    card.className = "agent-card";

    const key = agent.toLowerCase();

    card.innerHTML = `
      <img src="${getAgentIconUrl(key)}" />
      <span>${agent}</span>
    `;

card.style.cursor = "pointer";
card.style.pointerEvents = "auto";

const img = card.querySelector("img");
if (img) {
  img.style.pointerEvents = "none";
}

    card.setAttribute("data-agent", agent);

    card.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();

      const isLogging = getActivePageElement()?.id === "page-logging";

      if(isLogging){
        selectAgentInstant(agent);
      } else {
        selectAgentFromModal(agent);
      }
    });

    agentGrid.appendChild(card);

  });

}

// ========================
// ROLE SELECTOR
// ========================

function renderRoleSelector(){

  const container = document.getElementById("agentRoleSelect");
  if(!container) return;

  container.innerHTML = "";

  const roles = ["duelist","initiator","controller","sentinel"];

  roles.forEach(role => {

    const btn = document.createElement("div");
    btn.className = "agent-role-btn";

    if(role === activeRole){
      btn.classList.add("active");
    }

    const icon = ROLE_ICON_MAP[role];

    btn.innerHTML = icon
      ? `<img src="${icon}" />`
      : `<span>${role}</span>`;

    btn.onclick = () => {

      activeRole = role;
      activeRoleFilter = role;

      renderRoleSelector();
      setTimeout(()=>{ renderRoleSelector(); },0);

      renderAgentModal();

      const agentRoleDropdown = document.getElementById("agentRoleDropdown");
      if(agentRoleDropdown){
        agentRoleDropdown.value = role;
      }

      document.querySelectorAll(".role-filter-btn").forEach(btn => {
        btn.classList.toggle(
          "active",
          btn.dataset.role?.toLowerCase() === role
        );
      });
    };

    container.appendChild(btn);

  });

}

