// INIT
// ========================
function initApp(){
  applyBrowserCompatibilityMode();
  installMobileNavBehavior();
  syncMobileViewportState();
  scaleApp();
  cacheDOM();
  scaleImpactCard();
  bindEvents();
  bindPageNavigationEvents();
  bindDailyWarmupEvents();

  loadProfiles();
  updateProfileHeaderUI();
  rebuildProfileListUI();
  renderCoachReadinessUI?.();

  const active = getActiveProfile();
  matches = active?.matches ? active.matches.slice() : [];

  recomputeFromMatches();

  updateProfileHeaderUI();
  rebuildProfileListUI();
  updateDisplays();
  initStatsPage();
  renderStatsAgents();
  renderStatsMaps();
  renderStatsWeapons();
  renderInsights();
  renderLogFeed();
  syncLoggingQuickChipStates();
  bindInsightFilters();

  setTimeout(() => {
    queueChartAnimationMode(CHART_ANIMATION_MODE_EMPHASIS);
    renderChart(currentSize);
  }, 0);

  refreshImprovementTimeline({ animate: false });

  updateNavRRToRank();
  updateNavRRToGoalRank();
  updateDisplays();

  setRandomSilhouette();
  resetPlaceholder();
  randomizeInitialReel();
  applyPendingLoadoutRollToHome?.(active);
  refreshLatestRRMatchPanel?.();
  updateNavUnderline();
  const authStateListener = supabaseClient?.auth?.onAuthStateChange?.((event, session) => {
    if (authRecoveryInProgress || event === "PASSWORD_RECOVERY") {
      authRecoveryInProgress = true;
      if (session?.user) {
        currentAuthUser = session.user;
        updateProfileDropdownMenu?.();
      }
      if (event === "PASSWORD_RECOVERY") {
        authRecoverySessionReady = true;
        dismissLoginInitializationOverlay();
        setAuthPanel?.("forgot");
        setPasswordRecoveryStage?.("password");
        showModalById?.("authModal");
      }
      return;
    }
    if (event === "INITIAL_SESSION") {
      if (session?.user) {
        setAppEntryChoice("auth");
        closeAuthModal();
      }
      window.setTimeout(() => void initUserSession(session?.user || null), 0);
      return;
    }
    if (session?.user && (authPasswordLoginInProgress || authMfaChallengeInProgress)) {
      currentAuthUser = session.user;
      updateAuthUI?.(session.user);
      return;
    }
    if (session?.user && event === "SIGNED_IN" && !loginInitializationInFlight) {
      setAppEntryChoice("auth");
      closeAuthModal();
      void initializeSignedInAccount(session.user, { reason: "auth-state-signin" });
      return;
    }
    if (shouldSkipRecentAccountStateReload(session?.user || null)) {
      currentAuthUser = session.user;
      updateAuthUI?.(session.user);
      updateProfileDropdownMenu?.();
      updateProfileHeaderUI?.();
    } else {
      void handleSignedInUser(session?.user || null);
    }
    if (session?.user) {
      setAppEntryChoice("auth");
      closeAuthModal();
    }
  });
  if (!authStateListener) void initUserSession();
  noteRankedCoachLoadedBuild();
  startRankedCoachAppUpdateChecks();
  scheduleRiotAutoSync();

  updateWeeklyFocusDateLabel();
  scheduleWeeklyFocusRollover();

  activatePage("home");
  maybeOpenInitialAuthGate();
  void ensureGuestDemoMatches();
  installThemeSnapshotDebugControls();
  maybeAutoSaveThemeSnapshotFromUrl();
  refreshThemeBuilderAccess();
  applyThemeBuilderFontImports();
  ensureThemeBuilderThemeState(getCurrentThemeBuilderThemeKey());
  if (themeBuilderNeedsSave) {
    saveThemeBuilderState();
    themeBuilderNeedsSave = false;
  }
  applyThemeBuilderRuntimeStyles();
  syncThemeBuilderUI();
  void importCanonicalThemeSnapshotIfAvailable();

  console.log("INIT COMPLETE âœ”");
}

function roundThemeBuilderSnapshotNumber(value, precision = 3) {
  const number = Number(value);
  if (!Number.isFinite(number)) return 0;
  const factor = 10 ** precision;
  return Math.round(number * factor) / factor;
}

function rectToThemeBuilderSnapshotRect(rect) {
  if (!rect) return null;
  return {
    x: roundThemeBuilderSnapshotNumber(rect.x ?? rect.left ?? 0),
    y: roundThemeBuilderSnapshotNumber(rect.y ?? rect.top ?? 0),
    width: roundThemeBuilderSnapshotNumber(rect.width ?? 0),
    height: roundThemeBuilderSnapshotNumber(rect.height ?? 0)
  };
}

function getThemeBuilderViewportModel() {
  const root = document.querySelector(".app-root");
  const rootRect = root?.getBoundingClientRect?.() || null;
  const documentStyle = getComputedStyle(document.documentElement);
  const cssScale = Number(documentStyle.getPropertyValue("--app-scale"));
  const designWidth = Number(documentStyle.getPropertyValue("--app-design-width")) || APP_BASE_WIDTH;
  const designHeight = Number(documentStyle.getPropertyValue("--app-design-height")) || APP_BASE_HEIGHT;
  const scaleX = root && rootRect?.width
    ? rootRect.width / designWidth
    : (Number.isFinite(cssScale) && cssScale > 0 ? cssScale : 1);
  const scaleY = root && rootRect?.height
    ? rootRect.height / designHeight
    : (Number.isFinite(cssScale) && cssScale > 0 ? cssScale : 1);
  const uniformScale = Number.isFinite(cssScale) && cssScale > 0
    ? cssScale
    : Math.min(scaleX || 1, scaleY || 1);
  const visualViewport = window.visualViewport
    ? {
        width: roundThemeBuilderSnapshotNumber(window.visualViewport.width),
        height: roundThemeBuilderSnapshotNumber(window.visualViewport.height),
        scale: roundThemeBuilderSnapshotNumber(window.visualViewport.scale)
      }
    : null;

  return {
    unitModel: "app-design-px",
    note: "Use designRect and cssValues for durable CSS. viewportRect is post-transform screen pixels and changes with monitor resolution.",
    viewport: {
      width: window.innerWidth || document.documentElement.clientWidth || 0,
      height: window.innerHeight || document.documentElement.clientHeight || 0,
      devicePixelRatio: window.devicePixelRatio || 1,
      visualViewport
    },
    appBase: {
      width: designWidth,
      height: designHeight
    },
    appScale: {
      css: roundThemeBuilderSnapshotNumber(uniformScale),
      x: roundThemeBuilderSnapshotNumber(scaleX),
      y: roundThemeBuilderSnapshotNumber(scaleY)
    },
    appRoot: root
      ? {
          viewportRect: rectToThemeBuilderSnapshotRect(rootRect),
          designSize: {
            width: designWidth,
            height: designHeight
          }
        }
      : null
  };
}

function getThemeBuilderDesignRect(element, viewportModel = getThemeBuilderViewportModel()) {
  const rect = element?.getBoundingClientRect?.() || null;
  const rootRect = viewportModel?.appRoot?.viewportRect || null;
  const scaleX = Number(viewportModel?.appScale?.x) || Number(viewportModel?.appScale?.css) || 1;
  const scaleY = Number(viewportModel?.appScale?.y) || Number(viewportModel?.appScale?.css) || 1;
  if (!rect || !rootRect || !scaleX || !scaleY) return null;

  return {
    x: roundThemeBuilderSnapshotNumber(((rect.x ?? rect.left ?? 0) - rootRect.x) / scaleX),
    y: roundThemeBuilderSnapshotNumber(((rect.y ?? rect.top ?? 0) - rootRect.y) / scaleY),
    width: roundThemeBuilderSnapshotNumber((rect.width || 0) / scaleX),
    height: roundThemeBuilderSnapshotNumber((rect.height || 0) / scaleY)
  };
}

function getThemeBuilderDesignOffset(childElement, parentElement, viewportModel = getThemeBuilderViewportModel()) {
  const childRect = getThemeBuilderDesignRect(childElement, viewportModel);
  const parentRect = getThemeBuilderDesignRect(parentElement, viewportModel);
  if (!childRect || !parentRect) return null;
  return {
    x: roundThemeBuilderSnapshotNumber(childRect.x - parentRect.x),
    y: roundThemeBuilderSnapshotNumber(childRect.y - parentRect.y)
  };
}

function formatThemeBuilderSourceNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return "";
  return String(roundThemeBuilderSnapshotNumber(number, 2));
}

function withThemeBuilderRuntimeStylesSuspended(callback) {
  const style = document.getElementById(THEME_BUILDER_RUNTIME_STYLE_ID);
  const wasDisabled = style ? style.disabled : false;
  if (style) style.disabled = true;
  try {
    return callback();
  } finally {
    if (style) style.disabled = wasDisabled;
  }
}

function getThemeBuilderSourceParentForElement(target, element) {
  if (!element) return null;
  if (target?.parentSelector) return element.closest(target.parentSelector);
  const config = THEME_BUILDER_PARENT_CONFIGS.find(entry => element.closest(entry.selector));
  return config ? element.closest(config.selector) : null;
}

function getThemeBuilderSourceBoxDefaults(element, parentElement) {
  if (!element) {
    return { boxX: "0", boxY: "0", boxWidth: "", boxHeight: "" };
  }

  return withThemeBuilderRuntimeStylesSuspended(() => {
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect?.() || null;
    const offset = parentElement ? getThemeBuilderDesignOffset(element, parentElement) : null;
    const designRect = getThemeBuilderDesignRect(element);
    return {
      boxX: formatThemeBuilderSourceNumber(offset?.x ?? 0),
      boxY: formatThemeBuilderSourceNumber(offset?.y ?? 0),
      boxWidth: stripCssUnit(style?.width || (designRect?.width ? `${designRect.width}px` : "")),
      boxHeight: stripCssUnit(style?.height || (designRect?.height ? `${designRect.height}px` : "")),
      rect,
      designRect
    };
  });
}

function getThemeBuilderGroupsForParent(parentId) {
  return THEME_BUILDER_GROUP_CONFIGS.filter(group => group.parentId === parentId);
}

function isThemeBuilderAgentFrameGroup(groupOrParentId, groupId = "") {
  if (groupOrParentId && typeof groupOrParentId === "object") {
    return groupOrParentId.parentId === "loadout-card" && groupOrParentId.id === "agent-frame";
  }
  return String(groupOrParentId || "").trim() === "loadout-card" && String(groupId || "").trim() === "agent-frame";
}

function getThemeBuilderGroupTextSelector(group) {
  if (!group?.selector) return "";
  if (group.textSelector) return group.textSelector;
  return `${group.selector} :is(.card-title,.card-sub,.card-pill,.weekly-focus-key,.weekly-focus-text,.timeline-title,.timeline-sub,.timeline-label,.timeline-value,.role-filter-btn,.small,.score-num,.compass-card-label,.compass-card-tier,.compass-card-meta,.insight-title,.insight-label,.insight-tag,.insight-preview,.insight-meta-pill,.insight-trend-kicker,.insight-trend-title,.stat-label,.stat-value,.stats-proof-kicker,.stats-breakdown-label,.stats-breakdown-value,.stats-breakdown-detail,span,strong,p,label,button,input,textarea,select)`;
}

function getThemeBuilderGroupTextTargets(group) {
  return getThemeBuilderSelectorMatches(getThemeBuilderGroupTextSelector(group))
    .filter(isThemeBuilderElementVisible)
    .filter((element) => {
      const enclosingAction = element.closest(THEME_BUILDER_ACTION_TARGET_SELECTOR);
      return !enclosingAction || element === enclosingAction;
    });
}

function getThemeBuilderLineHeightInputValue(style = null) {
  const rawLineHeight = String(style?.lineHeight || "").trim();
  if (!rawLineHeight || rawLineHeight === "normal") return "";
  const numericLineHeight = Number.parseFloat(rawLineHeight);
  if (!Number.isFinite(numericLineHeight)) return "";
  const rawFontSize = String(style?.fontSize || "").trim();
  const numericFontSize = Number.parseFloat(rawFontSize);
  if (/px$/i.test(rawLineHeight) && Number.isFinite(numericFontSize) && numericFontSize > 0) {
    return String(roundThemeBuilderSnapshotNumber(numericLineHeight / numericFontSize, 2));
  }
  return String(roundThemeBuilderSnapshotNumber(numericLineHeight, 2));
}

function getThemeBuilderGroupDefaults(group) {
  const element = group?.selector ? document.querySelector(group.selector) : null;
  const parentConfig = THEME_BUILDER_PARENT_CONFIGS.find(config => config.id === group?.parentId);
  const parentElement = parentConfig ? element?.closest?.(parentConfig.selector) : null;
  return withThemeBuilderRuntimeStylesSuspended(() => {
    const style = element ? getComputedStyle(element) : null;
    const textSample = getThemeBuilderGroupTextTargets(group)
      .find((textElement) => Boolean(getThemeBuilderReadableElementContent(textElement))) || null;
    const textStyle = textSample ? getComputedStyle(textSample) : style;
    const sourceBox = getThemeBuilderSourceBoxDefaults(element, parentElement);
    const borderColor = style?.borderColor && style.borderColor !== "rgba(0, 0, 0, 0)"
      ? style.borderColor
      : style?.color;
    const defaultWidth = sourceBox.boxWidth || stripCssUnit(style?.width || "");
    const defaultHeight = sourceBox.boxHeight || stripCssUnit(style?.height || "");
    const agentFrameSize = isThemeBuilderAgentFrameGroup(group)
      ? defaultWidth || defaultHeight
      : "";
    return {
      groupX: "0",
      groupY: "0",
      groupWidth: agentFrameSize || defaultWidth,
      groupHeight: agentFrameSize || defaultHeight,
      groupScale: "1",
      groupZIndex: "",
      groupBg: rgbColorToHex(style?.backgroundColor || "rgba(0, 0, 0, 0)"),
      groupText: rgbColorToHex(textStyle?.color || style?.color || "#ffffff"),
      groupBorder: rgbColorToHex(borderColor || "#ffffff"),
      fontFamily: matchThemeBuilderFontOption(textStyle?.fontFamily || style?.fontFamily || ""),
      fontSize: stripCssUnit(textStyle?.fontSize || style?.fontSize || "16px"),
      fontWeight: normalizeThemeBuilderFontWeight(textStyle?.fontWeight || style?.fontWeight || ""),
      letterSpacing: textStyle?.letterSpacing && textStyle.letterSpacing !== "normal" ? stripCssUnit(textStyle.letterSpacing) : "",
      lineHeight: getThemeBuilderLineHeightInputValue(textStyle),
      groupGap: style?.rowGap && style.rowGap !== "normal"
        ? stripCssUnit(style.rowGap)
        : style?.gap && style.gap !== "normal"
          ? stripCssUnit(style.gap)
          : "",
      groupPaddingX: stripCssUnit(style?.paddingLeft || ""),
      groupPaddingY: stripCssUnit(style?.paddingTop || ""),
      textNoWrap: false,
      textGlow: "",
      textStroke: "",
      textX: "0",
      textY: "0",
      sourceBoxX: sourceBox.boxX || "0",
      sourceBoxY: sourceBox.boxY || "0"
    };
  });
}

function buildThemeBuilderGroupCssValues(values = {}) {
  const x = String(values.groupX ?? "").trim();
  const y = String(values.groupY ?? "").trim();
  const textX = String(values.textX ?? "").trim();
  const textY = String(values.textY ?? "").trim();
  const scale = String(values.groupScale ?? "").trim();
  const groupGap = String(values.groupGap ?? "").trim();
  const groupPaddingX = String(values.groupPaddingX ?? "").trim();
  const groupPaddingY = String(values.groupPaddingY ?? "").trim();
  const textCss = buildThemeBuilderTextCssValues(values);
  const translateX = (x && x !== "0") || (y && y !== "0")
    ? appendThemeBuilderPx(x || "0", "x")
    : "";
  const translateY = (x && x !== "0") || (y && y !== "0")
    ? appendThemeBuilderPx(y || "0", "y")
    : "";
  const textTranslateX = (textX && textX !== "0") || (textY && textY !== "0")
    ? appendThemeBuilderPx(textX || "0", "x")
    : "";
  const textTranslateY = (textX && textX !== "0") || (textY && textY !== "0")
    ? appendThemeBuilderPx(textY || "0", "y")
    : "";
  const normalizedScale = scale && Number(scale) !== 1 ? scale : "";
  return {
    translate: translateX || translateY ? `${translateX || "0px"} ${translateY || "0px"}` : "",
    width: values.groupWidth ? appendThemeBuilderPxIfNeeded(values.groupWidth, "px", "x") : "",
    height: values.groupHeight ? appendThemeBuilderPxIfNeeded(values.groupHeight, "px", "y") : "",
    scale: normalizedScale,
    transform: buildThemeBuilderTransformValue({ translateX, translateY, scale: normalizedScale }),
    zIndex: normalizeThemeBuilderZIndex(values.groupZIndex),
    background: values.groupBg || "",
    color: values.groupText || "",
    borderColor: values.groupBorder || "",
    fontFamily: values.fontFamily && values.fontFamily !== "inherit" ? values.fontFamily : "",
    fontSize: values.fontSize ? appendThemeBuilderPxIfNeeded(values.fontSize, "px", "uniform") : "",
    gap: groupGap ? appendThemeBuilderPxIfNeeded(groupGap, "px", "y") : "",
    paddingX: groupPaddingX ? appendThemeBuilderPxIfNeeded(groupPaddingX, "px", "x") : "",
    paddingY: groupPaddingY ? appendThemeBuilderPxIfNeeded(groupPaddingY, "px", "y") : "",
    ...textCss,
    textTranslate: textTranslateX || textTranslateY ? `${textTranslateX || "0px"} ${textTranslateY || "0px"}` : "",
    textTransform: buildThemeBuilderTransformValue({ translateX: textTranslateX, translateY: textTranslateY })
  };
}

function buildThemeBuilderGroupCssRules(themeKey, group, cssValues = {}) {
  if (!group?.selector) return "";
  const declarations = [
    "box-sizing:border-box !important;",
    "overflow:visible !important;",
    "max-width:none !important;",
    "max-height:none !important;"
  ];
  const lockSquareFrame = isThemeBuilderAgentFrameGroup(group);
  const lockedSize = lockSquareFrame
    ? (cssValues.width || cssValues.height)
    : "";
  if (lockSquareFrame) declarations.push("overflow:hidden !important;");
  if (browserFeatureSupport.individualTransform) {
    if (cssValues.translate) declarations.push(`translate:${cssValues.translate} !important;`);
    if (cssValues.scale) declarations.push(`scale:${cssValues.scale} !important;`);
  } else if (cssValues.transform) {
    declarations.push(`transform:${cssValues.transform} !important;`);
  }
  if (cssValues.scale) {
    declarations.push("transform-origin:left top !important;");
  }
  if (lockSquareFrame) declarations.push("aspect-ratio:1 / 1 !important;");
  if (lockSquareFrame && lockedSize) {
    declarations.push(`width:${lockedSize} !important;`);
    declarations.push(`height:${lockedSize} !important;`);
    declarations.push(`--agent-frame-size:${lockedSize} !important;`);
    declarations.push(`--agent-frame-unit:${lockedSize} !important;`);
    declarations.push(`--agent-reel-step:${lockedSize} !important;`);
    declarations.push("--agent-art-offset-scale:1 !important;");
  } else {
    if (cssValues.width) declarations.push(`width:${cssValues.width} !important;`);
    if (cssValues.height) declarations.push(`height:${cssValues.height} !important;`);
  }
  if (cssValues.zIndex) {
    declarations.push("position:relative !important;");
    declarations.push(`z-index:${cssValues.zIndex} !important;`);
  }
  if (cssValues.background) declarations.push(`background:${cssValues.background} !important;`);
  if (cssValues.color) declarations.push(`color:${cssValues.color} !important;`);
  if (cssValues.borderColor) declarations.push(`border-color:${cssValues.borderColor} !important;`);
  if (cssValues.fontFamily) declarations.push(`font-family:${cssValues.fontFamily} !important;`);
  if (cssValues.fontSize) declarations.push(`font-size:${cssValues.fontSize} !important;`);
  if (cssValues.gap) declarations.push(`gap:${cssValues.gap} !important;`);
  if (cssValues.paddingX) {
    declarations.push(`padding-left:${cssValues.paddingX} !important;`);
    declarations.push(`padding-right:${cssValues.paddingX} !important;`);
  }
  if (cssValues.paddingY) {
    declarations.push(`padding-top:${cssValues.paddingY} !important;`);
    declarations.push(`padding-bottom:${cssValues.paddingY} !important;`);
  }
  appendThemeBuilderTextDeclarations(declarations, cssValues);

  const rules = [];
  const hasGroupDeclarations = declarations.length > 1;
  if (hasGroupDeclarations) {
    rules.push(`${scopeThemeBuilderSelectorList(themeKey, group.selector)}{${declarations.join("")}}`);
  }
  if (cssValues.color || cssValues.fontFamily || cssValues.fontSize || cssValues.textTranslate || hasThemeBuilderTextCssValues(cssValues)) {
    const textDeclarations = [];
    if (cssValues.color) textDeclarations.push(`color:${cssValues.color} !important;`);
    if (cssValues.fontFamily) textDeclarations.push(`font-family:${cssValues.fontFamily} !important;`);
    if (cssValues.fontSize) textDeclarations.push(`font-size:${cssValues.fontSize} !important;`);
    appendThemeBuilderTextDeclarations(textDeclarations, cssValues);
    if (browserFeatureSupport.individualTransform) {
      if (cssValues.textTranslate) textDeclarations.push(`translate:${cssValues.textTranslate} !important;`);
    } else if (cssValues.textTransform) {
      textDeclarations.push(`transform:${cssValues.textTransform} !important;`);
    }
    rules.push(`${scopeThemeBuilderSelectorList(themeKey, getThemeBuilderGroupTextSelector(group))}{${textDeclarations.join("")}}`);
  }
  return rules.join("\n");
}

function collectThemeSnapshot() {
  const bodyTheme = document.body?.dataset?.theme || "unknown";
  const themeState = cloneThemeBuilderValue(themeBuilderState?.[bodyTheme] || {});
  const viewportModel = getThemeBuilderViewportModel();
  const overlayMeasurements = THEME_BUILDER_PARENT_CONFIGS
    .map(config => {
      const selector = config.selector;
      const element = document.querySelector(selector);
      if (!element) return null;

      const computed = getComputedStyle(element);
      const rect = element.getBoundingClientRect?.() || null;
      const values = OVERLAY_TUNING_VAR_NAMES.reduce((acc, name) => {
        acc[name] = computed.getPropertyValue(name).trim();
        return acc;
      }, {});

      return {
        id: config.id,
        label: config.label,
        selector,
        childSelector: config.childSelector || "",
        theme: bodyTheme,
        viewportRect: rectToThemeBuilderSnapshotRect(rect),
        designRect: getThemeBuilderDesignRect(element, viewportModel),
        values,
        parentState: cloneThemeBuilderValue(themeState.parents?.[config.id] || {}),
        hoverFxSnapshot: collectThemeBuilderParentHoverSnapshot(bodyTheme, config, themeState),
        childSnapshot: collectThemeBuilderChildSnapshot(bodyTheme, config, themeState, viewportModel),
        groupSnapshots: collectThemeBuilderGroupSnapshots(bodyTheme, config, themeState, viewportModel),
        elementSnapshots: []
      };
    })
    .filter(Boolean);

  return {
    snapshotType: "theme",
    schemaVersion: 2,
    capturedAt: new Date().toISOString(),
    url: window.location.href,
    theme: bodyTheme,
    viewportModel,
    overlayMeasurements,
    cards: overlayMeasurements,
    themeBuilder: {
      activeTheme: bodyTheme,
      currentThemeState: themeState,
      allThemes: cloneThemeBuilderValue(themeBuilderState || {})
    }
  };
}

const collectOverlaySnapshot = collectThemeSnapshot;

function collectThemeBuilderParentHoverSnapshot(themeKey, config, themeState = {}) {
  const saved = themeState.parents?.[config.id] || {};
  const defaults = getThemeBuilderParentDefaults(config);
  const reduceFieldValues = (fields, booleanField) => fields.reduce((acc, field) => {
    acc[field] = field === booleanField
      ? Boolean(saved[field])
      : String(saved[field] ?? defaults[field] ?? "").trim();
    return acc;
  }, {});
  const savedValues = THEME_BUILDER_PARENT_HOVER_FIELDS.reduce((acc, field) => {
    acc[field] = field === "hoverFxEnabled"
      ? Boolean(saved[field])
      : String(saved[field] ?? defaults[field] ?? "").trim();
    return acc;
  }, {});
  const outerAuraSavedValues = reduceFieldValues(THEME_BUILDER_PARENT_OUTER_AURA_FIELDS, "outerAuraEnabled");
  const cssValues = buildThemeBuilderHoverFxCssValues(savedValues, themeKey);
  const outerAuraCssValues = buildThemeBuilderOuterAuraCssValues(outerAuraSavedValues);
  const renderer = cssValues.preset === "smoke-video" ? "video-smoke" : "solid-aura";
  const generatedCssRule = cssValues.enabled
    ? `${scopeThemeBuilderSelectorList(themeKey, config.selector)}{--tb-hover-fx-renderer:${renderer}; --tb-hover-fx-color:${cssValues.color}; --tb-hover-fx-accent:${cssValues.accent}; --tb-hover-fx-intensity:${cssValues.intensity}; --tb-hover-fx-distance:${cssValues.distance}; --tb-hover-fx-opacity:${cssValues.opacity}; --tb-hover-fx-duration:${cssValues.duration};}`
    : "";

  return {
    defaultValues: THEME_BUILDER_PARENT_HOVER_FIELDS.reduce((acc, field) => {
      acc[field] = field === "hoverFxEnabled"
        ? Boolean(defaults[field])
        : String(defaults[field] ?? "").trim();
      return acc;
    }, {}),
    savedValues,
    cssValues,
    outerAura: {
      defaultValues: THEME_BUILDER_PARENT_OUTER_AURA_FIELDS.reduce((acc, field) => {
        acc[field] = field === "outerAuraEnabled"
          ? Boolean(defaults[field])
          : String(defaults[field] ?? "").trim();
        return acc;
      }, {}),
      savedValues: outerAuraSavedValues,
      cssValues: outerAuraCssValues
    },
    renderer,
    generatedCssRule
  };
}

function collectThemeBuilderGroupSnapshots(themeKey, config, themeState = {}, viewportModel = getThemeBuilderViewportModel()) {
  const groupStates = themeState.groups?.[config.id] || {};
  return getThemeBuilderGroupsForParent(config.id).map((group) => {
    const saved = groupStates[group.id] || {};
    const defaults = getThemeBuilderGroupDefaults(group);
    const defaultValues = THEME_BUILDER_GROUP_FIELDS.reduce((acc, field) => {
      acc[field] = String(defaults[field] ?? "").trim();
      return acc;
    }, {});
    const savedValues = THEME_BUILDER_GROUP_FIELDS.reduce((acc, field) => {
      acc[field] = Object.prototype.hasOwnProperty.call(saved, field) ? String(saved[field] ?? "").trim() : "";
      return acc;
    }, {});
    const cssValues = buildThemeBuilderGroupCssValues(savedValues);
    const element = document.querySelector(group.selector);
    const computed = element ? getComputedStyle(element) : null;
    const rect = element?.getBoundingClientRect?.() || null;
    const viewportRect = rectToThemeBuilderSnapshotRect(rect);

    return {
      id: group.id,
      label: group.label,
      selector: group.selector,
      textSelector: getThemeBuilderGroupTextSelector(group),
      defaultValues,
      savedValues,
      cssValues,
      generatedCssRule: buildThemeBuilderGroupCssRules(themeKey, group, cssValues),
      rect: viewportRect,
      viewportRect,
      designRect: getThemeBuilderDesignRect(element, viewportModel),
      computedValues: computed
        ? {
            background: computed.backgroundColor,
            color: computed.color,
            borderColor: computed.borderColor,
            fontFamily: computed.fontFamily,
            fontSize: computed.fontSize,
            translate: computed.getPropertyValue("translate").trim(),
            scale: computed.getPropertyValue("scale").trim(),
            width: computed.width,
            height: computed.height,
            position: computed.position,
            zIndex: computed.zIndex
          }
        : {}
    };
  });
}

function collectThemeBuilderChildSnapshot(themeKey, config, themeState = {}, viewportModel = getThemeBuilderViewportModel()) {
  const childTargets = getThemeBuilderSelectorMatches(config.childSelector);
  return {
    selector: config.childSelector || "",
    legacyDisabled: true,
    note: "Theme Builder v2 uses curated groupSnapshots instead of the broad legacy child free-form selector.",
    targetCount: childTargets.length,
    savedValues: {},
    cssValues: {},
    generatedCssRule: "",
    firstTarget: null,
    computedValues: {}
  };
}

async function saveThemeSnapshot(button = null) {
  const targetButton = button || document.getElementById("themeSnapshotDebugBtn");
  const originalText = targetButton?.textContent || "Snapshot Current Theme";
  if (targetButton) {
    targetButton.disabled = true;
    targetButton.textContent = "Saving...";
  }

  try {
    const payload = collectThemeSnapshot();
    const response = await fetch("/api/dev/theme-snapshot", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload)
    });
    const result = await response.json();

    if (!response.ok || !result?.ok) {
      throw new Error(result?.error || "Failed to save theme snapshot.");
    }

    if (targetButton) {
      targetButton.textContent = "Theme Snapshot Saved";
      window.setTimeout(() => {
        targetButton.disabled = false;
        targetButton.textContent = originalText;
      }, 1500);
    }

    return result;
  } catch (error) {
    if (targetButton) {
      targetButton.disabled = false;
      targetButton.textContent = originalText;
    }
    throw error;
  }
}

const saveOverlaySnapshot = saveThemeSnapshot;

function shouldAutoSaveThemeSnapshotFromUrl() {
  const params = getThemeBuilderUrlParams();
  return isLocalThemeBuilderHost() && params.get("autoThemeSnapshot") === "1";
}

function maybeAutoSaveThemeSnapshotFromUrl() {
  if (!shouldAutoSaveThemeSnapshotFromUrl()) return;
  if (window.__themeSnapshotAutoSaveStarted) return;
  window.__themeSnapshotAutoSaveStarted = true;

  const runAutoSave = () => {
    saveThemeSnapshot()
      .then((result) => {
        console.info("[ThemeSnapshot] Auto-saved current theme snapshot.", result);
      })
      .catch((error) => {
        console.error("[ThemeSnapshot] Auto-save failed.", error);
      });
  };

  requestAnimationFrame(() => {
    window.setTimeout(runAutoSave, 300);
  });
}

function shouldShowThemeSnapshotDebugButton() {
  const params = new URLSearchParams(window.location.search || "");
  return params.has("themeSnapshot") ||
    params.has("overlaySnapshot") ||
    localStorage.getItem("vip_show_theme_snapshot") === "1" ||
    localStorage.getItem("vip_show_overlay_snapshot") === "1";
}

function installThemeSnapshotDebugControls() {
  if (THEME_BUILDER_LAUNCH_LOCKED) return;
  if (!shouldShowThemeSnapshotDebugButton()) {
    window.saveThemeSnapshot = saveThemeSnapshot;
    window.collectThemeSnapshot = collectThemeSnapshot;
    window.saveOverlaySnapshot = saveOverlaySnapshot;
    window.collectOverlaySnapshot = collectOverlaySnapshot;
    return;
  }
  if (!document.body || document.getElementById("themeSnapshotDebugBtn")) return;

  const button = document.createElement("button");
  button.id = "themeSnapshotDebugBtn";
  button.type = "button";
  button.textContent = "Snapshot Current Theme";
  button.style.position = "fixed";
  button.style.right = "18px";
  button.style.bottom = "18px";
  button.style.zIndex = "2147483647";
  button.style.padding = "10px 14px";
  button.style.borderRadius = "999px";
  button.style.border = "1px solid rgba(255,255,255,.18)";
  button.style.background = "rgba(8,12,18,.86)";
  button.style.color = "#fff";
  button.style.font = "600 12px/1.2 system-ui, sans-serif";
  button.style.letterSpacing = ".02em";
  button.style.cursor = "pointer";
  button.style.boxShadow = "0 10px 30px rgba(0,0,0,.28)";
  button.addEventListener("click", async () => {
    try {
      await saveThemeSnapshot(button);
    } catch (error) {
      console.error(error);
      window.alert(error?.message || "Failed to save theme snapshot.");
    }
  });

  document.body.appendChild(button);
  window.saveThemeSnapshot = saveThemeSnapshot;
  window.collectThemeSnapshot = collectThemeSnapshot;
  window.saveOverlaySnapshot = saveOverlaySnapshot;
  window.collectOverlaySnapshot = collectOverlaySnapshot;
}

function archiveThemeBuilderLocalStorageForLaunchLock() {
  if (!THEME_BUILDER_LAUNCH_LOCKED || typeof localStorage === "undefined") return;
  try {
    const payload = {
      lockedAt: new Date().toISOString(),
      storageKey: THEME_BUILDER_STORAGE_KEY,
      uiStorageKey: THEME_BUILDER_UI_STORAGE_KEY,
      state: localStorage.getItem(THEME_BUILDER_STORAGE_KEY),
      uiState: localStorage.getItem(THEME_BUILDER_UI_STORAGE_KEY)
    };
    if (payload.state || payload.uiState) {
      localStorage.setItem(THEME_BUILDER_LOCKED_BACKUP_STORAGE_KEY, JSON.stringify(payload));
    }
    localStorage.removeItem(THEME_BUILDER_STORAGE_KEY);
    localStorage.removeItem(THEME_BUILDER_UI_STORAGE_KEY);
    localStorage.removeItem(THEME_BUILDER_ACCESS_STORAGE_KEY);
  } catch (_error) {}
}

function loadThemeBuilderState() {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    archiveThemeBuilderLocalStorageForLaunchLock();
    return {};
  }
  try {
    const raw = localStorage.getItem(THEME_BUILDER_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return normalizeLoadedThemeBuilderState(
      mergeBakedThemeBuilderState(parsed && typeof parsed === "object" ? parsed : {})
    );
  } catch (_error) {
    return normalizeLoadedThemeBuilderState(mergeBakedThemeBuilderState({}));
  }
}

function extractThemeBuilderThemesFromSnapshot(snapshot = {}) {
  const allThemes = snapshot?.themeBuilder?.allThemes;
  if (allThemes && typeof allThemes === "object" && !Array.isArray(allThemes)) {
    return cloneThemeBuilderValue(allThemes);
  }

  const themeKey = String(snapshot?.theme || "").trim();
  const currentThemeState = snapshot?.themeBuilder?.currentThemeState;
  if (themeKey && currentThemeState && typeof currentThemeState === "object") {
    return {
      [themeKey]: cloneThemeBuilderValue(currentThemeState)
    };
  }

  return {};
}

async function importCanonicalThemeSnapshotIfAvailable() {
  if (THEME_BUILDER_LAUNCH_LOCKED) return;
  if (!isLocalThemeBuilderHost()) return;

  try {
    const response = await fetch("/api/dev/theme-snapshot", { cache: "no-store" });
    if (!response.ok) return;

    const result = await response.json();
    const snapshot = result?.snapshot;
    if (!snapshot || typeof snapshot !== "object") return;

    const capturedAt = String(snapshot?.capturedAt || "").trim();
    const importedThemes = extractThemeBuilderThemesFromSnapshot(snapshot);
    const themeKeys = Object.keys(importedThemes);
    if (!themeKeys.length) return;

    const shouldImport = themeKeys.some((themeKey) => {
      const themeState = themeBuilderState?.[themeKey];
      const importedAt = String(themeState?.__importedSnapshotCapturedAt || "").trim();
      const importVersion = Number(themeState?.__snapshotImportVersion || 0);
      return importVersion < THEME_SNAPSHOT_IMPORT_VERSION || !capturedAt || importedAt !== capturedAt;
    });
    if (!shouldImport) return;

    const nextState = cloneThemeBuilderValue(themeBuilderState || {});
    themeKeys.forEach((themeKey) => {
      const importedTheme = importedThemes[themeKey];
      if (!importedTheme || typeof importedTheme !== "object") return;
      nextState[themeKey] = {
        ...importedTheme,
        __importedSnapshotCapturedAt: capturedAt,
        __snapshotImportVersion: THEME_SNAPSHOT_IMPORT_VERSION
      };
    });

    themeBuilderState = normalizeLoadedThemeBuilderState(nextState);
    themeKeys.forEach((themeKey) => ensureThemeBuilderThemeState(themeKey));
    saveThemeBuilderState();
    applyThemeBuilderFontImports();
    applyThemeBuilderRuntimeStyles();
    syncThemeBuilderUI();
  } catch (error) {
    console.warn("[ThemeBuilder] Snapshot import skipped.", error);
  }
}

function getThemeBuilderSnapshotImportMeta(themeState = {}) {
  const importedAtValue = Date.parse(String(themeState?.__importedSnapshotCapturedAt || "").trim());
  const importVersionValue = Number(themeState?.__snapshotImportVersion || 0);
  return {
    importedAt: Number.isFinite(importedAtValue) ? importedAtValue : 0,
    importVersion: Number.isFinite(importVersionValue) ? importVersionValue : 0
  };
}

function shouldPreferLocalThemeBuilderThemeState(localTheme = {}, remoteTheme = {}) {
  const localMeta = getThemeBuilderSnapshotImportMeta(localTheme);
  const remoteMeta = getThemeBuilderSnapshotImportMeta(remoteTheme);
  if (localMeta.importVersion !== remoteMeta.importVersion) {
    return localMeta.importVersion > remoteMeta.importVersion;
  }
  if (localMeta.importedAt !== remoteMeta.importedAt) {
    return localMeta.importedAt > remoteMeta.importedAt;
  }
  return false;
}

function mergeLocalAndRemoteThemeBuilderState(localState = {}, remoteState = {}) {
  const mergedState = cloneThemeBuilderValue(
    remoteState && typeof remoteState === "object" ? remoteState : {}
  );
  const localThemes = localState && typeof localState === "object" ? localState : {};
  Object.entries(localThemes).forEach(([themeKey, localTheme]) => {
    const remoteTheme = mergedState?.[themeKey];
    if (!remoteTheme || shouldPreferLocalThemeBuilderThemeState(localTheme, remoteTheme)) {
      mergedState[themeKey] = cloneThemeBuilderValue(localTheme);
    }
  });
  return mergedState;
}

function loadThemeBuilderUiState() {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    return { open: false, dock: "left", offsetX: 0, offsetY: 0, advancedElements: false };
  }
  try {
    const raw = localStorage.getItem(THEME_BUILDER_UI_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : {};
    return {
      open: Boolean(parsed?.open),
      dock: String(parsed?.dock || "left"),
      offsetX: Number.isFinite(Number(parsed?.offsetX)) ? Number(parsed.offsetX) : 0,
      offsetY: Number.isFinite(Number(parsed?.offsetY)) ? Number(parsed.offsetY) : 0,
      advancedElements: Boolean(parsed?.advancedElements)
    };
  } catch (_error) {
    return { open: false, dock: "left", offsetX: 0, offsetY: 0, advancedElements: false };
  }
}

function saveThemeBuilderUiState() {
  if (THEME_BUILDER_LAUNCH_LOCKED) return;
  localStorage.setItem(THEME_BUILDER_UI_STORAGE_KEY, JSON.stringify(themeBuilderUiState));
}

function isThemeBuilderAdvancedElementsEnabled() {
  return Boolean(themeBuilderUiState?.advancedElements);
}

function cloneThemeBuilderValue(value) {
  return JSON.parse(JSON.stringify(value || {}));
}

function stripThemeBuilderElementLayoutFields(elementState = {}) {
  if (!elementState || typeof elementState !== "object") return;
  [
    "layoutMode",
    "boxX",
    "boxY",
    "boxWidth",
    "boxHeight",
    "scaleX",
    "scaleY",
    "imageScale"
  ].forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(elementState, field)) {
      delete elementState[field];
    }
  });
}

function stripThemeBuilderParentChildLayoutFields(parentState = {}) {
  if (!parentState || typeof parentState !== "object") return;
  THEME_BUILDER_CHILD_SNAPSHOT_FIELDS.forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(parentState, field)) {
      delete parentState[field];
    }
  });
}

function stripThemeBuilderGroupLayoutFields(groupState = {}) {
  if (!groupState || typeof groupState !== "object") return;
  [
    "groupX",
    "groupY",
    "groupWidth",
    "groupHeight",
    "groupScale",
    "groupZIndex",
    "textX",
    "textY"
  ].forEach((field) => {
    if (Object.prototype.hasOwnProperty.call(groupState, field)) {
      delete groupState[field];
    }
  });
}

function stripThemeBuilderParentState(themeState = {}, parentId = "") {
  if (!themeState || typeof themeState !== "object" || !parentId) return false;
  let changed = false;

  if (themeState?.parents?.[parentId]) {
    delete themeState.parents[parentId];
    changed = true;
  }
  if (themeState?.groups?.[parentId]) {
    delete themeState.groups[parentId];
    changed = true;
  }
  if (themeState?.elements?.[parentId]) {
    delete themeState.elements[parentId];
    changed = true;
  }

  return changed;
}

function normalizeCompassHeaderThemeBuilderState(themeState = {}) {
  if (themeState?.groups?.["compass-main"]?.["compass-header"]) {
    delete themeState.groups["compass-main"]["compass-header"];
    if (!Object.keys(themeState.groups["compass-main"]).length) {
      delete themeState.groups["compass-main"];
    }
  }

  const compassElements = themeState?.elements?.["compass-main"];
  if (!compassElements || typeof compassElements !== "object") return;

  [
    "compass-header",
    "compass-header-div",
    "card-title",
    "compass-profile-copy",
    "compass-source-pill"
  ].forEach((elementId) => {
    const elementState = compassElements[elementId];
    if (!elementState || typeof elementState !== "object") return;
    stripThemeBuilderElementLayoutFields(elementState);
    if (!Object.keys(elementState).length) {
      delete compassElements[elementId];
    }
  });

  if (!Object.keys(compassElements).length) {
    delete themeState.elements["compass-main"];
  }
}

function normalizeLoadoutThemeBuilderState(themeState = {}) {
  const loadoutParent = themeState?.parents?.["loadout-card"];
  if (loadoutParent && typeof loadoutParent === "object") {
    stripThemeBuilderParentChildLayoutFields(loadoutParent);
    if (!Object.keys(loadoutParent).length) {
      delete themeState.parents["loadout-card"];
    }
  }

  const loadoutGroups = themeState?.groups?.["loadout-card"];
  if (loadoutGroups && typeof loadoutGroups === "object") {
    Object.keys(loadoutGroups).forEach((groupId) => {
      const groupState = loadoutGroups[groupId];
      if (!groupState || typeof groupState !== "object") {
        delete loadoutGroups[groupId];
        return;
      }
      stripThemeBuilderGroupLayoutFields(groupState);
      if (!Object.keys(groupState).length) {
        delete loadoutGroups[groupId];
      }
    });
    if (!Object.keys(loadoutGroups).length) {
      delete themeState.groups["loadout-card"];
    }
  }

  const loadoutElements = themeState?.elements?.["loadout-card"];
  if (loadoutElements && typeof loadoutElements === "object") {
    Object.keys(loadoutElements).forEach((elementId) => {
      const elementState = loadoutElements[elementId];
      if (!elementState || typeof elementState !== "object") {
        delete loadoutElements[elementId];
        return;
      }
      stripThemeBuilderElementLayoutFields(elementState);
      if (!Object.keys(elementState).length) {
        delete loadoutElements[elementId];
      }
    });
    if (!Object.keys(loadoutElements).length) {
      delete themeState.elements["loadout-card"];
    }
  }
}

function normalizeStatsSummaryThemeBuilderState(themeState = {}) {
  const parentId = "stats-summary-card";
  const preservedGroupIds = new Set(["stats-summary-left", "stats-summary-right"]);

  const parentState = themeState?.parents?.[parentId];
  if (parentState && typeof parentState === "object") {
    stripThemeBuilderParentChildLayoutFields(parentState);
    if (!Object.keys(parentState).length) {
      delete themeState.parents[parentId];
    }
  }

  const groupStates = themeState?.groups?.[parentId];
  if (groupStates && typeof groupStates === "object") {
    Object.keys(groupStates).forEach((groupId) => {
      const groupState = groupStates[groupId];
      if (!groupState || typeof groupState !== "object") {
        delete groupStates[groupId];
        return;
      }
      if (!preservedGroupIds.has(groupId)) {
        stripThemeBuilderGroupLayoutFields(groupState);
      }
      if (!Object.keys(groupState).length) {
        delete groupStates[groupId];
      }
    });
    if (!Object.keys(groupStates).length) {
      delete themeState.groups[parentId];
    }
  }

  const elementStates = themeState?.elements?.[parentId];
  if (elementStates && typeof elementStates === "object") {
    Object.keys(elementStates).forEach((elementId) => {
      const elementState = elementStates[elementId];
      if (!elementState || typeof elementState !== "object") {
        delete elementStates[elementId];
        return;
      }
      stripThemeBuilderElementLayoutFields(elementState);
      if (!Object.keys(elementState).length) {
        delete elementStates[elementId];
      }
    });
    if (!Object.keys(elementStates).length) {
      delete themeState.elements[parentId];
    }
  }
}

function normalizeInsightsTopThemeBuilderState(themeState = {}) {
  const parentId = "insights-top-card";
  const stateVersion = Number(themeState?.__insightsTopStateVersion || 0);
  if (stateVersion >= 2) return;

  const hadState = Boolean(
    themeState?.parents?.[parentId]
    || themeState?.groups?.[parentId]
    || themeState?.elements?.[parentId]
  );

  if (themeState?.parents?.[parentId]) {
    delete themeState.parents[parentId];
  }
  if (themeState?.groups?.[parentId]) {
    delete themeState.groups[parentId];
  }
  if (themeState?.elements?.[parentId]) {
    delete themeState.elements[parentId];
  }

  themeState.__insightsTopStateVersion = 2;

  if (hadState) {
    themeBuilderNeedsSave = true;
  }
}

function normalizeInsightsActionThemeBuilderState(themeState = {}) {
  const parentId = "insights-action-card";
  const parentState = themeState?.parents?.[parentId];
  let changed = false;

  if (parentState && typeof parentState === "object") {
    [
      ["contentScaleX", "1"],
      ["contentScaleY", "1"],
      ["contentShiftX", "0"],
      ["contentShiftY", "0"],
      ["contentOrigin", "center top"]
    ].forEach(([field, value]) => {
      if (String(parentState[field] ?? "") !== value) {
        parentState[field] = value;
        changed = true;
      }
    });
    stripThemeBuilderParentChildLayoutFields(parentState);
  }

  const groupStates = themeState?.groups?.[parentId];
  if (groupStates && typeof groupStates === "object") {
    Object.keys(groupStates).forEach((groupId) => {
      const groupState = groupStates[groupId];
      if (!groupState || typeof groupState !== "object") {
        delete groupStates[groupId];
        changed = true;
        return;
      }
      const before = JSON.stringify(groupState);
      stripThemeBuilderGroupLayoutFields(groupState);
      if (JSON.stringify(groupState) !== before) changed = true;
      if (!Object.keys(groupState).length) {
        delete groupStates[groupId];
        changed = true;
      }
    });
    if (!Object.keys(groupStates).length) {
      delete themeState.groups[parentId];
      changed = true;
    }
  }

  const elementStates = themeState?.elements?.[parentId];
  if (elementStates && typeof elementStates === "object") {
    Object.keys(elementStates).forEach((elementId) => {
      const elementState = elementStates[elementId];
      if (!elementState || typeof elementState !== "object") {
        delete elementStates[elementId];
        changed = true;
        return;
      }
      const before = JSON.stringify(elementState);
      stripThemeBuilderElementLayoutFields(elementState);
      if (JSON.stringify(elementState) !== before) changed = true;
      if (!Object.keys(elementState).length) {
        delete elementStates[elementId];
        changed = true;
      }
    });
    if (!Object.keys(elementStates).length) {
      delete themeState.elements[parentId];
      changed = true;
    }
  }

  if (Number(themeState?.__insightsActionStateVersion || 0) < 3) {
    themeState.__insightsActionStateVersion = 3;
    changed = true;
  }

  if (changed) {
    themeBuilderNeedsSave = true;
  }
}

function normalizeStatsBreakdownThemeBuilderState(themeState = {}) {
  const parentId = "stats-breakdown-card";
  const stateVersion = Number(themeState?.__statsBreakdownStateVersion || 0);
  if (stateVersion >= 1) return;

  const hadState = Boolean(
    themeState?.parents?.[parentId]
    || themeState?.groups?.[parentId]
    || themeState?.elements?.[parentId]
  );

  normalizeCardLayoutThemeBuilderState(themeState, parentId);
  themeState.__statsBreakdownStateVersion = 1;

  if (hadState) {
    themeBuilderNeedsSave = true;
  }
}

function normalizeThemeBuilderModalState(themeState = {}) {
  const stateVersion = Number(themeState?.__modalOverlayStateVersion || 0);
  if (stateVersion >= 1) return;

  let hadState = false;
  THEME_BUILDER_MODAL_PARENT_IDS.forEach((parentId) => {
    hadState = stripThemeBuilderParentState(themeState, parentId) || hadState;
  });

  themeState.__modalOverlayStateVersion = 1;

  if (hadState) {
    themeBuilderNeedsSave = true;
  }
}

function normalizeCardLayoutThemeBuilderState(themeState = {}, parentId = "") {
  if (!parentId) return;

  const parentState = themeState?.parents?.[parentId];
  if (parentState && typeof parentState === "object") {
    stripThemeBuilderParentChildLayoutFields(parentState);
    if (!Object.keys(parentState).length) {
      delete themeState.parents[parentId];
    }
  }

  const groupStates = themeState?.groups?.[parentId];
  if (groupStates && typeof groupStates === "object") {
    Object.keys(groupStates).forEach((groupId) => {
      const groupState = groupStates[groupId];
      if (!groupState || typeof groupState !== "object") {
        delete groupStates[groupId];
        return;
      }
      stripThemeBuilderGroupLayoutFields(groupState);
      if (!Object.keys(groupState).length) {
        delete groupStates[groupId];
      }
    });
    if (!Object.keys(groupStates).length) {
      delete themeState.groups[parentId];
    }
  }

  const elementStates = themeState?.elements?.[parentId];
  if (elementStates && typeof elementStates === "object") {
    Object.keys(elementStates).forEach((elementId) => {
      const elementState = elementStates[elementId];
      if (!elementState || typeof elementState !== "object") {
        delete elementStates[elementId];
        return;
      }
      stripThemeBuilderElementLayoutFields(elementState);
      if (!Object.keys(elementState).length) {
        delete elementStates[elementId];
      }
    });
    if (!Object.keys(elementStates).length) {
      delete themeState.elements[parentId];
    }
  }
}

function resetDefaultThemeBuilderState(themeState = {}) {
  if (!themeState || typeof themeState !== "object") return themeState;
  const hadCustomState =
    Object.values(themeState.overlayAssets || {}).some(Boolean) ||
    Object.values(themeState.globals || {}).some(Boolean) ||
    (Array.isArray(themeState.importedFonts) && themeState.importedFonts.length > 0) ||
    Object.keys(themeState.parents || {}).length > 0 ||
    Object.keys(themeState.elements || {}).length > 0 ||
    Object.keys(themeState.groups || {}).length > 0;
  themeState.overlayAssets = {};
  themeState.globals = {};
  themeState.importedFonts = [];
  themeState.parents = {};
  themeState.elements = {};
  themeState.groups = {};
  return hadCustomState;
}

function normalizeLoadedThemeBuilderState(state = {}) {
  Object.entries(state || {}).forEach(([themeKey, themeState]) => {
    if (themeState && typeof themeState === "object") {
      if (String(themeKey || "").toLowerCase() === "default") {
        if (resetDefaultThemeBuilderState(themeState)) {
          themeBuilderNeedsSave = true;
        }
      }
      normalizeThemeBuilderModalState(themeState);
      normalizeCompassHeaderThemeBuilderState(themeState);
      normalizeLoadoutThemeBuilderState(themeState);
      normalizeStatsSummaryThemeBuilderState(themeState);
      normalizeStatsBreakdownThemeBuilderState(themeState);
      normalizeInsightsTopThemeBuilderState(themeState);
      normalizeInsightsActionThemeBuilderState(themeState);
      ["compass-main", "stats-maps-card"].forEach((parentId) => {
        normalizeCardLayoutThemeBuilderState(themeState, parentId);
      });
    }
  });
  return state;
}

function mergeBakedThemeBuilderState(storedState = {}) {
  const merged = cloneThemeBuilderValue(storedState);
  Object.entries(BAKED_THEME_BUILDER_STATE).forEach(([themeKey, bakedTheme]) => {
    const existingTheme = merged[themeKey] && typeof merged[themeKey] === "object" ? merged[themeKey] : {};
    const storedMatchesBakedSnapshot = existingTheme.__bakedSnapshotCapturedAt === BAKED_THEME_SNAPSHOT_CAPTURED_AT;
    const first = storedMatchesBakedSnapshot ? cloneThemeBuilderValue(bakedTheme) : existingTheme;
    const second = storedMatchesBakedSnapshot ? existingTheme : cloneThemeBuilderValue(bakedTheme);
    merged[themeKey] = {
      ...first,
      ...second,
      __bakedSnapshotCapturedAt: BAKED_THEME_SNAPSHOT_CAPTURED_AT,
      overlayAssets: {
        ...(first.overlayAssets || {}),
        ...(second.overlayAssets || {})
      },
      globals: {
        ...(first.globals || {}),
        ...(second.globals || {})
      },
      parents: {
        ...(first.parents || {}),
        ...(second.parents || {})
      },
      groups: {
        ...(first.groups || {}),
        ...(second.groups || {})
      },
      elements: {
        ...(first.elements || {}),
        ...(second.elements || {})
      },
      importedFonts: second.importedFonts || first.importedFonts || []
    };
  });
  return merged;
}

function flushThemeBuilderStateSave() {
  if (THEME_BUILDER_LAUNCH_LOCKED) return;
  Object.values(themeBuilderState || {}).forEach((themeState) => {
    if (themeState && typeof themeState === "object") {
      themeState.__bakedSnapshotCapturedAt = BAKED_THEME_SNAPSHOT_CAPTURED_AT;
    }
  });
  localStorage.setItem(THEME_BUILDER_STORAGE_KEY, JSON.stringify(themeBuilderState));
  queuePersistentAccountSave("theme-builder");
}

function saveThemeBuilderState(options = {}) {
  if (THEME_BUILDER_LAUNCH_LOCKED) return;
  const immediate = typeof options === "boolean" ? options : options.immediate !== false;
  if (immediate) {
    if (themeBuilderSaveTimer) {
      clearTimeout(themeBuilderSaveTimer);
      themeBuilderSaveTimer = 0;
    }
    flushThemeBuilderStateSave();
    return;
  }
  if (themeBuilderSaveTimer) {
    clearTimeout(themeBuilderSaveTimer);
  }
  themeBuilderSaveTimer = window.setTimeout(() => {
    themeBuilderSaveTimer = 0;
    flushThemeBuilderStateSave();
  }, 140);
}

function getCurrentThemeBuilderThemeKey() {
  return document.body?.dataset?.theme || "default";
}

function getThemeBuilderUrlParams() {
  try {
    return new URLSearchParams(window.location.search || "");
  } catch (_error) {
    return new URLSearchParams("");
  }
}

function isLocalThemeBuilderHost() {
  const host = window.location.hostname;
  return !host || ["localhost", "127.0.0.1", "::1"].includes(host);
}

function syncThemeBuilderAccessFromUrl() {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    localStorage.removeItem(THEME_BUILDER_ACCESS_STORAGE_KEY);
    return;
  }
  const params = getThemeBuilderUrlParams();
  if (params.has("hideThemeBuilder")) {
    localStorage.removeItem(THEME_BUILDER_ACCESS_STORAGE_KEY);
    return;
  }
  if (params.has("themeBuilder") || params.has("designerTools")) {
    localStorage.setItem(THEME_BUILDER_ACCESS_STORAGE_KEY, "1");
  }
}

function isCurrentUserThemeBuilderAdmin(user = currentAuthUser) {
  const email = String(user?.email || "").trim().toLowerCase();
  const metadataRole = String(user?.app_metadata?.role || user?.user_metadata?.role || user?.user_metadata?.designerRole || "").trim().toLowerCase();
  const emailAllowed = email && THEME_BUILDER_ADMIN_EMAILS.map(entry => String(entry).trim().toLowerCase()).includes(email);
  return Boolean(
    emailAllowed ||
    ["admin", "designer", "theme-designer", "owner"].includes(metadataRole) ||
    user?.app_metadata?.theme_builder === true ||
    user?.user_metadata?.theme_builder === true
  );
}

function normalizeHenrikRegion(input = "") {
  const raw = String(input || "").trim().toLowerCase();
  if (["na", "americas", "us"].includes(raw)) return "na";
  if (["latam", "br"].includes(raw)) return raw;
  if (["eu", "euw", "eune", "tr", "ru", "europe"].includes(raw)) return "eu";
  if (["kr"].includes(raw)) return "kr";
  if (["ap", "jp", "oce", "asia"].includes(raw)) return "ap";
  return "na";
}

function isPremiumThemeQaUser(user = currentAuthUser) {
  const email = String(user?.email || "").trim().toLowerCase();
  return Boolean(
    email &&
    PREMIUM_THEME_QA_EMAILS.map(entry => String(entry || "").trim().toLowerCase()).includes(email)
  );
}

function shouldShowThemeBuilder() {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    archiveThemeBuilderLocalStorageForLaunchLock();
    return false;
  }
  syncThemeBuilderAccessFromUrl();
  const params = getThemeBuilderUrlParams();
  if (params.has("hideThemeBuilder")) return false;
  return Boolean(
    isLocalThemeBuilderHost() ||
    localStorage.getItem(THEME_BUILDER_ACCESS_STORAGE_KEY) === "1" ||
    isCurrentUserThemeBuilderAdmin()
  );
}

function ensureThemeBuilderThemeState(themeKey = getCurrentThemeBuilderThemeKey()) {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    return { overlayAssets: {}, parents: {}, elements: {}, groups: {}, globals: {}, importedFonts: [] };
  }
  const key = String(themeKey || "default");
  if (!themeBuilderState[key] || typeof themeBuilderState[key] !== "object") {
    themeBuilderState[key] = {
      overlayAssets: {},
      parents: {},
      elements: {},
      groups: {}
    };
  }
  if (!themeBuilderState[key].overlayAssets || typeof themeBuilderState[key].overlayAssets !== "object") {
    themeBuilderState[key].overlayAssets = {};
  }
  if (!themeBuilderState[key].globals || typeof themeBuilderState[key].globals !== "object") {
    themeBuilderState[key].globals = {};
  }
  if (!Array.isArray(themeBuilderState[key].importedFonts)) {
    themeBuilderState[key].importedFonts = [];
  }
  if (!themeBuilderState[key].parents || typeof themeBuilderState[key].parents !== "object") {
    themeBuilderState[key].parents = {};
  }
  if (!themeBuilderState[key].elements || typeof themeBuilderState[key].elements !== "object") {
    themeBuilderState[key].elements = {};
  }
  if (!themeBuilderState[key].groups || typeof themeBuilderState[key].groups !== "object") {
    themeBuilderState[key].groups = {};
  }
  if (migrateThemeBuilderThemeStateToV2(themeBuilderState[key])) {
    themeBuilderNeedsSave = true;
  }
  return themeBuilderState[key];
}

function migrateThemeBuilderThemeStateToV2(themeState) {
  if (!themeState || typeof themeState !== "object" || themeState.builderVersion === THEME_BUILDER_VERSION) return false;
  const legacyChildFields = new Set(THEME_BUILDER_CHILD_SNAPSHOT_FIELDS);
  if (themeState.elements && Object.keys(themeState.elements).length) {
    themeState.legacyElementsV1 = cloneThemeBuilderValue(themeState.elements);
    themeState.elements = {};
  }
  Object.values(themeState.parents || {}).forEach((parentState) => {
    if (!parentState || typeof parentState !== "object") return;
    legacyChildFields.forEach(field => delete parentState[field]);
  });
  themeState.builderVersion = THEME_BUILDER_VERSION;
  return true;
}

function cleanupThemeBuilderThemeState(themeKey = getCurrentThemeBuilderThemeKey()) {
  const key = String(themeKey || "default");
  const state = themeBuilderState[key];
  if (!state) return;
  ["elements", "groups"].forEach((sectionKey) => {
    const section = state[sectionKey];
    if (!section || typeof section !== "object") return;
    Object.keys(section).forEach((parentId) => {
      const parentMap = section[parentId];
      if (!parentMap || typeof parentMap !== "object") {
        delete section[parentId];
        return;
      }
      Object.keys(parentMap).forEach((entryId) => {
        const entry = parentMap[entryId];
        if (!entry || typeof entry !== "object" || !Object.keys(entry).length) {
          delete parentMap[entryId];
        }
      });
      if (!Object.keys(parentMap).length) {
        delete section[parentId];
      }
    });
  });
  const hasOverlayAssets = Object.values(state.overlayAssets || {}).some(Boolean);
  const hasGlobals = Object.values(state.globals || {}).some(Boolean);
  const hasImportedFonts = Array.isArray(state.importedFonts) && state.importedFonts.length > 0;
  const hasParents = Object.values(state.parents || {}).some(parentState => parentState && Object.keys(parentState).length);
  const hasElements = Object.values(state.elements || {}).some(parentMap =>
    parentMap && Object.values(parentMap).some(entry => entry && Object.keys(entry).length)
  );
  const hasGroups = Object.values(state.groups || {}).some(parentMap =>
    parentMap && Object.values(parentMap).some(entry => entry && Object.keys(entry).length)
  );
  if (!hasOverlayAssets && !hasGlobals && !hasImportedFonts && !hasParents && !hasElements && !hasGroups) {
    delete themeBuilderState[key];
  }
}

function stripCssUnit(value = "") {
  return String(value || "").trim().replace(/px$/i, "");
}

function rgbColorToHex(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "#ffffff";
  if (/^#[0-9a-f]{6}$/i.test(raw)) return raw;
  if (/^#[0-9a-f]{3}$/i.test(raw)) {
    return `#${raw[1]}${raw[1]}${raw[2]}${raw[2]}${raw[3]}${raw[3]}`;
  }
  const match = raw.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
  if (!match) return "#ffffff";
  const parts = match.slice(1, 4).map(part => Number(part).toString(16).padStart(2, "0"));
  return `#${parts.join("")}`;
}

function matchThemeBuilderFontOption(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  const exact = getThemeBuilderFontOptions().find(option => option.value.toLowerCase() === raw);
  if (exact) return exact.value;
  const fuzzy = getThemeBuilderFontOptions().find(option => raw.includes(option.label.toLowerCase()) || raw.includes(option.value.replace(/["']/g, "").toLowerCase().split(",")[0]));
  return fuzzy?.value || "inherit";
}

function getThemeBuilderFontOptions(themeKey = getCurrentThemeBuilderThemeKey()) {
  const importedFonts = ensureThemeBuilderThemeState(themeKey).importedFonts || [];
  const merged = [...THEME_BUILDER_FONT_OPTIONS];
  importedFonts.forEach((font) => {
    if (!font?.value || merged.some(option => option.value === font.value)) return;
    merged.push({ value: font.value, label: font.label || font.value, source: font.source || "imported" });
  });
  return merged;
}

function getThemeBuilderFontPresetById(presetId = "") {
  return THEME_BUILDER_FONT_PRESET_GROUPS.find(group => group.id === String(presetId || "").trim()) || null;
}

function buildThemeBuilderFontImportCss() {
  const urls = new Set();
  Object.values(themeBuilderState || {}).forEach((themeState) => {
    (themeState?.importedFonts || []).forEach((font) => {
      if (font?.importUrl) urls.add(font.importUrl);
    });
  });
  return Array.from(urls).map(url => `@import url("${escapeCssString(url)}");`).join("\n");
}

function applyThemeBuilderFontImports() {
  if (THEME_BUILDER_LAUNCH_LOCKED) {
    document.getElementById(THEME_BUILDER_FONT_IMPORT_STYLE_ID)?.remove();
    return;
  }
  let style = document.getElementById(THEME_BUILDER_FONT_IMPORT_STYLE_ID);
  const css = buildThemeBuilderFontImportCss();
  if (!css) {
    style?.remove();
    return;
  }
  if (!style) {
    style = document.createElement("style");
    style.id = THEME_BUILDER_FONT_IMPORT_STYLE_ID;
    document.head.appendChild(style);
  }
  style.textContent = css;
}

function importThemeBuilderFontPreset(themeKey, presetId) {
  const preset = getThemeBuilderFontPresetById(presetId);
  if (!preset) return;
  const themeState = ensureThemeBuilderThemeState(themeKey);
  const importedFonts = Array.isArray(themeState.importedFonts) ? themeState.importedFonts : [];
  preset.fonts.forEach((font) => {
    if (importedFonts.some(entry => entry.value === font.family)) return;
    importedFonts.push({
      id: `${preset.id}:${font.label}`,
      presetId: preset.id,
      label: `${preset.label} - ${font.label}`,
      value: font.family,
      importUrl: font.importUrl,
      source: preset.label
    });
  });
  themeState.importedFonts = importedFonts;
  persistAndApplyThemeBuilder(themeKey);
  renderThemeBuilderPanel();
}

function removeThemeBuilderImportedFont(themeKey, fontValue) {
  const themeState = ensureThemeBuilderThemeState(themeKey);
  themeState.importedFonts = (themeState.importedFonts || []).filter(font => font?.value !== fontValue);
  persistAndApplyThemeBuilder(themeKey);
  renderThemeBuilderPanel();
}

function splitThemeBuilderSelectorList(selectorList = "") {
  const raw = String(selectorList || "").trim();
  if (!raw) return [];

  const selectors = [];
  let current = "";
  let depthParen = 0;
  let depthBracket = 0;
  let quote = "";
  let escaped = false;

  for (let index = 0; index < raw.length; index += 1) {
    const char = raw[index];

    if (escaped) {
      current += char;
      escaped = false;
      continue;
    }

    if (char === "\\") {
      current += char;
      escaped = true;
      continue;
    }

    if (quote) {
      current += char;
      if (char === quote) quote = "";
      continue;
    }

    if (char === "\"" || char === "'") {
      current += char;
      quote = char;
      continue;
    }

    if (char === "(") {
      depthParen += 1;
      current += char;
      continue;
    }

    if (char === ")") {
      depthParen = Math.max(0, depthParen - 1);
      current += char;
      continue;
    }

    if (char === "[") {
      depthBracket += 1;
      current += char;
      continue;
    }

    if (char === "]") {
      depthBracket = Math.max(0, depthBracket - 1);
      current += char;
      continue;
    }

    if (char === "," && depthParen === 0 && depthBracket === 0) {
      const next = current.trim();
      if (next) selectors.push(next);
      current = "";
      continue;
    }

    current += char;
  }

  const tail = current.trim();
  if (tail) selectors.push(tail);
  return selectors;
}

function getFirstSelectorMatch(selectorList = "") {
  const selectors = splitThemeBuilderSelectorList(selectorList);

  for (const selector of selectors) {
    try {
      const element = document.querySelector(selector);
      if (element) return element;
    } catch (error) {
      console.warn("[ThemeBuilder] Invalid selector skipped in getFirstSelectorMatch:", selector, error);
    }
  }

  return null;
}

function getThemeBuilderSelectorMatches(selectorList = "") {
  const selectors = splitThemeBuilderSelectorList(selectorList);
  const seen = new Set();
  const matches = [];

  selectors.forEach((selector) => {
    try {
      document.querySelectorAll(selector).forEach((element) => {
        if (seen.has(element)) return;
        seen.add(element);
        matches.push(element);
      });
    } catch (error) {
      console.warn("[ThemeBuilder] Invalid selector skipped in getThemeBuilderSelectorMatches:", selector, error);
    }
  });

  return matches;
}

function escapeCssIdent(value = "") {
  const raw = String(value || "");
  if (window.CSS?.escape) return CSS.escape(raw);
  return raw.replace(/[^a-zA-Z0-9_-]/g, "\\$&");
}

function getThemeBuilderParentElement(config) {
  return document.querySelector(config.selector);
}

function formatThemeBuilderElementName(value = "") {
  const cleaned = String(value || "")
    .replace(/^#/, "")
    .replace(/^\./, "")
    .replace(/[.[\]="'#]+/g, " ")
    .replace(/([a-z0-9])([A-Z])/g, "$1 $2")
    .replace(/[-_]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!cleaned) return "Element";
  return cleaned
    .split(" ")
    .map((part) => {
      const lower = part.toLowerCase();
      if (["rr", "svg", "ui", "id", "url", "kda", "acs"].includes(lower)) return lower.toUpperCase();
      return `${lower.charAt(0).toUpperCase()}${lower.slice(1)}`;
    })
    .join(" ");
}

function slugThemeBuilderName(value = "") {
  return formatThemeBuilderElementName(value)
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "") || "element";
}

function getThemeBuilderElementNameBase(element) {
  if (!element) return "element";
  const tag = element.tagName.toLowerCase();
  if (element.id) return `#${element.id}`;
  const classes = Array.from(element.classList || []).filter(Boolean);
  if (classes.length) return `.${classes.slice(0, 3).join(".")}`;
  const dataKey = Array.from(element.attributes || []).find(attr => attr.name.startsWith("data-"));
  if (dataKey) return `${tag}[${dataKey.name}]`;
  return tag;
}

function getThemeBuilderElementTextHint(element) {
  const directText = Array.from(element?.childNodes || [])
    .filter(node => node.nodeType === Node.TEXT_NODE)
    .map(node => node.textContent || "")
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
  const fallbackText = element?.children?.length <= 1
    ? String(element?.textContent || "").replace(/\s+/g, " ").trim()
    : "";
  const text = directText || fallbackText;
  if (!text || text.length > 48) return "";
  return text;
}

function getThemeBuilderSemanticName(element) {
  if (!element) return "Element";
  if (element.id) return formatThemeBuilderElementName(element.id);
  const usefulClasses = Array.from(element.classList || [])
    .filter(name => !/^(active|is-|has-|ui-|agent-neutral|focus-neutral|loading)$/i.test(name))
    .slice(0, 3);
  if (usefulClasses.length) return formatThemeBuilderElementName(usefulClasses.join(" "));
  const dataAttr = Array.from(element.attributes || []).find(attr => attr.name.startsWith("data-") && attr.value);
  if (dataAttr) return `${formatThemeBuilderElementName(dataAttr.name)} ${formatThemeBuilderElementName(dataAttr.value)}`;
  return formatThemeBuilderElementName(element.tagName.toLowerCase());
}

function getThemeBuilderElementContextName(element, parentElement) {
  let current = element?.parentElement || null;
  while (current && current !== parentElement) {
    const name = getThemeBuilderSemanticName(current);
    if (!["Div", "Span", "Element"].includes(name)) return name;
    current = current.parentElement;
  }
  return "";
}

function getThemeBuilderElementFriendlyLabel(element, parentElement, occurrence, hasDuplicates) {
  const ownName = getThemeBuilderSemanticName(element);
  const contextName = getThemeBuilderElementContextName(element, parentElement);
  const textHint = getThemeBuilderElementTextHint(element);
  const genericMap = {
    Div: "Wrapper",
    Span: "Text",
    Strong: "Value",
    Small: "Small Text",
    P: "Paragraph",
    Img: "Image",
    Svg: "SVG",
    Circle: "Circle",
    Polygon: "Polygon",
    Line: "Line",
    Text: "SVG Text"
  };
  const baseName = genericMap[ownName] || ownName;
  const contextualName = contextName && !baseName.toLowerCase().includes(contextName.toLowerCase())
    ? `${contextName} ${baseName}`
    : baseName;
  const duplicateSuffix = hasDuplicates ? ` ${occurrence}` : "";
  const textSuffix = textHint && !contextualName.toLowerCase().includes(textHint.toLowerCase())
    ? ` - ${textHint}`
    : "";
  return `${contextualName}${duplicateSuffix}${textSuffix}`;
}

function getThemeBuilderElementIdBase(element, parentElement) {
  const ownName = getThemeBuilderSemanticName(element);
  const contextName = getThemeBuilderElementContextName(element, parentElement);
  const generic = ["Div", "Span", "Strong", "Small", "P", "Text"].includes(ownName);
  const label = generic && contextName ? `${contextName} ${ownName}` : ownName;
  return slugThemeBuilderName(label);
}

const THEME_BUILDER_ACTION_TARGET_SELECTOR = [
  "button",
  "input:not([type=\"hidden\"])",
  "select",
  "textarea",
  "a[href]",
  "[role=\"button\"]",
  "[role=\"tab\"]",
  "[role=\"switch\"]",
  "[role=\"checkbox\"]",
  "[role=\"radio\"]"
].join(", ");

const THEME_BUILDER_VISIBLE_OBJECT_GROUP_INCLUDE_TOKENS = [
  "agent-frame",
  "summary-shell",
  "compass-summary-shell",
  "frame",
  "chart",
  "graph",
  "progress",
  "bar",
  "card",
  "hero",
  "list",
  "feed",
  "notes",
  "breakdown",
  "proof",
  "impact",
  "scorebox",
  "scoreboard",
  "performance",
  "map",
  "agent",
  "timeline",
  "pill"
];

const THEME_BUILDER_VISIBLE_OBJECT_GROUP_EXCLUDE_TOKENS = [
  "content",
  "row",
  "column",
  "body",
  "shell",
  "wrap",
  "wrapper",
  "panels",
  "field",
  "fields",
  "nav",
  "selector"
];

const THEME_BUILDER_ALWAYS_VISIBLE_OBJECT_GROUP_IDS = new Set([
  "compass-summary-shell",
  "stats-map-list",
  "stats-breakdown",
  "insights-top-header",
  "insights-list",
  "insights-all-cards"
]);

function getThemeBuilderDirectTextContent(element) {
  return Array.from(element?.childNodes || [])
    .filter(node => node.nodeType === Node.TEXT_NODE)
    .map(node => node.textContent || "")
    .join(" ")
    .replace(/\s+/g, " ")
    .trim();
}

function getThemeBuilderReadableElementContent(element) {
  if (!element) return "";

  const value = "value" in element ? String(element.value || "").trim() : "";
  const selectedOption = element.tagName?.toLowerCase() === "select"
    ? String(element.options?.[element.selectedIndex]?.textContent || "").trim()
    : "";
  const placeholder = String(element.getAttribute?.("placeholder") || "").trim();
  const ariaLabel = String(element.getAttribute?.("aria-label") || "").trim();
  const text = String(element.innerText || element.textContent || "")
    .replace(/\s+/g, " ")
    .trim();

  return [value, selectedOption, text, placeholder, ariaLabel]
    .find(entry => entry && entry.length)
    ?.slice(0, 120) || "";
}

function isThemeBuilderElementVisible(element) {
  if (!element || !element.isConnected) return false;
  if (element.closest("[hidden]")) return false;

  const style = getComputedStyle(element);
  if (style.display === "none" || style.visibility === "hidden") return false;
  if (Number(style.opacity) === 0) return false;

  const rect = element.getBoundingClientRect?.();
  return Boolean(rect && rect.width >= 1 && rect.height >= 1);
}

function isThemeBuilderActionElement(element) {
  return Boolean(element?.matches?.(THEME_BUILDER_ACTION_TARGET_SELECTOR));
}

function isThemeBuilderMediaElement(element) {
  if (!element) return false;
  const tag = element.tagName?.toLowerCase?.() || "";
  if (!["img", "svg", "canvas", "video", "picture"].includes(tag)) return false;
  if (tag === "svg" && element.parentElement?.closest?.("svg")) return false;
  return true;
}

function getThemeBuilderTextSectionName(element, parentElement) {
  const tag = element?.tagName?.toLowerCase?.() || "";
  const tokens = [];
  let current = element;

  while (current && current !== parentElement) {
    if (current.id) tokens.push(current.id);
    tokens.push(...Array.from(current.classList || []));
    current = current.parentElement;
  }

  const joined = tokens.join(" ").toLowerCase();
  if (/footer|source|note|helper|credits|bottom/.test(joined)) return "Footer";
  if (/header|hero|title|heading|kicker/.test(joined) || /^h[1-6]$/.test(tag)) return "Header";
  if (/meta|sub|detail|description|desc|date|label|stat|score|tier|tag|pill/.test(joined)) return "Meta";
  return "Line";
}

function getThemeBuilderActionKind(element) {
  if (!element) return "Control";
  const role = String(element.getAttribute?.("role") || "").toLowerCase();
  const type = String(element.getAttribute?.("type") || "").toLowerCase();
  const tag = element.tagName?.toLowerCase?.() || "";
  if (tag === "button" || role === "button") return "Button";
  if (tag === "select") return "Select";
  if (tag === "textarea") return "Text Area";
  if (tag === "a") return "Link";
  if (role === "tab") return "Tab";
  if (role === "switch" || type === "checkbox" || role === "checkbox") return "Toggle";
  if (type === "range") return "Slider";
  if (tag === "input") return "Input";
  return "Control";
}

function getThemeBuilderMediaKind(element) {
  if (!element) return "Image";
  const tag = element.tagName?.toLowerCase?.() || "";
  const descriptor = `${element.id || ""} ${Array.from(element.classList || []).join(" ")}`.toLowerCase();
  if (/chart|graph/.test(descriptor)) return "Chart";
  if (/icon|avatar|logo/.test(descriptor)) return "Icon";
  if (tag === "svg") return "Graphic";
  if (tag === "video") return "Video";
  if (tag === "canvas") return "Canvas";
  return "Image";
}

function isThemeBuilderLeafTextElement(element, parentElement) {
  if (!element || !isThemeBuilderElementVisible(element)) return false;
  if (isThemeBuilderActionElement(element) || isThemeBuilderMediaElement(element)) return false;

  const enclosingAction = element.closest(THEME_BUILDER_ACTION_TARGET_SELECTOR);
  if (enclosingAction && enclosingAction !== element && parentElement?.contains(enclosingAction)) return false;
  if (element.closest("svg") && element.tagName?.toLowerCase?.() !== "svg") return false;

  const readableText = getThemeBuilderReadableElementContent(element);
  if (!readableText) return false;

  const directText = getThemeBuilderDirectTextContent(element);
  const descriptor = `${element.id || ""} ${Array.from(element.classList || []).join(" ")}`.toLowerCase();
  const tag = element.tagName?.toLowerCase?.() || "";
  const looksTextLike = /^(h[1-6]|p|span|strong|small|label|li|dt|dd|figcaption|blockquote)$/.test(tag)
    || /\b(title|label|copy|text|value|meta|sub|detail|kicker|name|score|stat|tier|caption|desc|description|date|tone|focus|why|how|source|hero)\b/.test(descriptor);

  if (!directText && !looksTextLike) return false;

  const textBearingChildren = Array.from(element.children || []).filter((child) => {
    if (!isThemeBuilderElementVisible(child)) return false;
    if (isThemeBuilderActionElement(child) || isThemeBuilderMediaElement(child)) return true;
    return Boolean(getThemeBuilderReadableElementContent(child));
  });

  if (!directText && textBearingChildren.length) return false;
  return true;
}

function getThemeBuilderElementRoleLabel(target) {
  if (!target) return "element";
  if (target.role === "text") return "line";
  if (target.role === "action") return getThemeBuilderActionKind(target.element).toLowerCase();
  if (target.role === "media") return getThemeBuilderMediaKind(target.element).toLowerCase();
  return String(target.role || "element").toLowerCase();
}

function buildThemeBuilderTargetDisplayLabel(target, counters) {
  if (!target) return "Element";
  if (target.role === "text") {
    const section = target.sectionName || "Line";
    const key = `text:${section}`;
    counters[key] = (counters[key] || 0) + 1;
    return section === "Line"
      ? `Line ${counters[key]}`
      : `${section} Line ${counters[key]}`;
  }
  if (target.role === "action") {
    const actionKind = getThemeBuilderActionKind(target.element);
    const key = `action:${actionKind}`;
    counters[key] = (counters[key] || 0) + 1;
    return `${actionKind} ${counters[key]}`;
  }
  if (target.role === "media") {
    const mediaKind = getThemeBuilderMediaKind(target.element);
    const key = `media:${mediaKind}`;
    counters[key] = (counters[key] || 0) + 1;
    return `${mediaKind} ${counters[key]}`;
  }
  const key = `element:${target.role || "Element"}`;
  counters[key] = (counters[key] || 0) + 1;
  return `${formatThemeBuilderElementName(target.role || "Element")} ${counters[key]}`;
}

function isThemeBuilderVisibleObjectGroup(group) {
  if (!group?.selector) return false;
  if (isThemeBuilderAgentFrameGroup(group)) return true;
  if (THEME_BUILDER_ALWAYS_VISIBLE_OBJECT_GROUP_IDS.has(String(group.id || "").trim())) return true;

  const element = document.querySelector(group.selector);
  if (!isThemeBuilderElementVisible(element)) return false;
  if (isThemeBuilderActionElement(element) || isThemeBuilderMediaElement(element)) return false;

  const descriptor = `${group.id || ""} ${group.label || ""} ${group.selector || ""}`.toLowerCase();
  const style = element ? getComputedStyle(element) : null;
  const hasVisualBox = Boolean(style && (
    style.backgroundColor !== "rgba(0, 0, 0, 0)"
    || style.borderColor !== "rgba(0, 0, 0, 0)"
    || style.boxShadow !== "none"
  ));
  const hasIncludeToken = THEME_BUILDER_VISIBLE_OBJECT_GROUP_INCLUDE_TOKENS.some(token => descriptor.includes(token));

  if (THEME_BUILDER_VISIBLE_OBJECT_GROUP_EXCLUDE_TOKENS.some(token => descriptor.includes(token)) && !hasIncludeToken) {
    return false;
  }

  return hasVisualBox || hasIncludeToken;
}

function getThemeBuilderVisibleObjectGroups(parentId) {
  return getThemeBuilderGroupsForParent(parentId).filter(isThemeBuilderVisibleObjectGroup);
}

function getThemeBuilderVisualGroupRoot(config, element, parentElement) {
  if (!element || !parentElement) return element;
  if (isThemeBuilderActionElement(element) || isThemeBuilderMediaElement(element)) {
    return element;
  }
  const childRoot = config.childSelector ? element.closest(config.childSelector) : null;
  if (childRoot && childRoot !== parentElement && parentElement.contains(childRoot)) {
    return childRoot;
  }

  let directChild = element;
  let current = element;
  while (current?.parentElement && current.parentElement !== parentElement) {
    current = current.parentElement;
    if (current && current !== parentElement) directChild = current;
  }
  return directChild || element;
}

function getThemeBuilderElementRootKey(config, groupElement, parentElement, usedGroupIds = new Map()) {
  const selector = getThemeBuilderElementSelector(config, groupElement, parentElement);
  const baseId = getThemeBuilderElementIdBase(groupElement, parentElement);
  const useCount = (usedGroupIds.get(baseId) || 0) + 1;
  usedGroupIds.set(baseId, useCount);
  return {
    id: useCount > 1 ? `${baseId}-group-${useCount}` : `${baseId}-group`,
    selector
  };
}

function groupThemeBuilderElementTargets(targets = []) {
  const groups = new Map();
  targets.forEach((target) => {
    const groupId = target.groupId || "ungrouped";
    if (!groups.has(groupId)) {
      groups.set(groupId, {
        id: groupId,
        label: target.groupLabel || "Visual Group",
        selector: target.groupSelector || target.selector,
        role: target.groupRole || "group",
        depth: target.groupDepth ?? target.depth,
        order: target.order,
        targets: []
      });
    }
    groups.get(groupId).targets.push(target);
  });

  return [...groups.values()]
    .map((group) => {
      const sortedTargets = group.targets.slice().sort((a, b) => {
        const score = (target) => {
          if (target.isGroupRoot) return 0;
          if (["media", "action", "text"].includes(target.role)) return 1;
          if (target.role === "group") return 2;
          return 3;
        };
        return score(a) - score(b) || a.depth - b.depth || a.order - b.order;
      });
      const primaryCount = sortedTargets.filter(target => ["media", "action", "text"].includes(target.role)).length;
      const shellCount = sortedTargets.length - primaryCount;
      return {
        ...group,
        targets: sortedTargets,
        primaryCount,
        shellCount
      };
    })
    .sort((a, b) => a.order - b.order || a.depth - b.depth || a.label.localeCompare(b.label));
}

function getThemeBuilderElementSelectorPart(element) {
  const tag = element.tagName.toLowerCase();
  if (element.id) return `${tag}#${escapeCssIdent(element.id)}`;
  const classes = Array.from(element.classList || []).filter(Boolean);
  const classSelector = classes.length ? `.${classes.map(escapeCssIdent).join(".")}` : "";
  let part = `${tag}${classSelector}`;
  const parent = element.parentElement;
  if (parent) {
    const matchingSiblings = Array.from(parent.children).filter(child => child.matches(part));
    if (matchingSiblings.length > 1) {
      const sameTagSiblings = Array.from(parent.children).filter(child => child.tagName === element.tagName);
      part += `:nth-of-type(${sameTagSiblings.indexOf(element) + 1})`;
    }
  }
  return part;
}

function getThemeBuilderElementSelector(config, element, parentElement) {
  if (element.id && document.querySelectorAll(`#${escapeCssIdent(element.id)}`).length === 1) {
    return `#${escapeCssIdent(element.id)}`;
  }

  const parts = [];
  let current = element;
  while (current && current !== parentElement && current.nodeType === 1) {
    parts.unshift(getThemeBuilderElementSelectorPart(current));
    current = current.parentElement;
  }

  return parts.length ? `${config.selector} > ${parts.join(" > ")}` : config.selector;
}

function discoverThemeBuilderElementTargets(config) {
  const parentElement = getThemeBuilderParentElement(config);
  if (!parentElement) return [];
  const elements = Array.from(parentElement.querySelectorAll("*"))
    .filter(element => !["SCRIPT", "STYLE", "TEMPLATE"].includes(element.tagName))
    .filter(isThemeBuilderElementVisible);
  const actionTargets = [];
  const mediaTargets = [];
  const textTargets = [];

  elements.forEach((element) => {
    if (isThemeBuilderActionElement(element)) {
      const parentAction = element.parentElement?.closest?.(THEME_BUILDER_ACTION_TARGET_SELECTOR);
      if (!parentAction || parentAction === element || !parentElement.contains(parentAction)) {
        actionTargets.push({ element, role: "action" });
      }
      return;
    }

    if (isThemeBuilderMediaElement(element)) {
      const parentAction = element.closest(THEME_BUILDER_ACTION_TARGET_SELECTOR);
      if (!parentAction || parentAction === element || !parentElement.contains(parentAction)) {
        mediaTargets.push({ element, role: "media" });
      }
      return;
    }

    if (isThemeBuilderLeafTextElement(element, parentElement)) {
      textTargets.push({
        element,
        role: "text",
        sectionName: getThemeBuilderTextSectionName(element, parentElement)
      });
    }
  });

  const editableTargets = [...actionTargets, ...mediaTargets, ...textTargets].sort((a, b) => {
    const aPosition = a.element.compareDocumentPosition(b.element);
    if (aPosition & Node.DOCUMENT_POSITION_FOLLOWING) return -1;
    if (aPosition & Node.DOCUMENT_POSITION_PRECEDING) return 1;
    return 0;
  });
  const groupFirstOrder = new Map();
  const groupRootBases = new Map();
  const groupMetaByElement = new Map();

  editableTargets.forEach((entry, index) => {
    const groupElement = getThemeBuilderVisualGroupRoot(config, entry.element, parentElement);
    if (!groupElement || !parentElement.contains(groupElement)) return;
    if (!groupFirstOrder.has(groupElement)) {
      groupFirstOrder.set(groupElement, index + 1);
      const groupBase = getThemeBuilderElementNameBase(groupElement);
      groupRootBases.set(groupBase, (groupRootBases.get(groupBase) || 0) + 1);
    }
  });

  const seenGroupBases = new Map();
  const usedGroupIds = new Map();
  [...groupFirstOrder.keys()].forEach((groupElement) => {
    const groupBase = getThemeBuilderElementNameBase(groupElement);
    const occurrence = (seenGroupBases.get(groupBase) || 0) + 1;
    seenGroupBases.set(groupBase, occurrence);
    const rootKey = getThemeBuilderElementRootKey(config, groupElement, parentElement, usedGroupIds);
    groupMetaByElement.set(groupElement, {
      id: rootKey.id,
      label: getThemeBuilderElementFriendlyLabel(groupElement, parentElement, occurrence, (groupRootBases.get(groupBase) || 0) > 1),
      selector: rootKey.selector,
      role: isThemeBuilderActionElement(groupElement)
        ? "action"
        : isThemeBuilderMediaElement(groupElement)
          ? "media"
          : "group",
      depth: Math.max(0, rootKey.selector.split(">").length - 1),
      order: groupFirstOrder.get(groupElement) || occurrence
    });
  });

  const combinedEntries = editableTargets.map((entry, index) => {
    const groupElement = getThemeBuilderVisualGroupRoot(config, entry.element, parentElement);
    return {
      ...entry,
      order: index + 1,
      groupElement,
      groupMeta: groupMetaByElement.get(groupElement) || null,
      isGroupRoot: groupElement === entry.element,
      labelOverride: ""
    };
  });

  [...groupFirstOrder.keys()].forEach((groupElement) => {
    const hasDirectRootTarget = combinedEntries.some(entry => entry.groupElement === groupElement && entry.isGroupRoot);
    if (hasDirectRootTarget) return;
    const groupMeta = groupMetaByElement.get(groupElement);
    if (!groupMeta) return;
    combinedEntries.push({
      element: groupElement,
      role: "shell",
      sectionName: "",
      order: (groupMeta.order || 0) - 0.1,
      groupElement,
      groupMeta,
      isGroupRoot: true,
      labelOverride: `${groupMeta.label} Shell`
    });
  });

  const counts = new Map();
  combinedEntries.forEach(({ element }) => {
    const base = getThemeBuilderElementNameBase(element);
    counts.set(base, (counts.get(base) || 0) + 1);
  });

  const seen = new Map();
  const usedIds = new Map();
  const labelCounters = Object.create(null);
  return combinedEntries
    .sort((a, b) => a.order - b.order || Number(b.isGroupRoot) - Number(a.isGroupRoot))
    .map((entry, index) => {
      const { element, role, sectionName = "", groupMeta, groupElement, isGroupRoot, labelOverride = "" } = entry;
      const base = getThemeBuilderElementNameBase(element);
      const occurrence = (seen.get(base) || 0) + 1;
      seen.set(base, occurrence);
      const hasDuplicates = (counts.get(base) || 0) > 1;
      const idBase = getThemeBuilderElementIdBase(element, parentElement);
      const candidateId = hasDuplicates ? `${idBase}-${occurrence}` : idBase;
      const idUseCount = (usedIds.get(candidateId) || 0) + 1;
      usedIds.set(candidateId, idUseCount);
      const id = idUseCount > 1 ? `${candidateId}-${idUseCount}` : candidateId;
      const selector = getThemeBuilderElementSelector(config, element, parentElement);
      const depth = Math.max(0, selector.split(">").length - 1);
      const previewText = getThemeBuilderReadableElementContent(element);
      const draftTarget = {
        element,
        role,
        sectionName
      };
      const label = labelOverride || buildThemeBuilderTargetDisplayLabel(draftTarget, labelCounters);

      return {
        id,
        label,
        selector,
        depth,
        tagName: element.tagName.toLowerCase(),
        sourceName: base,
        parentId: config.id,
        parentSelector: config.selector,
        order: index + 1,
        role,
        roleLabel: role === "shell" ? "shell" : getThemeBuilderElementRoleLabel({ element, role }),
        sectionName,
        previewText,
        groupId: groupMeta?.id || "",
        groupLabel: groupMeta?.label || "",
        groupSelector: groupMeta?.selector || selector,
        groupRole: groupMeta?.role || "",
        groupDepth: groupMeta?.depth ?? depth,
        isGroupRoot,
        hasDuplicates,
        element,
        groupElement
      };
    });
}

function getThemeBuilderCachedElementTargets(config, cache = null) {
  if (!config) return [];
  if (!(cache instanceof Map)) return discoverThemeBuilderElementTargets(config);
  const cacheKey = config.id || config.selector || "";
  if (!cache.has(cacheKey)) {
    cache.set(cacheKey, discoverThemeBuilderElementTargets(config));
  }
  return cache.get(cacheKey) || [];
}

function getThemeBuilderElementDefaultsCacheKey(target) {
  if (!target) return "";
  return `${target.parentId || target.parentSelector || ""}::${target.id || target.selector || ""}`;
}

function getThemeBuilderElementDefaults(target, cache = null) {
  const cacheKey = cache instanceof Map ? getThemeBuilderElementDefaultsCacheKey(target) : "";
  if (cacheKey && cache.has(cacheKey)) {
    return cache.get(cacheKey);
  }

  const element = target?.element?.isConnected
    ? target.element
    : target?.selector
      ? document.querySelector(target.selector)
      : null;
  const parentElement = getThemeBuilderSourceParentForElement(target, element);

  const defaults = withThemeBuilderRuntimeStylesSuspended(() => {
    const style = element ? getComputedStyle(element) : null;
    const sourceBox = getThemeBuilderSourceBoxDefaults(element, parentElement);
    const borderColor = style?.borderColor && style.borderColor !== "rgba(0, 0, 0, 0)"
      ? style.borderColor
      : style?.color;

    return {
      layoutMode: "flow",
      elementBg: rgbColorToHex(style?.backgroundColor || "rgba(0, 0, 0, 0)"),
      elementText: rgbColorToHex(style?.color || "#ffffff"),
      elementBorder: rgbColorToHex(borderColor || "#ffffff"),
      fontFamily: matchThemeBuilderFontOption(style?.fontFamily || ""),
      fontSize: stripCssUnit(style?.fontSize || "16px"),
      fontWeight: normalizeThemeBuilderFontWeight(style?.fontWeight || ""),
      letterSpacing: style?.letterSpacing && style.letterSpacing !== "normal" ? stripCssUnit(style.letterSpacing) : "",
      textNoWrap: false,
      textGlow: "",
      textStroke: "",
      boxX: sourceBox.boxX || "0",
      boxY: sourceBox.boxY || "0",
      boxWidth: sourceBox.boxWidth || stripCssUnit(style?.width || ""),
      boxHeight: sourceBox.boxHeight || stripCssUnit(style?.height || ""),
      scaleX: "1",
      scaleY: "1",
      imageScale: "1",
      opacity: style?.opacity || "1",
      zIndex: "",
      auraColor: rgbColorToHex(style?.color || "#8b5cf6"),
      auraEnabled: false
    };
  });

  if (cacheKey) {
    cache.set(cacheKey, defaults);
  }

  return defaults;
}

function getThemeBuilderParentDefaults(config) {
  const themeHoverDefaults = getThemeBuilderThemeHoverDefaults();
  const parent = document.querySelector(config.selector);
  const parentStyle = parent ? getComputedStyle(parent) : null;
  const child = getFirstSelectorMatch(config.childSelector);
  const childStyle = child ? getComputedStyle(child) : null;
  const button = getFirstSelectorMatch(config.buttonSelector);
  const buttonStyle = button ? getComputedStyle(button) : null;
  const assetValue = parentStyle?.getPropertyValue("--reaver-parent-overlay-current").trim() || "";
  const childSourceBox = getThemeBuilderSourceBoxDefaults(child, child?.closest?.(config.selector) || parent);

  return {
    parentBg: rgbColorToHex(parentStyle?.backgroundColor || "#111827"),
    overlayWidth: stripCssUnit(parentStyle?.getPropertyValue("--parent-overlay-width").trim() || "420px"),
    overlayHeight: stripCssUnit(parentStyle?.getPropertyValue("--parent-overlay-height").trim() || "420px"),
    overlayScale: String(parentStyle?.getPropertyValue("--parent-overlay-scale").trim() || "1"),
    overlayX: stripCssUnit(parentStyle?.getPropertyValue("--parent-overlay-x").trim() || "0px"),
    overlayY: stripCssUnit(parentStyle?.getPropertyValue("--parent-overlay-y").trim() || "0px"),
    contentScaleX: String(parentStyle?.getPropertyValue("--parent-card-content-scale-x").trim() || "1"),
    contentScaleY: String(parentStyle?.getPropertyValue("--parent-card-content-scale-y").trim() || "1"),
    contentShiftX: stripCssUnit(parentStyle?.getPropertyValue("--parent-card-content-shift-x").trim() || "0px"),
    contentShiftY: stripCssUnit(parentStyle?.getPropertyValue("--parent-card-content-shift-y").trim() || "0px"),
    childBg: rgbColorToHex(childStyle?.backgroundColor || parentStyle?.backgroundColor || "#1f2937"),
    childText: rgbColorToHex(childStyle?.color || parentStyle?.color || "#ffffff"),
    buttonHighlight: rgbColorToHex(buttonStyle?.borderColor || buttonStyle?.backgroundColor || childStyle?.color || "#ffffff"),
    fontFamily: matchThemeBuilderFontOption(childStyle?.fontFamily || parentStyle?.fontFamily || ""),
    fontSize: stripCssUnit(childStyle?.fontSize || parentStyle?.fontSize || "16px"),
    fontWeight: normalizeThemeBuilderFontWeight(childStyle?.fontWeight || parentStyle?.fontWeight || ""),
    letterSpacing: childStyle?.letterSpacing && childStyle.letterSpacing !== "normal"
      ? stripCssUnit(childStyle.letterSpacing)
      : parentStyle?.letterSpacing && parentStyle.letterSpacing !== "normal"
        ? stripCssUnit(parentStyle.letterSpacing)
        : "",
    textNoWrap: false,
    textGlow: "",
    textStroke: "",
    childLayoutMode: "free",
    childBoxX: childSourceBox.boxX || "0",
    childBoxY: childSourceBox.boxY || "0",
    childBoxWidth: childSourceBox.boxWidth || stripCssUnit(childStyle?.width || ""),
    childBoxHeight: childSourceBox.boxHeight || stripCssUnit(childStyle?.height || ""),
    childScale: "1",
    childFontSize: stripCssUnit(childStyle?.fontSize || parentStyle?.fontSize || "16px"),
    childZIndex: "",
    imageScale: "1",
    auraEnabled: false,
    auraColor: rgbColorToHex(parentStyle?.color || "#8b5cf6"),
    auraDistance: "28",
    auraIntensity: "0.65",
    auraOpacity: "0.72",
    outerAuraEnabled: false,
    outerAuraColor: rgbColorToHex(parentStyle?.color || "#8b5cf6"),
    outerAuraBlur: "18",
    outerAuraSpread: "34",
    outerAuraOpacity: "0.62",
    outerAuraScale: "1.04",
    outerAuraZIndex: "2147483646",
    ...themeHoverDefaults,
    currentOverlayAsset: assetValue
  };
}

function getThemeBuilderOverlayAssetDisplay(themeKey, category) {
  const state = ensureThemeBuilderThemeState(themeKey);
  const saved = String(state.overlayAssets?.[category] || "").trim();
  if (saved) return saved;
  const config = THEME_BUILDER_PARENT_CONFIGS.find(entry => entry.overlayCategory === category);
  if (!config) return "";
  return getThemeBuilderParentDefaults(config).currentOverlayAsset || "";
}

function shouldHydrateThemeBuilderSourceValue(currentValue, sourceValue, forceZero = false) {
  const current = String(currentValue ?? "").trim();
  const source = String(sourceValue ?? "").trim();
  if (!source) return false;
  if (!current) return true;
  return Boolean(forceZero && current === "0" && source !== "0");
}

function hydrateThemeBuilderParentFreeFormSourceValues(parentId, parentState, options = {}) {
  const config = THEME_BUILDER_PARENT_CONFIGS.find(entry => entry.id === parentId);
  if (!config || !parentState || typeof parentState !== "object") return false;
  const isFree = normalizeThemeBuilderLayoutMode(parentState.childLayoutMode || "free") === "free";
  const hasChildOverride = ["childLayoutMode", "childBoxX", "childBoxY", "childBoxWidth", "childBoxHeight", "childScale", "childFontSize", "childZIndex"]
    .some(field => Object.prototype.hasOwnProperty.call(parentState, field));
  if (!isFree || (!hasChildOverride && !options.includeMissing)) return false;

  const defaults = getThemeBuilderParentDefaults(config);
  let changed = false;
  if (!parentState.childLayoutMode) {
    parentState.childLayoutMode = "free";
    changed = true;
  }

  [
    ["childBoxX", defaults.childBoxX, Boolean(options.forceZero)],
    ["childBoxY", defaults.childBoxY, Boolean(options.forceZero)],
    ["childBoxWidth", defaults.childBoxWidth, false],
    ["childBoxHeight", defaults.childBoxHeight, false]
  ].forEach(([field, sourceValue, forceZero]) => {
    if (shouldHydrateThemeBuilderSourceValue(parentState[field], sourceValue, forceZero)) {
      parentState[field] = sourceValue;
      changed = true;
    }
  });

  return changed;
}

function hydrateThemeBuilderElementFreeFormSourceValues(parentId, elementId, elementState, options = {}) {
  const config = THEME_BUILDER_PARENT_CONFIGS.find(entry => entry.id === parentId);
  if (!config || !elementState || typeof elementState !== "object") return false;
  const isFree = getThemeBuilderElementLayoutMode(elementState.layoutMode, "flow") === "free";
  const hasElementOverride = THEME_BUILDER_ELEMENT_FIELDS.some(field => Object.prototype.hasOwnProperty.call(elementState, field));
  if (!isFree || (!hasElementOverride && !options.includeMissing)) return false;

  const target = getThemeBuilderCachedElementTargets(config, options.elementTargetCache).find(entry => entry.id === elementId);
  if (!target) return false;
  const defaults = getThemeBuilderElementDefaults(target, options.elementDefaultsCache);
  let changed = false;
  if (!elementState.layoutMode) {
    elementState.layoutMode = "free";
    changed = true;
  }

  [
    ["boxX", defaults.boxX, Boolean(options.forceZero)],
    ["boxY", defaults.boxY, Boolean(options.forceZero)],
    ["boxWidth", defaults.boxWidth, false],
    ["boxHeight", defaults.boxHeight, false]
  ].forEach(([field, sourceValue, forceZero]) => {
    if (shouldHydrateThemeBuilderSourceValue(elementState[field], sourceValue, forceZero)) {
      elementState[field] = sourceValue;
      changed = true;
    }
  });

  return changed;
}

function escapeCssString(value = "") {
  return String(value || "").replace(/\\/g, "\\\\").replace(/"/g, "\\\"");
}

function scopeThemeBuilderSelectorList(themeKey, selectorList, suffix = "") {
  const scope = `body[data-theme="${escapeCssString(themeKey)}"]`;
  return splitThemeBuilderSelectorList(selectorList)
    .filter(Boolean)
    .map(selector => `${scope} ${selector}${suffix}`)
    .join(",\n");
}

function normalizeThemeBuilderAssetValue(value = "") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (raw.startsWith("url(")) return raw;
  return `url("${escapeCssString(raw)}")`;
}

function appendThemeBuilderPx(value = "", axis = "uniform") {
  const raw = String(value || "").trim();
  return appendThemeBuilderPxIfNeeded(raw, "px", axis);
}

function getThemeBuilderScaleCssVar(axis = "uniform") {
  if (axis === "none") return "";
  if (axis === "x") return "--app-design-scale-x";
  if (axis === "y") return "--app-design-scale-y";
  return "--app-design-scale";
}

function appendThemeBuilderPxIfNeeded(value = "", unit = "px", axis = "uniform") {
  const raw = String(value || "").trim();
  if (!raw) return "";
  if (/^(?:calc|min|max|clamp|var)\(/i.test(raw)) return raw;
  const numericOnly = /^-?\d*\.?\d+$/i.test(raw);
  const pxLength = /^-?\d*\.?\d+px$/i.test(raw);
  if (!numericOnly && !pxLength) return raw;
  const normalized = numericOnly ? `${raw}${unit}` : raw;
  if (axis === "none") return normalized;
  return `calc(${normalized} * var(${getThemeBuilderScaleCssVar(axis)}))`;
}

function buildThemeBuilderScaleTransform(scaleValue = "") {
  const raw = String(scaleValue || "").trim();
  if (!raw) return "";
  const parts = raw.split(/\s+/).filter(Boolean);
  if (!parts.length) return "";
  if (parts.length === 1) return `scale(${parts[0]})`;
  return `scale(${parts[0]}, ${parts[1]})`;
}

function buildThemeBuilderTransformValue({ translateX = "", translateY = "", scale = "" } = {}) {
  const parts = [];
  if (translateX || translateY) {
    parts.push(`translate(${translateX || "0px"}, ${translateY || "0px"})`);
  }
  const scaleTransform = buildThemeBuilderScaleTransform(scale);
  if (scaleTransform) parts.push(scaleTransform);
  return parts.join(" ");
}

function normalizeThemeBuilderLayoutMode(value = "") {
  const mode = String(value || "").trim().toLowerCase();
  return THEME_BUILDER_LAYOUT_MODES.some(option => option.value === mode) ? mode : "free";
}

function normalizeThemeBuilderHoverPreset(value = "", themeKey = getCurrentThemeBuilderThemeKey()) {
  const preset = String(value || "").trim().toLowerCase();
  if (THEME_BUILDER_HOVER_FX_PRESETS.some(option => option.value === preset)) return preset;
  return THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxPreset || "solid";
}

function normalizeThemeBuilderHoverMotion(value = "", themeKey = getCurrentThemeBuilderThemeKey()) {
  const motion = String(value || "").trim().toLowerCase();
  if (THEME_BUILDER_HOVER_FX_MOTIONS.some(option => option.value === motion)) return motion;
  return THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxMotion || "static";
}

function clampThemeBuilderNumber(value, fallback, min, max) {
  const number = Number(value);
  const safe = Number.isFinite(number) ? number : fallback;
  return Math.max(min, Math.min(max, safe));
}

function normalizeThemeBuilderZIndex(value = "") {
  const raw = String(value ?? "").trim();
  if (!raw) return "";
  const number = Number(raw);
  return Number.isFinite(number) ? String(Math.round(number)) : "";
}

function normalizeThemeBuilderFontWeight(value = "") {
  const raw = String(value ?? "").trim().toLowerCase();
  if (!raw || raw === "inherit") return "";
  if (["normal", "bold", "lighter", "bolder"].includes(raw)) return raw;
  const number = Number(raw);
  if (!Number.isFinite(number)) return "";
  return String(Math.max(100, Math.min(1000, Math.round(number / 100) * 100)));
}

function isThemeBuilderEnabledBoolean(value) {
  return value === true || String(value ?? "").trim().toLowerCase() === "true";
}

function buildThemeBuilderTextCssValues(values = {}) {
  const letterSpacing = String(values.letterSpacing ?? "").trim();
  const lineHeight = String(values.lineHeight ?? "").trim();
  const textGlow = String(values.textGlow ?? "").trim();
  const textStroke = String(values.textStroke ?? "").trim();
  const hasLetterSpacing = letterSpacing && Number(letterSpacing) !== 0;
  const hasLineHeight = lineHeight && Number(lineHeight) > 0;
  const hasGlow = textGlow && Number(textGlow) !== 0;
  const hasStroke = textStroke && Number(textStroke) !== 0;
  return {
    fontWeight: normalizeThemeBuilderFontWeight(values.fontWeight),
    letterSpacing: hasLetterSpacing ? appendThemeBuilderPxIfNeeded(letterSpacing, "px", "x") : "",
    lineHeight: hasLineHeight ? lineHeight : "",
    textNoWrap: isThemeBuilderEnabledBoolean(values.textNoWrap),
    textGlow: hasGlow ? appendThemeBuilderPxIfNeeded(textGlow) : "",
    textStroke: hasStroke ? appendThemeBuilderPxIfNeeded(textStroke) : ""
  };
}

function hasThemeBuilderTextCssValues(cssValues = {}) {
  return Boolean(
    cssValues.fontWeight ||
    cssValues.letterSpacing ||
    cssValues.lineHeight ||
    cssValues.textNoWrap ||
    cssValues.textGlow ||
    cssValues.textStroke
  );
}

function appendThemeBuilderTextDeclarations(declarations, cssValues = {}) {
  if (cssValues.fontWeight) declarations.push(`font-weight:${cssValues.fontWeight} !important;`);
  if (cssValues.letterSpacing) declarations.push(`letter-spacing:${cssValues.letterSpacing} !important;`);
  if (cssValues.lineHeight) declarations.push(`line-height:${cssValues.lineHeight} !important;`);
  if (cssValues.textNoWrap) {
    declarations.push("white-space:nowrap !important;");
    declarations.push("overflow:visible !important;");
    declarations.push("text-overflow:clip !important;");
    declarations.push("min-width:0 !important;");
  }
  if (cssValues.textGlow) {
    declarations.push(`text-shadow:0 1px 2px rgba(0,0,0,.78), 0 0 ${cssValues.textGlow} currentColor !important;`);
  }
  if (cssValues.textStroke) {
    declarations.push(`-webkit-text-stroke:${cssValues.textStroke} rgba(0,0,0,.82) !important;`);
    declarations.push("paint-order:stroke fill !important;");
  }
  if (cssValues.textGlow || cssValues.textStroke) {
    declarations.push("text-rendering:geometricPrecision !important;");
    declarations.push("-webkit-font-smoothing:antialiased !important;");
  }
}

function getThemeBuilderThemeHoverDefaults(themeKey = getCurrentThemeBuilderThemeKey()) {
  return {
    hoverFxEnabled: false,
    hoverFxPreset: THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxPreset || "solid",
    hoverFxMotion: THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxMotion || "static",
    hoverFxColor: THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxColor || "#8b5cf6",
    hoverFxAccent: THEME_BUILDER_THEME_HOVER_DEFAULTS[themeKey]?.hoverFxAccent || "#22d3ee",
    hoverFxIntensity: "0.65",
    hoverFxDistance: "28",
    hoverFxOpacity: "0.74",
    hoverFxSpeed: "1",
    hoverFxZIndex: "2147483644"
  };
}

function buildThemeBuilderHoverFxCssValues(values = {}, themeKey = getCurrentThemeBuilderThemeKey()) {
  const defaults = getThemeBuilderThemeHoverDefaults(themeKey);
  const speed = clampThemeBuilderNumber(values.hoverFxSpeed, Number(defaults.hoverFxSpeed), 0.2, 4);
  return {
    enabled: Boolean(values.hoverFxEnabled),
    preset: normalizeThemeBuilderHoverPreset(values.hoverFxPreset || defaults.hoverFxPreset, themeKey),
    motion: normalizeThemeBuilderHoverMotion(values.hoverFxMotion || defaults.hoverFxMotion, themeKey),
    color: normalizeThemeBuilderColorValue(values.hoverFxColor || defaults.hoverFxColor, defaults.hoverFxColor),
    accent: normalizeThemeBuilderColorValue(values.hoverFxAccent || defaults.hoverFxAccent, defaults.hoverFxAccent),
    intensity: String(clampThemeBuilderNumber(values.hoverFxIntensity, Number(defaults.hoverFxIntensity), 0, 2)),
    distance: appendThemeBuilderPxIfNeeded(clampThemeBuilderNumber(values.hoverFxDistance, Number(defaults.hoverFxDistance), 0, 180)),
    opacity: String(clampThemeBuilderNumber(values.hoverFxOpacity, Number(defaults.hoverFxOpacity), 0, 1)),
    zIndex: normalizeThemeBuilderZIndex(values.hoverFxZIndex || defaults.hoverFxZIndex) || defaults.hoverFxZIndex,
    speed: String(speed),
    duration: `${roundThemeBuilderSnapshotNumber(3 / speed, 2)}s`
  };
}

function buildThemeBuilderAuraCssValues(values = {}) {
  const color = normalizeThemeBuilderColorValue(values.auraColor || "#8b5cf6", "#8b5cf6");
  const distance = clampThemeBuilderNumber(values.auraDistance, 28, 0, 180);
  const intensity = clampThemeBuilderNumber(values.auraIntensity, 0.65, 0, 2);
  const opacity = clampThemeBuilderNumber(values.auraOpacity, 0.72, 0, 1);
  const strength = Math.round(Math.min(100, Math.max(0, intensity * opacity * 100)));
  return {
    enabled: Boolean(values.auraEnabled),
    color,
    distance: appendThemeBuilderPxIfNeeded(distance),
    nearDistance: appendThemeBuilderPxIfNeeded(roundThemeBuilderSnapshotNumber(distance * 0.55, 2)),
    farDistance: appendThemeBuilderPxIfNeeded(roundThemeBuilderSnapshotNumber(distance * 1.35, 2)),
    intensity: String(intensity),
    opacity: String(opacity),
    renderedColor: strength > 0 ? `color-mix(in srgb, ${color} ${strength}%, transparent)` : "transparent"
  };
}

function buildThemeBuilderOuterAuraCssValues(values = {}) {
  const color = normalizeThemeBuilderColorValue(values.outerAuraColor || "#8b5cf6", "#8b5cf6");
  const blur = clampThemeBuilderNumber(values.outerAuraBlur, 18, 0, 80);
  const spread = clampThemeBuilderNumber(values.outerAuraSpread, 34, 0, 220);
  const opacity = clampThemeBuilderNumber(values.outerAuraOpacity, 0.62, 0, 1);
  const scale = clampThemeBuilderNumber(values.outerAuraScale, 1.04, 0.6, 2.4);
  const zIndex = normalizeThemeBuilderZIndex(values.outerAuraZIndex || "-1") || "-1";
  return {
    enabled: Boolean(values.outerAuraEnabled),
    color,
    blur: appendThemeBuilderPxIfNeeded(blur),
    spread: appendThemeBuilderPxIfNeeded(spread),
    opacity: String(opacity),
    scale: String(scale),
    zIndex
  };
}

function getThemeBuilderElementLayoutMode(value = "", fallback = "flow") {
  const raw = String(value ?? "").trim();
  return raw ? normalizeThemeBuilderLayoutMode(raw) : fallback;
}

function hasThemeBuilderElementFieldDifference(field, savedValue, defaultValue) {
  if (field === "auraEnabled" || field === "textNoWrap") {
    return Boolean(savedValue) !== Boolean(defaultValue);
  }
  const saved = String(savedValue ?? "").trim();
  const fallback = String(defaultValue ?? "").trim();
  return Boolean(saved) && saved !== fallback;
}

function getThemeBuilderElementOverrideState(target, savedValues = {}, elementDefaultsCache = null) {
  if (!target || !savedValues || typeof savedValues !== "object" || !Object.keys(savedValues).length) return {};

  const defaults = getThemeBuilderElementDefaults(target, elementDefaultsCache);
  const layoutMode = getThemeBuilderElementLayoutMode(savedValues.layoutMode, defaults.layoutMode || "flow");
  const layoutFields = ["boxX", "boxY", "boxWidth", "boxHeight", "scaleX", "scaleY"];
  const styleFields = [
    "elementBg",
    "elementText",
    "elementBorder",
    "fontFamily",
    "fontSize",
    "fontWeight",
    "letterSpacing",
    "textNoWrap",
    "textGlow",
    "textStroke",
    "imageScale",
    "opacity",
    "zIndex",
    "auraColor",
    "auraEnabled"
  ];
  const geometryDiffFields = layoutFields.filter(field => hasThemeBuilderElementFieldDifference(field, savedValues[field], defaults[field]));
  const styleDiffFields = styleFields.filter(field => hasThemeBuilderElementFieldDifference(field, savedValues[field], defaults[field]));
  const overrides = {};

  if (geometryDiffFields.length) {
    overrides.layoutMode = layoutMode;
    overrides.boxX = String(savedValues.boxX ?? defaults.boxX ?? "0").trim();
    overrides.boxY = String(savedValues.boxY ?? defaults.boxY ?? "0").trim();

    ["boxWidth", "boxHeight", "scaleX", "scaleY"].forEach((field) => {
      const nextValue = String(savedValues[field] ?? "").trim();
      if (nextValue) {
        overrides[field] = nextValue;
      }
    });
  }

  styleDiffFields.forEach((field) => {
    if (field === "auraEnabled" || field === "textNoWrap") {
      overrides[field] = Boolean(savedValues[field]);
      return;
    }
    const nextValue = String(savedValues[field] ?? "").trim();
    if (nextValue) {
      overrides[field] = nextValue;
    }
  });

  return overrides;
}

function buildThemeBuilderElementCssValues(values = {}) {
  const x = String(values.boxX ?? "").trim();
  const y = String(values.boxY ?? "").trim();
  const scaleX = String(values.scaleX ?? "").trim();
  const scaleY = String(values.scaleY ?? "").trim();
  const imageScale = String(values.imageScale ?? "").trim();
  const layoutMode = getThemeBuilderElementLayoutMode(values.layoutMode, "flow");
  const flowZoom = scaleX || scaleY || "";
  const nonUniformFlowScale = layoutMode === "flow" && scaleX && scaleY && Number(scaleX) !== Number(scaleY)
    ? `1 ${Number(scaleY) / Math.max(0.01, Number(scaleX))}`
    : "";
  const textCss = buildThemeBuilderTextCssValues(values);
  const translateX = layoutMode === "visual" && (x || y) ? appendThemeBuilderPx(x || "0", "x") : "";
  const translateY = layoutMode === "visual" && (x || y) ? appendThemeBuilderPx(y || "0", "y") : "";
  const normalizedScale = layoutMode !== "flow" && (scaleX || scaleY)
    ? `${scaleX || "1"} ${scaleY || "1"}`
    : nonUniformFlowScale;
  const normalizedImageScale = imageScale && Number(imageScale) !== 1 ? imageScale : "";
  const effectiveScale = normalizedScale || (normalizedImageScale ? `${normalizedImageScale} ${normalizedImageScale}` : "");

  return {
    layoutMode,
    background: values.elementBg || "",
    color: values.elementText || "",
    borderColor: values.elementBorder || "",
    fontFamily: values.fontFamily && values.fontFamily !== "inherit" ? values.fontFamily : "",
    fontSize: values.fontSize ? appendThemeBuilderPxIfNeeded(values.fontSize, "px", "uniform") : "",
    ...textCss,
    translate: translateX || translateY ? `${translateX || "0px"} ${translateY || "0px"}` : "",
    marginLeft: layoutMode === "flow" && x ? appendThemeBuilderPx(x, "x") : "",
    marginTop: layoutMode === "flow" && y ? appendThemeBuilderPx(y, "y") : "",
    left: layoutMode === "free" && x ? appendThemeBuilderPx(x, "x") : "",
    top: layoutMode === "free" && y ? appendThemeBuilderPx(y, "y") : "",
    width: values.boxWidth ? appendThemeBuilderPxIfNeeded(values.boxWidth, "px", "x") : "",
    height: values.boxHeight ? appendThemeBuilderPxIfNeeded(values.boxHeight, "px", "y") : "",
    scale: effectiveScale,
    transform: buildThemeBuilderTransformValue({ translateX, translateY, scale: effectiveScale }),
    zoom: layoutMode === "flow" && flowZoom && Number(flowZoom) !== 1 ? flowZoom : "",
    opacity: values.opacity ? String(values.opacity).trim() : "",
    zIndex: normalizeThemeBuilderZIndex(values.zIndex),
    auraColor: values.auraColor || "",
    auraEnabled: Boolean(values.auraEnabled)
  };
}

function buildThemeBuilderElementDeclarations(cssValues = {}) {
  const declarations = [
    "box-sizing:border-box !important;",
    "overflow:visible !important;",
    "max-width:none !important;",
    "max-height:none !important;"
  ];
  const useTransformFallback = !browserFeatureSupport.individualTransform && cssValues.transform;
  if (cssValues.layoutMode === "free") {
    declarations.push("position:absolute !important;");
    declarations.push("transform-origin:left top !important;");
    if (cssValues.left) declarations.push(`left:${cssValues.left} !important;`);
    if (cssValues.top) declarations.push(`top:${cssValues.top} !important;`);
  } else {
    declarations.push("position:relative !important;");
    if (cssValues.layoutMode === "flow") {
      if (cssValues.marginLeft) declarations.push(`margin-left:${cssValues.marginLeft} !important;`);
      if (cssValues.marginTop) declarations.push(`margin-top:${cssValues.marginTop} !important;`);
      if (cssValues.zoom) declarations.push(`zoom:${cssValues.zoom} !important;`);
    }
    if (browserFeatureSupport.individualTransform && cssValues.translate) {
      declarations.push(`translate:${cssValues.translate} !important;`);
    }
  }
  if (cssValues.background) declarations.push(`background:${cssValues.background} !important;`);
  if (cssValues.color) {
    declarations.push(`color:${cssValues.color} !important;`);
    declarations.push(`fill:${cssValues.color} !important;`);
  }
  if (cssValues.borderColor) {
    declarations.push(`border-color:${cssValues.borderColor} !important;`);
    declarations.push(`stroke:${cssValues.borderColor} !important;`);
  }
  if (cssValues.fontFamily) declarations.push(`font-family:${cssValues.fontFamily} !important;`);
  if (cssValues.fontSize) declarations.push(`font-size:${cssValues.fontSize} !important;`);
  appendThemeBuilderTextDeclarations(declarations, cssValues);
  if (cssValues.width) declarations.push(`width:${cssValues.width} !important;`);
  if (cssValues.height) declarations.push(`height:${cssValues.height} !important;`);
  if (browserFeatureSupport.individualTransform) {
    if (cssValues.scale) declarations.push(`scale:${cssValues.scale} !important;`);
  } else if (useTransformFallback) {
    declarations.push(`transform:${cssValues.transform} !important;`);
  }
  if (cssValues.opacity) declarations.push(`opacity:${cssValues.opacity} !important;`);
  if (cssValues.zIndex) {
    if (cssValues.layoutMode !== "free") declarations.push("position:relative !important;");
    declarations.push(`z-index:${cssValues.zIndex} !important;`);
  }
  if (cssValues.auraEnabled && cssValues.auraColor) {
    declarations.push(`box-shadow:0 0 0 1px ${cssValues.auraColor}, 0 0 18px color-mix(in srgb, ${cssValues.auraColor} 28%, transparent) !important;`);
  }
  return declarations;
}

function buildThemeBuilderElementSnapshotCss(themeKey, target, cssValues = {}) {
  if (!target?.selector) return "";
  const hasValues = Object.entries(cssValues).some(([key, value]) => !["auraEnabled", "layoutMode"].includes(key) && Boolean(value)) || Boolean(cssValues.auraEnabled);
  if (!hasValues) return "";
  return `${scopeThemeBuilderSelectorList(themeKey, target.selector)}{${buildThemeBuilderElementDeclarations(cssValues).join("")}}`;
}

