function updateCompass(stats, model = null) {
  if (crestPreviewActive) {
    return;
  }

  const aim = safeNumber(stats?.aim);
  const sense = safeNumber(stats?.gamesense);
  const team = safeNumber(stats?.teamplay);
  const disc = safeNumber(stats?.discipline);

  applyCompassVisual({
    aim,
    gamesense: sense,
    teamplay: team,
    discipline: disc,
    strongestLens: stats?.strongestLens,
    weakestLens: stats?.weakestLens,
    profileShare: stats?.profileShare,
    source: stats?.source,
    summary: stats?.summary,
    noData: stats?.noData,
    model
  });

}

