PREMIUM_PROFILE_THEME_PRESETS.sort((left, right) => {
  const leftIndex = PREMIUM_PROFILE_THEME_STRUCTURE_ORDER.indexOf(left?.value);
  const rightIndex = PREMIUM_PROFILE_THEME_STRUCTURE_ORDER.indexOf(right?.value);
  const normalizedLeft = leftIndex === -1 ? Number.MAX_SAFE_INTEGER : leftIndex;
  const normalizedRight = rightIndex === -1 ? Number.MAX_SAFE_INTEGER : rightIndex;
  return normalizedLeft - normalizedRight;
});

// Extra animated themes must be authored as unique texture/motion systems.
// The previous generated pack reused the same few SVG/motion pairs under
// different names, so it has been removed from the picker.

// Keep the runtime class cleanup derived from the presets.  New animated
// themes are added regularly; a handwritten remove list silently left the
// newer scene classes on <body>, so changing themes could run several
// full-screen animations at once.
const PROFILE_THEME_MOTION_CLASS_NAMES = Object.freeze(Array.from(new Set([
  "static",
  "ambient-lite",
  "kinetic",
  "rings",
  "orbit",
  "shimmer",
  "tide",
  ...PROFILE_THEME_PRESETS,
  ...PREMIUM_PROFILE_THEME_PRESETS
].map((theme) => typeof theme === "string" ? theme : theme?.motion)
  .filter(Boolean)
  .map((motion) => `theme-${motion}`))));

function getAvailableProfileThemePresets(user = currentAuthUser) {
  return isPremiumThemeQaUser(user)
    ? PROFILE_THEME_PRESETS.concat(PREMIUM_PROFILE_THEME_PRESETS)
    : PROFILE_THEME_PRESETS;
}

