const VALORANT_PLAYER_CARDS_ENDPOINTS = Object.freeze([
  "/api/content/player-cards",
  "https://valorant-api.com/v1/playercards?language=en-US"
]);
const VALORANT_PLAYER_CARD_VALUE_PREFIX = "valorant-card-";
let dynamicProfileBannerStyles = [];
let profileBannerCatalogPromise = null;
let profileBannerCatalogAttempted = false;
let profileBannerCatalogLoading = false;
let activeProfileBannerCategory = "official";
const PROFILE_BANNER_BATCH_LIMITS = Object.freeze({
  mobileInitial: 48,
  mobileStep: 48,
  desktopInitial: 120,
  desktopStep: 120
});
const profileBannerVisibleCounts = new Map();

function getProfileBannerBatchLimit(kind = "initial") {
  const isMobile = isMobileLayoutViewport();
  if (kind === "step") {
    return isMobile ? PROFILE_BANNER_BATCH_LIMITS.mobileStep : PROFILE_BANNER_BATCH_LIMITS.desktopStep;
  }
  return isMobile ? PROFILE_BANNER_BATCH_LIMITS.mobileInitial : PROFILE_BANNER_BATCH_LIMITS.desktopInitial;
}

function getProfileBannerVisibleCount(category = activeProfileBannerCategory) {
  const key = String(category || "official");
  if (!profileBannerVisibleCounts.has(key)) {
    profileBannerVisibleCounts.set(key, getProfileBannerBatchLimit("initial"));
  }
  return profileBannerVisibleCounts.get(key);
}

function growProfileBannerVisibleCount(category = activeProfileBannerCategory) {
  const key = String(category || "official");
  profileBannerVisibleCounts.set(key, getProfileBannerVisibleCount(key) + getProfileBannerBatchLimit("step"));
}

function normalizeProfileBannerDisplayName(displayName = "") {
  return String(displayName || "")
    .replace(/\s+/g, " ")
    .trim()
    .replace(/\s+Card$/i, "")
    .replace(/^V(\d+):\s*/i, "V$1 · ")
    || "Valorant Player Card";
}

function getValorantPlayerCardUuid(value = "") {
  const raw = String(value || "").trim().toLowerCase();
  const urlMatch = raw.match(/playercards\/([0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})\//i);
  if (urlMatch?.[1]) return urlMatch[1];
  const candidate = raw.startsWith(VALORANT_PLAYER_CARD_VALUE_PREFIX)
    ? raw.slice(VALORANT_PLAYER_CARD_VALUE_PREFIX.length)
    : raw;
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(candidate)
    ? candidate
    : "";
}

function getValorantPlayerCardValue(uuid = "") {
  const normalizedUuid = getValorantPlayerCardUuid(uuid);
  return normalizedUuid ? `${VALORANT_PLAYER_CARD_VALUE_PREFIX}${normalizedUuid}` : "";
}

function getValorantPlayerCardWideArtUrl(uuid = "") {
  const normalizedUuid = getValorantPlayerCardUuid(uuid);
  return normalizedUuid ? `https://media.valorant-api.com/playercards/${normalizedUuid}/wideart.png` : "";
}

const PROFILE_BANNER_UPSCALED_ASSET_BASE = "assets/profile-banners/upscaled";
let profileBannerUpscaledUuidSet = null;

function getProfileBannerUpscaledUuidSet() {
  if (!profileBannerUpscaledUuidSet) {
    profileBannerUpscaledUuidSet = new Set(
      PROFILE_BANNER_STYLES
        .map(style => getValorantPlayerCardUuid(style?.image || style?.value || ""))
        .filter(Boolean)
    );
  }
  return profileBannerUpscaledUuidSet;
}

function getProfileBannerUpscaledWideArtUrl(style = {}) {
  const uuid = getValorantPlayerCardUuid(style?.uuid || style?.image || style?.value || "");
  return uuid && getProfileBannerUpscaledUuidSet().has(uuid)
    ? `${PROFILE_BANNER_UPSCALED_ASSET_BASE}/${uuid}.jpg`
    : "";
}

function profileBannerStyleFromValorantCard(card = {}) {
  const uuid = getValorantPlayerCardUuid(card.uuid);
  if (!uuid) return null;
  const image = String(card.wideArt || getValorantPlayerCardWideArtUrl(uuid) || "").trim();
  const highResImage = String(card.highResWideArt || card.upscaledWideArt || "").trim();
  if (!image) return null;
  return {
    value: getValorantPlayerCardValue(uuid),
    label: normalizeProfileBannerDisplayName(card.displayName || card.displayIcon || "Valorant Player Card"),
    image,
    highResImage,
    category: "official",
    source: "valorant-api",
    uuid
  };
}

function addUniqueProfileBannerStyle(list, style, seenValues, seenImages, options = {}) {
  if (!style?.value) return;
  const valueKey = String(style.value);
  const imageKey = String(style.image || "").trim().toLowerCase();
  if (seenValues.has(valueKey)) return;
  if (imageKey && seenImages.has(imageKey) && !options.allowDuplicateImage) return;
  seenValues.add(valueKey);
  if (imageKey) seenImages.add(imageKey);
  list.push(style);
}

function buildProfileBannerStyleList(user = currentAuthUser, extraStyles = []) {
  const list = [];
  const seenValues = new Set();
  const seenImages = new Set();
  [
    ...PROFILE_BANNER_STYLES,
    ...dynamicProfileBannerStyles,
    ...(isPremiumThemeQaUser(user) && isMobileLayoutViewport() ? PREMIUM_PROFILE_BANNER_STYLES : [])
  ].forEach(style => addUniqueProfileBannerStyle(list, style, seenValues, seenImages));
  extraStyles.forEach(style => addUniqueProfileBannerStyle(list, style, seenValues, seenImages, { allowDuplicateImage: true }));
  return list;
}

function getAvailableProfileBorderStyles(user = currentAuthUser) {
  return isPremiumThemeQaUser(user)
    ? PROFILE_BORDER_STYLES.concat(PREMIUM_PROFILE_BORDER_STYLES)
    : PROFILE_BORDER_STYLES;
}

function getAvailableProfileBannerStyles(user = currentAuthUser, extraStyles = []) {
  return buildProfileBannerStyleList(user, extraStyles);
}

const PROFILE_AVATAR_ASSET_OPTIONS = Object.freeze([]);

function getProfileAvatarAsset(value = "") {
  const key = String(value || "").trim().toLowerCase();
  return PROFILE_AVATAR_ASSET_OPTIONS.find(option => option.value === key) || null;
}

function getProfileAvatarOptions() {
  return [
    ...allAgents.map(agent => ({
      value: String(agent || "").toLowerCase(),
      label: agent,
      url: getAgentIconUrl(agent)
    })),
    ...PROFILE_AVATAR_ASSET_OPTIONS
  ];
}

function getProfileAvatarLabel(value = getDefaultProfileAvatarAgent()) {
  const key = String(value || "").trim().toLowerCase();
  const asset = getProfileAvatarAsset(key);
  if (asset) return asset.label;
  return allAgents.find(agent => String(agent).toLowerCase() === key)
    || allAgents.find(agent => String(agent).toLowerCase() === getDefaultProfileAvatarAgent())
    || "Jett";
}

function getDefaultProfileAvatarAgent() {
  return "jett";
}

function getDefaultProfileAvatarUrl(agentName = getDefaultProfileAvatarAgent()) {
  const key = String(agentName || "jett").toLowerCase();
  const asset = getProfileAvatarAsset(key);
  const agent = allAgents.find(option => String(option).toLowerCase() === key)
    || allAgents.find(option => String(option).toLowerCase() === getDefaultProfileAvatarAgent())
    || getDefaultProfileAvatarAgent();
  return asset?.url || getAgentIconUrl(agent);
}

function normalizeAccessibilityLayoutMode(value) {
  return value === "mobile" ? "mobile" : "web";
}

function normalizeThemeAccentColor(value = "") {
  const trimmed = String(value || "").trim();
  const match = trimmed.match(/^#?([0-9a-f]{3}|[0-9a-f]{6})$/i);
  if (!match) return "";
  const raw = match[1].toLowerCase();
  const expanded = raw.length === 3
    ? raw.split("").map(char => char + char).join("")
    : raw;
  return `#${expanded}`;
}

function hexToRgb(value = "") {
  const hex = normalizeThemeAccentColor(value).replace("#", "");
  if (!hex) return null;
  return {
    r: parseInt(hex.slice(0, 2), 16),
    g: parseInt(hex.slice(2, 4), 16),
    b: parseInt(hex.slice(4, 6), 16)
  };
}

function clampColorChannel(value = 0) {
  return Math.max(0, Math.min(255, Math.round(value)));
}

function rgbToHex({ r = 0, g = 0, b = 0 } = {}) {
  return `#${[r, g, b].map(channel => clampColorChannel(channel).toString(16).padStart(2, "0")).join("")}`;
}

function blendHexColors(primary = "", secondary = "", ratio = 0.5) {
  const start = hexToRgb(primary);
  const end = hexToRgb(secondary);
  if (!start) return normalizeThemeAccentColor(secondary);
  if (!end) return normalizeThemeAccentColor(primary);
  const mix = Math.max(0, Math.min(1, Number.isFinite(Number(ratio)) ? Number(ratio) : 0.5));
  return rgbToHex({
    r: (start.r * (1 - mix)) + (end.r * mix),
    g: (start.g * (1 - mix)) + (end.g * mix),
    b: (start.b * (1 - mix)) + (end.b * mix)
  });
}

function normalizeFreeThemeMotionMode(value = "static") {
  return value === "ambient" ? "ambient" : "static";
}

function normalizeProfileRecord(profile = {}) {
  const profileBase = { ...(profile && typeof profile === "object" ? profile : {}) };
  delete profileBase[["loadout", "WeaponStyle"].join("")];
  profile = profileBase;
  const avatarAgent = String(profile.avatarAgent || "").trim() || getDefaultProfileAvatarAgent();
  const loadoutOneTrick = normalizeLoadoutAgent(profile.loadoutOneTrick);
  const loadoutExclusions = loadoutOneTrick ? [] : normalizeLoadoutExclusions(profile.loadoutExclusions);
  return {
    ...profile,
    name: profile.name || "Main",
    accountName: sanitizeAccountName(profile.accountName || profile.name || "Guest", "Guest"),
    riotId: profile.riotId || "",
    puuid: profile.puuid || "",
    region: profile.region || "NA",
    startingRR: safeNumber(profile.startingRR),
    startingRRDate: String(profile.startingRRDate || ""),
    startingRRSource: String(profile.startingRRSource || ""),
    henrikHistoryWindowSize: Math.max(0, safeNumber(profile.henrikHistoryWindowSize)),
    henrikHistoryCursor: Math.max(0, safeNumber(profile.henrikHistoryCursor)),
    henrikHistoryBackfillVersion: Math.max(0, safeNumber(profile.henrikHistoryBackfillVersion)),
    henrikHistoryBackfillTargetVersion: Math.max(0, safeNumber(profile.henrikHistoryBackfillTargetVersion)),
    henrikHistoryBackfillCompleteAt: String(profile.henrikHistoryBackfillCompleteAt || ""),
    henrikHistoryReachedLimit: profile.henrikHistoryReachedLimit === true,
    storedRawRehydrateVersion: Math.max(0, safeNumber(profile.storedRawRehydrateVersion)),
    storedRawRehydrateCompleteAt: String(profile.storedRawRehydrateCompleteAt || ""),
    storedRawRehydrateMatchCount: Math.max(0, safeNumber(profile.storedRawRehydrateMatchCount)),
    storedRawIncompleteRetryCount: Math.max(0, safeNumber(profile.storedRawIncompleteRetryCount)),
    matchBackfillScanVersion: Math.max(0, safeNumber(profile.matchBackfillScanVersion)),
    matchBackfillScanCompleteAt: String(profile.matchBackfillScanCompleteAt || ""),
    matchBackfillScanMatchCount: Math.max(0, safeNumber(profile.matchBackfillScanMatchCount)),
    matchBackfillRefreshCursor: Math.max(0, Math.floor(safeNumber(profile.matchBackfillRefreshCursor))),
    lastDailyProfileSyncDate: String(profile.lastDailyProfileSyncDate || ""),
    goalRank: profile.goalRank || null,
    goalRR: Number.isFinite(Number(profile.goalRR)) ? Number(profile.goalRR) : null,
    peakRR: safeNumber(profile.peakRR),
    matches: Array.isArray(profile.matches) ? profile.matches : [],
    pendingLoadoutRoll: normalizePendingLoadoutRoll(profile.pendingLoadoutRoll) || undefined,
    lastWarmupPromptDate: String(profile.lastWarmupPromptDate || ""),
    warmupLog: normalizeWarmupLog(profile.warmupLog),
    loadoutExclusions,
    loadoutOneTrick,
    watchedPlaylistVideos: normalizeWatchedPlaylistVideos(profile.watchedPlaylistVideos),
    themeKey: profile.themeKey || "default",
    frameTheme: profile.frameTheme || profile.themeKey || "default",
    customAccent: normalizeThemeAccentColor(profile.customAccent || ""),
    freeThemeMotion: normalizeFreeThemeMotionMode(profile.freeThemeMotion),
    layoutShape: normalizeProfileLayoutShape(profile.layoutShape ?? profile.layoutStyle),
    layoutTexture: normalizeProfileLayoutTexture(profile.layoutTexture),
    layoutStyle: normalizeProfileLayoutShape(profile.layoutShape ?? profile.layoutStyle),
    layoutStyleCustomFont: profile.layoutStyleCustomFont !== false,
    layoutFont: normalizeProfileLayoutFont(profile.layoutFont),
    avatarAgent,
    avatarUrl: profile.avatarUrl || getDefaultProfileAvatarUrl(avatarAgent),
    navBackgroundUrl: profile.navBackgroundUrl || "",
    profileBorderColor: normalizeProfileBorderColor(profile.profileBorderColor || "theme"),
    profileBorder: normalizeProfileBorderStyle(profile.profileBorder || "standard"),
    profileBorderRotate: !!profile.profileBorderRotate,
    bannerStyle: normalizeProfileBannerStyle(profile.bannerStyle || "theme"),
    accessibility: {
      contrastMode: profile?.accessibility?.contrastMode || "standard",
      motionMode: profile?.accessibility?.motionMode || "standard",
      layoutMode: normalizeAccessibilityLayoutMode(profile?.accessibility?.layoutMode)
    }
  };
}

function loadProfiles(){

  try{
    const raw = localStorage.getItem(STORAGE_KEY_PROFILES);
    profiles = raw ? JSON.parse(raw) : [];
  }catch(e){
    profiles = [];
  }

  profiles = (profiles || []).map(profile => {
    const normalized = normalizeProfileRecord(profile);
    hydratePendingLoadoutRoll(normalized);
    return normalized;
  });
  let storedRawProfileMigrationChanged = false;
  profiles.forEach(profile => {
    const prep = prepareProfileStoredRawRehydrate(profile);
    if (prep?.changed) storedRawProfileMigrationChanged = true;
  });
  activeProfileId =
    localStorage.getItem(STORAGE_KEY_ACTIVE_ID);

  if (profiles.length && !profiles.some(profile => profile.id === activeProfileId)) {
    activeProfileId = profiles[0].id;
  }

  if(!profiles.length){

    const defaultProfile = {
      id: uuid(),
      name: "Main",
      accountName: "Guest",
      riotId: "",
      region: "NA",
      startingRR: 0,
      startingRRDate: "",
      startingRRSource: "",
      themeKey: "default",
      frameTheme: "default",
      customAccent: "",
      freeThemeMotion: "static",
      layoutShape: "default",
      layoutTexture: "default",
      layoutStyle: "default",
      layoutStyleCustomFont: true,
      layoutFont: "default",
      avatarAgent: getDefaultProfileAvatarAgent(),
      avatarUrl: getDefaultProfileAvatarUrl(),
      navBackgroundUrl: "",
      profileBorderColor: "theme",
      profileBorder: "standard",
      profileBorderRotate: false,
      bannerStyle: "theme",
      goalRank: null,
      goalRR: null,
      peakRR: 0,
      lastWarmupPromptDate: "",
      warmupLog: [],
      loadoutExclusions: [],
      loadoutOneTrick: "",
      watchedPlaylistVideos: [],
      accessibility: {
        contrastMode: "standard",
        motionMode: "standard",
        layoutMode: "web"
      }
    };

    profiles.push(normalizeProfileRecord(defaultProfile));
    activeProfileId = defaultProfile.id;

    saveProfiles();
  }

  logEntries = readLocalLogEntries({ profileId: activeProfileId });
  repairStatsLoggingParityForProfiles(profiles, { skipBackend: true });
  if (storedRawProfileMigrationChanged) saveProfiles();

}

