function populateEditProfileModal(profile = getActiveProfile()) {
  const themeSelect = document.getElementById("editProfileTheme");
  const layoutShapeSelect = document.getElementById("editProfileLayoutShape");
  const layoutTextureSelect = document.getElementById("editProfileLayoutTexture");
  const layoutFontSelect = document.getElementById("editProfileLayoutFont");
  const avatarSelect = document.getElementById("editProfileAvatarAgent");
  const borderColorSelect = document.getElementById("editProfileBorderColor");
  const borderSelect = document.getElementById("editProfileBorderStyle");
  const bannerSelect = document.getElementById("editProfileBannerStyle");
  const availableThemes = getAvailableProfileThemePresets();
  const availableBorderStyles = getAvailableProfileBorderStyles();

  if (themeSelect) {
    themeSelect.innerHTML = availableThemes
      .map(theme => `<option value="${theme.value}">${theme.label}</option>`)
      .join("");
  }

  if (layoutShapeSelect) {
    layoutShapeSelect.innerHTML = PROFILE_LAYOUT_SHAPES
      .map(style => `<option value="${style.value}">${style.label}</option>`)
      .join("");
  }

  if (layoutTextureSelect) {
    layoutTextureSelect.innerHTML = PROFILE_LAYOUT_TEXTURES
      .map(texture => `<option value="${texture.value}">${texture.label}</option>`)
      .join("");
  }

  if (layoutFontSelect) {
    layoutFontSelect.innerHTML = PROFILE_LAYOUT_FONTS
      .map(font => `<option value="${font.value}">${font.label}</option>`)
      .join("");
  }

  if (avatarSelect) {
    avatarSelect.innerHTML = getProfileAvatarOptions()
      .map(option => `<option value="${escapeHtml(option.value)}">${escapeHtml(option.label)}</option>`)
      .join("");
  }

  if (borderColorSelect && !borderColorSelect.options.length) {
    borderColorSelect.innerHTML = PROFILE_BORDER_COLORS
      .map(color => `<option value="${color.value}">${color.label}</option>`)
      .join("");
  }

  if (borderSelect) {
    borderSelect.innerHTML = availableBorderStyles
      .map(style => `<option value="${style.value}">${style.label}</option>`)
      .join("");
  }

  const editNameEl = document.getElementById("editProfileName");
  const editRiotIdEl = document.getElementById("editProfileRiotId");
  const editRegionEl = document.getElementById("editProfileRegion");
  if (editNameEl) editNameEl.value = profile?.name || "";
  if (editRiotIdEl) editRiotIdEl.value = profile?.riotId || "";
  if (editRegionEl) editRegionEl.value = profile?.region || "NA";
  const startingRREl = document.getElementById("editProfileStartingRR");
  const startingRRNoteEl = document.getElementById("editProfileStartingRRNote");
  if (startingRREl) {
    startingRREl.value = safeNumber(profile?.startingRR);
  }
  if (startingRRNoteEl) {
    const syncDateLabel = profile?.startingRRDate
      ? new Date(`${profile.startingRRDate}T00:00:00`).toLocaleDateString()
      : "the first Riot sync";
    startingRRNoteEl.textContent = profile?.startingRRDate
      ? `Captured automatically on ${syncDateLabel}. This value is locked.`
      : "Captured automatically on the first Riot sync of the day. This value is locked.";
  }
  const selectedThemeKey = getThemePreset(profile?.themeKey || profile?.frameTheme || "default").value;
  const selectedLayoutShape = normalizeProfileLayoutShape(profile?.layoutShape ?? profile?.layoutStyle);
  const selectedLayoutTexture = normalizeProfileLayoutTexture(profile?.layoutTexture);
  const selectedLayoutFont = normalizeProfileLayoutFont(profile?.layoutFont);
  const selectedBorderColor = normalizeProfileBorderColor(profile?.profileBorderColor || "theme");
  const selectedBorder = normalizeProfileBorderStyle(profile?.profileBorder || "standard");
  const selectedBanner = normalizeProfileBannerStyle(profile?.bannerStyle || "theme");
  refreshProfileBannerSelectOptions(selectedBanner);
  if (themeSelect) themeSelect.value = selectedThemeKey;
  if (layoutShapeSelect) layoutShapeSelect.value = selectedLayoutShape;
  if (layoutTextureSelect) layoutTextureSelect.value = selectedLayoutTexture;
  if (layoutFontSelect) layoutFontSelect.value = selectedLayoutFont;
  setProfileLayoutStyleFontToggle(profile?.layoutStyleCustomFont !== false);
  setLayoutStyleMobileSection("shapes");
  syncEditProfileCustomAccentInput(selectedThemeKey, profile?.customAccent || "");
  const freeThemeMotionEl = document.getElementById("editProfileFreeThemeMotion");
  if (freeThemeMotionEl) freeThemeMotionEl.value = normalizeFreeThemeMotionMode(profile?.freeThemeMotion);
  renderThemeGallery(selectedThemeKey);
  if (avatarSelect) {
    const selectedAvatarKey = String(profile?.avatarAgent || getDefaultProfileAvatarAgent()).toLowerCase();
    avatarSelect.value = Array.from(avatarSelect.options).some(option => option.value === selectedAvatarKey)
      ? selectedAvatarKey
      : getDefaultProfileAvatarAgent();
  }
  if (borderColorSelect) borderColorSelect.value = selectedBorderColor;
  if (borderSelect) borderSelect.value = selectedBorder;
  setProfileBorderRotateToggle(!!profile?.profileBorderRotate);
  if (bannerSelect) bannerSelect.value = selectedBanner;
  activeProfileBannerCategory = getProfileBannerCategory(getProfileBannerStyle(selectedBanner));
  syncProfileBannerCategoryChrome(activeProfileBannerCategory);
  const contrastModeEl = document.getElementById("editProfileContrastMode");
  const motionModeEl = document.getElementById("editProfileMotionMode");
  const layoutModeEl = document.getElementById("editProfileLayoutMode");
  if (contrastModeEl) contrastModeEl.value = profile?.accessibility?.contrastMode || "standard";
  if (motionModeEl) motionModeEl.value = profile?.accessibility?.motionMode || "standard";
  if (layoutModeEl) layoutModeEl.value = normalizeAccessibilityLayoutMode(profile?.accessibility?.layoutMode);
}

function openEditProfileModal() {
  populateEditProfileModal();
  activateProfileEditTab("theme");
  showModalById("editProfileModal");
}

let profileEditPanelRefreshTimer = 0;

function refreshProfileEditTabPanel(tabKey = "theme") {
  const profile = getActiveProfile();
  const themeKey = document.getElementById("editProfileTheme")?.value || profile?.themeKey || "default";
  const layoutShape = normalizeProfileLayoutShape(document.getElementById("editProfileLayoutShape")?.value || profile?.layoutShape || profile?.layoutStyle);
  const layoutTexture = normalizeProfileLayoutTexture(document.getElementById("editProfileLayoutTexture")?.value || profile?.layoutTexture);
  const avatarAgent = document.getElementById("editProfileAvatarAgent")?.value || profile?.avatarAgent || getDefaultProfileAvatarAgent();
  const borderColor = normalizeProfileBorderColor(document.getElementById("editProfileBorderColor")?.value || profile?.profileBorderColor || "theme");
  const borderStyle = normalizeProfileBorderStyle(document.getElementById("editProfileBorderStyle")?.value || profile?.profileBorder || "standard");
  const bannerStyle = normalizeProfileBannerStyle(document.getElementById("editProfileBannerStyle")?.value || profile?.bannerStyle || "theme");

  switch (tabKey) {
    case "theme":
      renderThemeGallery(themeKey);
      break;
    case "layoutStyle":
      renderLayoutStyleGalleries(layoutShape, layoutTexture);
      break;
    case "icon":
      renderAvatarGallery(avatarAgent);
      break;
    case "borderColor":
      renderBorderColorGallery(borderColor);
      break;
    case "border":
      renderBorderGallery(borderStyle);
      break;
    case "banner":
      renderBannerGallery(bannerStyle, themeKey);
      break;
    default:
      break;
  }

  scheduleThemeBuilderAutoFitText({ resetBase: true });
  window.requestAnimationFrame?.(ensureMobileSwipeAffordances);
}

function scheduleProfileEditTabPanelRefresh(tabKey = "theme") {
  if (profileEditPanelRefreshTimer) {
    window.clearTimeout(profileEditPanelRefreshTimer);
    profileEditPanelRefreshTimer = 0;
  }
  window.requestAnimationFrame(() => refreshProfileEditTabPanel(tabKey));
  profileEditPanelRefreshTimer = window.setTimeout(() => {
    profileEditPanelRefreshTimer = 0;
    refreshProfileEditTabPanel(tabKey);
  }, 140);
}

function activateProfileEditTab(tabKey = "theme") {
  const shell = document.querySelector("#editProfileModal .profile-edit-shell");
  const previousTab = shell?.dataset.activeProfileTab || "";
  const tabOrder = ["theme", "layoutStyle", "icon", "borderColor", "border", "banner"];
  const previousIndex = tabOrder.indexOf(previousTab);
  const nextIndex = tabOrder.indexOf(tabKey);
  const direction = previousIndex >= 0 && nextIndex >= 0 && nextIndex < previousIndex ? "back" : "forward";
  if (shell) {
    shell.dataset.activeProfileTab = tabKey;
    shell.dataset.tabDirection = direction;
  }
  document.querySelectorAll("#editProfileModal .profile-edit-tab").forEach((tab) => {
    tab.classList.toggle("is-active", tab.dataset.profileTab === tabKey);
  });
  document.querySelectorAll("#editProfileModal .profile-edit-panel").forEach((panel) => {
    const isActivePanel = panel.dataset.profilePanel === tabKey;
    panel.classList.toggle("is-active", isActivePanel);
    panel.classList.remove("is-tab-entering");
    if (isActivePanel) {
      void panel.offsetWidth;
      panel.classList.add("is-tab-entering");
      window.setTimeout(() => panel.classList.remove("is-tab-entering"), 280);
    }
  });
  scheduleProfileEditTabPanelRefresh(tabKey);
}

function getProfileEditSelection(selector = "", dataAttribute = "", fallback = "") {
  const active = selector ? document.querySelector(selector) : null;
  const value = active?.getAttribute?.(dataAttribute) || "";
  return value || fallback;
}

function saveEditProfileModal() {
  let profile = getActiveProfile();
  if (!profile) {
    loadProfiles();
    profile = getActiveProfile();
  }
  if (!profile) return;

  const editNameEl = document.getElementById("editProfileName");
  const editRiotIdEl = document.getElementById("editProfileRiotId");
  const editRegionEl = document.getElementById("editProfileRegion");
  const selectedTheme = getProfileEditSelection("#editProfileThemeGallery [data-theme-card].is-active", "data-theme-card", document.getElementById("editProfileTheme")?.value || profile.themeKey || "default");
  const selectedLayoutShape = getProfileEditSelection("#editProfileLayoutShapeGallery [data-layout-shape-card].is-active", "data-layout-shape-card", document.getElementById("editProfileLayoutShape")?.value || profile.layoutShape || profile.layoutStyle || "default");
  const selectedLayoutTexture = getProfileEditSelection("#editProfileLayoutTextureGallery [data-layout-texture-card].is-active", "data-layout-texture-card", document.getElementById("editProfileLayoutTexture")?.value || profile.layoutTexture || "default");
  const selectedLayoutFont = normalizeProfileLayoutFont(document.getElementById("editProfileLayoutFont")?.value || profile.layoutFont);
  const selectedAvatar = getProfileEditSelection("#editProfileAvatarGallery [data-avatar-card].is-active", "data-avatar-card", document.getElementById("editProfileAvatarAgent")?.value || profile.avatarAgent);
  const selectedBorderColor = getProfileEditSelection("#editProfileBorderColorGallery [data-border-color-card].is-active", "data-border-color-card", document.getElementById("editProfileBorderColor")?.value || profile.profileBorderColor || "theme");
  const selectedBorder = getProfileEditSelection("#editProfileBorderGallery [data-border-card].is-active", "data-border-card", document.getElementById("editProfileBorderStyle")?.value || profile.profileBorder || "standard");
  const selectedBanner = getProfileEditSelection("#editProfileBannerGallery [data-banner-card].is-active", "data-banner-card", document.getElementById("editProfileBannerStyle")?.value || profile.bannerStyle || "theme");
  const selectedCustomAccent = getEditProfileCustomAccentValue(profile);
  const selectedFreeThemeMotion = normalizeFreeThemeMotionMode(document.getElementById("editProfileFreeThemeMotion")?.value || profile.freeThemeMotion);
  const nextRiotId = editRiotIdEl ? (editRiotIdEl.value?.trim() || "") : profile.riotId;

  if (!currentAuthUser?.id && nextRiotId) {
    hideModalById("editProfileModal");
    requestSignInForRiotConnection?.({
      resumeAction: "riot-link",
      source: "edit-profile-riot-id",
      reason: "edit-profile-riot-id"
    });
    return;
  }

  updateProfile(profile.id, {
    name: editNameEl ? (editNameEl.value?.trim() || profile.name) : profile.name,
    riotId: nextRiotId,
    region: editRegionEl ? (editRegionEl.value?.trim() || "NA") : profile.region,
    themeKey: selectedTheme,
    customAccent: selectedCustomAccent,
    freeThemeMotion: selectedFreeThemeMotion,
    layoutShape: normalizeProfileLayoutShape(selectedLayoutShape),
    layoutTexture: normalizeProfileLayoutTexture(selectedLayoutTexture),
    layoutStyleCustomFont: getProfileLayoutStyleFontValue(profile),
    layoutFont: selectedLayoutFont,
    avatarAgent: selectedAvatar,
    profileBorderColor: normalizeProfileBorderColor(selectedBorderColor),
    profileBorder: normalizeProfileBorderStyle(selectedBorder),
    profileBorderRotate: getProfileBorderRotateValue(profile),
    bannerStyle: normalizeProfileBannerStyle(selectedBanner),
    navBackgroundUrl: "",
    accessibility: profile?.accessibility || { contrastMode: "standard", motionMode: "standard", layoutMode: "web" }
  });

  hideModalById("editProfileModal");
}

function previewEditProfileVisuals() {
  const profile = getActiveProfile();
  if (!profile) return;
  const activeThemeKey = document.getElementById("editProfileTheme")?.value || profile.themeKey || "default";
  const activeLayoutShape = normalizeProfileLayoutShape(document.getElementById("editProfileLayoutShape")?.value || profile.layoutShape || profile.layoutStyle);
  const activeLayoutTexture = normalizeProfileLayoutTexture(document.getElementById("editProfileLayoutTexture")?.value || profile.layoutTexture);
  const activeLayoutFont = normalizeProfileLayoutFont(document.getElementById("editProfileLayoutFont")?.value || profile.layoutFont);
  if (document.getElementById("editProfileCustomAccent")?.dataset?.usesThemeAccent === "true") {
    syncEditProfileCustomAccentInput(activeThemeKey, "");
  }
  const activeAvatar = document.getElementById("editProfileAvatarAgent")?.value || profile.avatarAgent;
  const activeBorderColor = normalizeProfileBorderColor(document.getElementById("editProfileBorderColor")?.value || profile.profileBorderColor || "theme");
  const activeBorder = normalizeProfileBorderStyle(document.getElementById("editProfileBorderStyle")?.value || profile.profileBorder || "standard");
  const activeBorderRotate = getProfileBorderRotateValue(profile);
  const activeBanner = normalizeProfileBannerStyle(document.getElementById("editProfileBannerStyle")?.value || profile.bannerStyle || "theme");
  const activeCustomAccent = getEditProfileCustomAccentValue(profile);
  const activeFreeThemeMotion = normalizeFreeThemeMotionMode(document.getElementById("editProfileFreeThemeMotion")?.value || profile.freeThemeMotion);
  const activeTab = document.querySelector("#editProfileModal .profile-edit-tab.is-active")?.dataset?.profileTab || "theme";
  switch (activeTab) {
    case "theme":
      renderThemeGallery(activeThemeKey);
      break;
    case "layoutStyle":
      renderLayoutStyleGalleries(activeLayoutShape, activeLayoutTexture);
      break;
    case "icon":
      renderAvatarGallery(activeAvatar);
      break;
    case "borderColor":
      renderBorderColorGallery(activeBorderColor);
      break;
    case "border":
      renderBorderGallery(activeBorder);
      break;
    case "banner":
      renderBannerGallery(activeBanner, activeThemeKey);
      break;
    default:
      break;
  }
  applyProfileVisuals({
    ...profile,
    themeKey: activeThemeKey,
    frameTheme: activeThemeKey,
    avatarAgent: activeAvatar,
    avatarUrl: getDefaultProfileAvatarUrl(activeAvatar || profile.avatarAgent),
    customAccent: activeCustomAccent,
    freeThemeMotion: activeFreeThemeMotion,
    layoutShape: activeLayoutShape,
    layoutTexture: activeLayoutTexture,
    layoutStyle: activeLayoutShape,
    layoutStyleCustomFont: getProfileLayoutStyleFontValue(profile),
    layoutFont: activeLayoutFont,
    profileBorderColor: activeBorderColor,
    profileBorder: activeBorder,
    profileBorderRotate: activeBorderRotate,
    bannerStyle: activeBanner,
    navBackgroundUrl: "",
    accessibility: profile?.accessibility || { contrastMode: "standard", motionMode: "standard", layoutMode: "web" }
  });
}

// ========================
// NAVIGATION
// ========================

function updateNavUnderline(){

  const activeBtn =
    document.querySelector(".nav-btn.active");

  const underline =
    document.querySelector(".nav-underline");

  const container =
    document.querySelector(".nav-links");

  if (!activeBtn || !underline || !container)
    return;

  const rect = activeBtn.getBoundingClientRect();
  const parentRect = container.getBoundingClientRect();

  underline.style.width =
    rect.width + "px";

  underline.style.left =
    (rect.left - parentRect.left) + "px";
}

let navUnderlineUpdateRaf = 0;

function scheduleNavUnderlineUpdate() {
  if (navUnderlineUpdateRaf) return;
  // Reading nav geometry immediately after a page class change forces the
  // browser to lay out the newly selected page in the click handler. Let the
  // destination paint first, then position this purely decorative underline.
  navUnderlineUpdateRaf = requestAnimationFrame(() => {
    navUnderlineUpdateRaf = requestAnimationFrame(() => {
      navUnderlineUpdateRaf = 0;
      updateNavUnderline();
    });
  });
}

let pageTransitionToken = 0;
let pageTransitionTimer = 0;
let pageMotionBudgetTimer = 0;
let mobilePageHydrationTimer = 0;
let libraryPageActivationTimer = 0;

function pausePremiumSceneForPageSwitch(duration = 220) {
  const body = document.body;
  if (!body) return;
  body.classList.add("page-motion-budget-active");
  if (pageMotionBudgetTimer) window.clearTimeout(pageMotionBudgetTimer);
  pageMotionBudgetTimer = window.setTimeout(() => {
    pageMotionBudgetTimer = 0;
    document.body?.classList.remove("page-motion-budget-active");
  }, Math.max(80, Number(duration) || 220));
}
let libraryPageActivationToken = 0;
let desktopStatsPagePrewarmScheduled = false;
let desktopStatsPagePrewarmFrame = 0;
let desktopStatsPagePrewarmed = false;
let desktopLoggingPagePrewarmScheduled = false;
let desktopLoggingPagePrewarmFrame = 0;
let desktopLoggingPagePrewarmed = false;
const LIBRARY_STABLE_HYDRATION_DELAY_MS = 1800;

function scheduleDesktopStatsPagePrewarm(options = {}) {
  const immediate = Boolean(options?.immediate);
  // The initial warm-up leaves an inline `content-visibility:visible` on the
  // page, so Stats remains laid out after that first pass.  Repeating the
  // expensive forced-layout read on every theme or Layout Style change only
  // races a normal navigation (especially the first Stats click) without
  // making a later visit any more ready.
  if (desktopStatsPagePrewarmed) return;

  // Inactive dashboards use `content-visibility:hidden` so they do not tax
  // normal navigation.  The first Stats click therefore needs its layout and
  // composited surface ready before interaction starts.  Do that while the
  // loading overlay owns the screen, rather than hoping a later rAF finishes
  // before a player makes a fast first tab change.
  const warmStatsPage = () => {
    desktopStatsPagePrewarmFrame = 0;
    desktopStatsPagePrewarmScheduled = false;
    if (desktopStatsPagePrewarmed) return;

    const statsPage = document.getElementById("page-stats");
    if (!statsPage || statsPage.classList.contains("active")) return;

    const previous = {
      visibility: statsPage.style.visibility,
      opacity: statsPage.style.opacity,
      pointerEvents: statsPage.style.pointerEvents,
      transform: statsPage.style.transform,
      willChange: statsPage.style.willChange
    };
    statsPage.style.contentVisibility = "visible";
    statsPage.style.visibility = "visible";
    // A near-transparent, composited page can be painted under the boot
    // overlay.  `opacity:0` permits layout but lets Chromium defer the first
    // raster until the click that reveals Stats.
    statsPage.style.opacity = "0.001";
    statsPage.style.pointerEvents = "none";
    statsPage.style.transform = "translate3d(0,0,0) scale(1)";
    statsPage.style.willChange = "opacity, transform";

    // Materialize both the outer page and the real Stats surfaces.  Keeping
    // these reads together after all writes avoids layout thrash, and makes
    // the first Stats activation a simple visibility transition.
    const layoutRoots = statsPage.querySelectorAll(
      ".stats-layout, .stats-summary-card, .stats-main-grid, .stats-performance-card, .stats-breakdown-card, .stats-maps-card, .stats-agents-card, .stats-weapons-card"
    );
    void statsPage.getBoundingClientRect().height;
    layoutRoots.forEach(root => { void root.getBoundingClientRect().height; });
    void statsPage.offsetHeight;
    desktopStatsPagePrewarmed = true;

    // A single rAF runs before the browser paints. Restoring in that callback
    // therefore warmed layout but still left the first real Stats visit to
    // pay its full raster cost. Keep the near-transparent surface through one
    // paint, then restore it on the following frame while the boot overlay is
    // still covering the application.
    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        if (!statsPage.isConnected) return;
        statsPage.style.visibility = previous.visibility;
        statsPage.style.opacity = previous.opacity;
        statsPage.style.pointerEvents = previous.pointerEvents;
        statsPage.style.transform = previous.transform;
        statsPage.style.willChange = previous.willChange;
        // Keep `content-visibility:visible` for the first visit so Chrome can
        // reuse the materialized layout; inactive-page visibility and pointer
        // rules continue to keep the surface out of sight and noninteractive.
      });
    });
  };

  if (immediate) {
    if (desktopStatsPagePrewarmFrame) {
      window.cancelAnimationFrame(desktopStatsPagePrewarmFrame);
      desktopStatsPagePrewarmFrame = 0;
    }
    warmStatsPage();
    return;
  }
  if (desktopStatsPagePrewarmScheduled) return;
  desktopStatsPagePrewarmScheduled = true;
  desktopStatsPagePrewarmFrame = window.requestAnimationFrame(warmStatsPage);
}

function syncLibraryPageActivity(pageId = "") {
  const library = globalThis.RankedCoachGamesenseLibrary;
  if (!library?.setPageActive) return;

  const token = ++libraryPageActivationToken;
  if (libraryPageActivationTimer) {
    window.clearTimeout(libraryPageActivationTimer);
    libraryPageActivationTimer = 0;
  }

  if (pageId !== "library") {
    library.setPageActive(false);
    return;
  }

  // The overview is already rendered locally. Its optional Playlist,
  // patch-note, approved-knowledge, and collage refreshes can fetch, decode,
  // parse, and replace large DOM sections. Keep that work out of the immediate
  // page-switch window so themes, scroll, and tab presses stay responsive; if
  // the player leaves quickly, this scheduled hydration is cancelled.
  libraryPageActivationTimer = window.setTimeout(() => {
    libraryPageActivationTimer = 0;
    if (token !== libraryPageActivationToken) return;
    if (getActivePageElement()?.id !== "page-library") return;
    library.setPageActive(true);
  }, LIBRARY_STABLE_HYDRATION_DELAY_MS);
}

function hydrateMobilePageForCurrentState(pageId = "", options = {}) {
  if (!isMobileLayoutViewport()) return;
  const allowHiddenLayoutWork = Boolean(options?.allowHiddenLayoutWork);
  const immediatePreview = Boolean(options?.immediatePreview);
  switch (pageId) {
    case "logging": {
      ensureMobileLoggingTabs();
      syncLogFocusCustomDropdown?.();
      syncLoggingQuickChipStates?.();
      updateLoggingDebriefPreview?.();
      const loggingPage = document.getElementById("page-logging");
      if ((loggingPage?.dataset.mobileLoggingView || "form") === "feed") {
        if (immediatePreview) {
          cancelScheduledLoggingFeedRender?.();
          renderLogFeed?.({ force: true });
        } else {
          scheduleLoggingFeedRender();
        }
      } else {
        markLoggingFeedDirty();
      }
      break;
    }
    case "stats":
      initStatsPage?.();
      ensureMobileStatsTabs();
      ensureMobileTrendCarousel();
      ensureMobileStatsBreakdownCarousel();
      break;
    case "insights":
      renderInsights?.();
      if (allowHiddenLayoutWork) {
        enforceInsightsActionFluidWidth();
      }
      ensureMobileInsightCardCarousel();
      ensureMobileInsightTrendCarousel();
      if (allowHiddenLayoutWork) {
        scheduleInsightListOverflowSync(document.getElementById("insightsList"));
      }
      break;
    case "home":
      if (immediatePreview) {
        recomputeFromMatches?.();
        updateDisplays?.();
        renderChart?.(currentSize);
      }
      if (allowHiddenLayoutWork) {
        scheduleLoadoutValueTextFit();
      }
      break;
    default:
      break;
  }
}

function runActivatedMobilePageHydration(pageId = "", token = pageTransitionToken) {
  if (!isMobileLayoutViewport()) return;
  if (token !== pageTransitionToken) return;
  const activePageId = getActivePageElement()?.id?.replace("page-", "") || "";
  if (activePageId !== pageId) return;
  hydrateMobilePageForCurrentState(pageId, { allowHiddenLayoutWork: true });
  scheduleMobileScrollExtentSync();
  ensureMobileSwipeAffordances();
}

function syncEditProfileCustomAccentInput(themeKey = "default", customAccent = "") {
  const input = document.getElementById("editProfileCustomAccent");
  if (!input) return;
  const fallbackTheme = getThemePreset(themeKey);
  const fallbackAccent = normalizeThemeAccentColor(fallbackTheme?.colors?.accent || "#ff4655") || "#ff4655";
  const normalizedAccent = normalizeThemeAccentColor(customAccent || "");
  input.value = normalizedAccent || fallbackAccent;
  input.dataset.usesThemeAccent = normalizedAccent ? "false" : "true";
}

function getEditProfileCustomAccentValue(profile = getActiveProfile()) {
  const input = document.getElementById("editProfileCustomAccent");
  if (!input) return normalizeThemeAccentColor(profile?.customAccent || "");
  return input.dataset.usesThemeAccent === "true"
    ? ""
    : normalizeThemeAccentColor(input.value || "");
}

function scheduleActivatedMobilePageHydration(pageId = "", token = pageTransitionToken, options = {}) {
  const immediate = Boolean(options?.immediate);
  const startDelay = Math.max(0, Number(options?.startDelay) || 0);
  const followUpDelay = Math.max(32, Number(options?.followUpDelay) || (immediate ? 72 : 120));
  if (!pageId) return;
  if (mobilePageHydrationTimer) {
    window.clearTimeout(mobilePageHydrationTimer);
    mobilePageHydrationTimer = 0;
  }
  if (startDelay) {
    mobilePageHydrationTimer = window.setTimeout(() => {
      mobilePageHydrationTimer = 0;
      window.requestAnimationFrame(() => {
        runActivatedMobilePageHydration(pageId, token);
        if (token !== pageTransitionToken) return;
        mobilePageHydrationTimer = window.setTimeout(() => {
          mobilePageHydrationTimer = 0;
          runActivatedMobilePageHydration(pageId, token);
        }, followUpDelay);
      });
    }, startDelay);
    return;
  }
  if (immediate) {
    runActivatedMobilePageHydration(pageId, token);
  } else {
    window.requestAnimationFrame(() => runActivatedMobilePageHydration(pageId, token));
  }
  mobilePageHydrationTimer = window.setTimeout(() => {
    mobilePageHydrationTimer = 0;
    runActivatedMobilePageHydration(pageId, token);
  }, followUpDelay);
}

function activatePage(pageId, options = {}){

  hideChartTooltip();
  const mobileSwipeHandoff = Boolean(options?.mobileSwipeHandoff && isMobileLayoutViewport());
  const mobileNavHandoff = Boolean(options?.mobileNavHandoff && isMobileLayoutViewport());
  const mobileFastHandoff = mobileSwipeHandoff || mobileNavHandoff;
  if (pageId === "home" && !mobileFastHandoff) {
    scheduleLoadoutValueTextFit();
    scheduleDesktopStatsPagePrewarm();
    scheduleDesktopLoggingPagePrewarm();
  }

  document
    .querySelectorAll(".nav-btn")
    .forEach(btn =>
      btn.classList.toggle(
        "active",
        btn.dataset.page === pageId
      )
    );

  const targetId = "page-" + pageId;
  const nextPage = document.getElementById(targetId);
  const currentPage = getActivePageElement();
  if (nextPage && currentPage && nextPage !== currentPage && isMobileLayoutViewport()) {
    pausePremiumSceneForPageSwitch(260);
  }
  const currentPageId = currentPage?.id?.replace("page-", "") || pageId;
  const pageOrder = Array.isArray(MOBILE_PAGE_SWIPE_ORDER)
    ? MOBILE_PAGE_SWIPE_ORDER
    : ["home", "logging", "stats", "insights", "library"];
  const currentPageIndex = Math.max(0, pageOrder.indexOf(currentPageId));
  const nextPageIndex = Math.max(0, pageOrder.indexOf(pageId));
  const pageSlideDirection = nextPageIndex >= currentPageIndex ? 1 : -1;
  if (document.body) {
    document.body.dataset.pageSlideDirection = pageSlideDirection > 0 ? "forward" : "backward";
  }
  const isMobilePageSwitch = isMobileLayoutViewport();
  const allPages = Array.from(document.querySelectorAll(".page"));
  // Reset the one mobile scroll surface while the outgoing page is still the
  // laid-out page. Doing this after flipping every page class forced the
  // browser to synchronously lay out the incoming (often much larger) page in
  // the tap handler.
  const shouldResetMobileScroll = isMobilePageSwitch && currentPage && currentPage !== nextPage;
  if (shouldResetMobileScroll) {
    scrollMobilePageToTop({ deferExtent: true });
  }
  if (!isMobilePageSwitch) {
    allPages.forEach(page => {
      page.classList.remove("is-mobile-page-ready", "is-current-page", "is-mobile-swipe-outgoing");
      if (page !== currentPage) page.classList.remove("active", "entering", "exiting");
      setMobilePageCompositorReady(page, false);
    });
    syncMobilePageWarmLayouts();
  }

  if (isMobilePageSwitch && nextPage) {
    const token = ++pageTransitionToken;
    // Only the incoming page needs its first layout now. Keeping every hidden
    // page "ready" made the full Library and the other inactive dashboards
    // participate in every mobile navigation frame.
    if (pageTransitionTimer) {
      window.clearTimeout(pageTransitionTimer);
      pageTransitionTimer = 0;
    }

    // Keep just the visible mobile page live. The former implementation kept
    // every page (including the full Library) laid out off-screen so a swipe
    // could preview it. That made each normal tab press recompose five pages.
    // Swipe preview already promotes the adjacent page on demand, so it does
    // not need this permanent warm-DOM cost.
    allPages.forEach(page => {
      const isCurrent = page === nextPage;
      page.classList.toggle("active", isCurrent);
      page.classList.toggle("is-mobile-page-ready", isCurrent);
      page.classList.toggle("is-current-page", isCurrent);
      page.classList.remove("entering", "exiting");
      setMobilePageCompositorReady(page, mobileSwipeHandoff && isCurrent);
    });
    if (mobileSwipeHandoff) syncMobilePageWarmLayouts();

    // Direct tab taps reveal the destination immediately. The explicit
    // full-page Web Animation here was expensive on phones and did not add a
    // distinct gesture affordance; drag/swipe navigation retains its own
    // side-to-side preview animation above.

    syncMobileBottomShellState({ deferExtent: mobileNavHandoff });
    if (mobileSwipeHandoff) {
      scheduleMobileScrollExtentSync();
    } else if (mobileNavHandoff) {
      scheduleActivatedMobilePageHydration(pageId, token, { startDelay: 260, followUpDelay: 96 });
    } else {
      scheduleActivatedMobilePageHydration(pageId, token, { immediate: true, followUpDelay: 72 });
    }
  } else if (nextPage && currentPage !== nextPage) {
    ++pageTransitionToken;
    if (pageTransitionTimer) {
      window.clearTimeout(pageTransitionTimer);
      pageTransitionTimer = 0;
    }

    document.querySelectorAll(".page").forEach(page => {
      page.classList.remove("entering", "exiting");
      if (page !== nextPage) page.classList.remove("active");
    });

    nextPage.classList.remove("exiting", "entering");
    nextPage.classList.add("active");
  } else if (nextPage) {
    nextPage.classList.add("active");
    nextPage.classList.remove("entering", "exiting");
  }

  if (isMobileLayoutViewport()) {
    document.body.classList.remove("mobile-nav-hidden");
    if (!mobileNavHandoff) scheduleMobileNavVisibility();
    if (!isMobilePageSwitch) {
      const activationToken = pageTransitionToken;
      window.requestAnimationFrame(() => {
        scrollMobilePageToTop();
        scheduleActivatedMobilePageHydration(pageId, activationToken);
      });
    }
  }

  if (pageId !== "logging") cancelScheduledLoggingFeedRender();

  const runPageActivationWork = () => {
    if (mobileFastHandoff) {
      const activePageId = getActivePageElement()?.id?.replace("page-", "") || "";
      if (activePageId !== pageId) return;
      if (pageId === "logging") {
        scheduleLoggingPageActivationWork();
      }
      if (pageId === "home" && pendingAgentFromLog) {
        const queuedAgent = pendingAgentFromLog;
        const queuedFocus = pendingFocusFromLog;
        pendingAgentFromLog = null;
        pendingFocusFromLog = null;
        window.setTimeout(() => {
          if (getActivePageElement()?.id !== "page-home") return;
          spinLoadoutFromLogging(queuedAgent, queuedFocus);
          recomputeFromMatches();
          updateDisplays();
          requestAnimationFrame(() => renderChart(currentSize));
        }, 96);
      }
      if (pageId === "insights") {
        requestAnimationFrame(() => enforceInsightsActionFluidWidth());
      }
      return;
    }

    if(pageId === "home" && pendingAgentFromLog){
      spinLoadoutFromLogging(
        pendingAgentFromLog,
        pendingFocusFromLog
      );
      pendingAgentFromLog = null;
      pendingFocusFromLog = null;
    }

    if (pageId === "home") {
      scheduleLoadoutValueTextFit();
      const chartSource = getChartSourceEntries(currentSize);
      updateRRChartDataStatus(chartSource);
      refreshLatestRRMatchPanel?.();
      // The chart is already rendered from the live match state. Rebuilding its
      // full SVG (and replaying the intro) on every Home tab visit was enough to
      // miss several frames on a simple page switch. Recover it when an earlier
      // render left no chart behind or when the underlying retained match count
      // changed after a sync/pull refresh.
      const hasRenderedChart = Boolean(chartRow?.querySelector("svg"));
      const chartNeedsDataRefresh = safeNumber(chartSource?.matchCount) !== safeNumber(lastMatchesLength);
      if (!hasRenderedChart || chartNeedsDataRefresh) {
        forceChartIntroAnimation = true;
        requestAnimationFrame(() => {
          if (getActivePageElement()?.id === "page-home") renderChart(currentSize);
        });
      }
    }

    if (pageId === "insights") {
      requestAnimationFrame(() => {
        enforceInsightsActionFluidWidth();
        scheduleInsightListOverflowSync(document.getElementById("insightsList"));
        replayOpenInsightTrendAnimation();
      });
    }

    if (pageId === "logging") {
      scheduleLoggingPageActivationWork();
    }

    // A page switch does not change a text node's baseline font. Reuse the
    // existing fit and only measure the newly visible page; full resets remain
    // reserved for viewport, font, and style changes.
    scheduleThemeBuilderAutoFitText();
    scheduleNavUnderlineUpdate();
  };

  runPageActivationWork();
  window.RankedCoachDailyEntrance?.activatePage(pageId, getDailyEntranceMotionContext());
  syncLibraryPageActivity(pageId);
  if (["home", "logging"].includes(pageId)) scheduleDailyWarmupCheck(700);
}

function bindPageNavigationEvents() {
  document.querySelectorAll(".nav-btn").forEach(btn => {
    if (btn.dataset.navBound === "1") return;
    btn.dataset.navBound = "1";
    btn.addEventListener("click", (event) => {
      event.preventDefault();
      const page = btn.dataset.page;
      if (!page) return;

      if (getActivePageElement()?.id !== `page-${page}`) {
        activatePage(page);
      }

      if (page === "home" && pendingAgentFromLog) {
        spinLoadoutFromLogging(
          pendingAgentFromLog,
          pendingFocusFromLog
        );

        pendingAgentFromLog = null;
        pendingFocusFromLog = null;
      }
    });
  });
}


// ========================
// SCOREBOARD + DISPLAY
// ========================

function updateDisplays(){
  const sessionEntries = getSessionMatchEntries();
  sessionRRSum = sumRRForMatchEntries(sessionEntries);

  // ========================
  // RR TOTAL ANIMATION
  // ========================

  if(totalRRDisplay){

    const animationPayload = readRRTotalAnimationPayload();
    const payloadTs = Number(animationPayload?.ts || 0);
    const lastUsedPayloadTs = Number(totalRRDisplay.dataset.lastPayloadTs || 0);
    const persistedStart = readPersistedRRTotalDisplay();
    const datasetStart = Number(totalRRDisplay.dataset.value);
    const textStart = Number(totalRRDisplay.textContent);
    const shouldUsePayload =
      !!animationPayload &&
      Number(animationPayload.to) === Number(sessionRRSum) &&
      payloadTs !== lastUsedPayloadTs;
    const start = shouldUsePayload
      ? Number(animationPayload.from)
      : Number.isFinite(datasetStart)
        ? datasetStart
        : Number.isFinite(persistedStart)
          ? persistedStart
        : Number.isFinite(textStart)
          ? textStart
          : 0;
    const target = sessionRRSum;

    if (totalRRAnimFrame) {
      cancelAnimationFrame(totalRRAnimFrame);
      totalRRAnimFrame = null;
    }
    totalRRDisplay.classList.remove("rr-total-settle");
    totalRRDisplay.classList.remove("rr-total-rolling");
    totalRRDisplay.classList.remove("rr-total-positive", "rr-total-negative", "rr-total-neutral");

    const setDisplayValue = (value) => {
      totalRRDisplay.textContent = value;
      totalRRDisplay.style.color =
        value > 0 ? "#22c55e"
        : value < 0 ? "#ef4444"
        : "#e5e7eb";
    };

    const finishRRTotalAnimation = () => {
      totalRRAnimFrame = null;
      totalRRDisplay.dataset.value = String(target);
      if (shouldUsePayload && payloadTs) {
        totalRRDisplay.dataset.lastPayloadTs = String(payloadTs);
      }
      writePersistedRRTotalDisplay(target);
      totalRRDisplay.classList.remove("rr-total-rolling");
      totalRRDisplay.classList.add(
        target > 0 ? "rr-total-positive" :
        target < 0 ? "rr-total-negative" :
        "rr-total-neutral"
      );
      totalRRDisplay.classList.remove("rr-total-settle");
      void totalRRDisplay.offsetWidth;
      totalRRDisplay.classList.add("rr-total-settle");
    };

    if (start === target) {
      setDisplayValue(target);
      finishRRTotalAnimation();
    } else {
      const direction = target > start ? 1 : -1;
      const distance = Math.abs(target - start);
      const duration = 4000;
      const stepDuration = Math.max(32, duration / Math.max(distance, 1));
      let currentValue = start;
      let lastStepAt = performance.now();

      setDisplayValue(currentValue);
      totalRRDisplay.classList.add("rr-total-rolling");

      function frame(now){
        const elapsed = now - lastStepAt;
        const stepsToAdvance = Math.max(1, Math.floor(elapsed / stepDuration));

        if (elapsed >= stepDuration) {
          lastStepAt = now;
          currentValue += direction * stepsToAdvance;
          if ((direction > 0 && currentValue >= target) || (direction < 0 && currentValue <= target)) {
            currentValue = target;
          }
          setDisplayValue(currentValue);
        }

        if (currentValue !== target) {
          totalRRAnimFrame = requestAnimationFrame(frame);
        } else {
          finishRRTotalAnimation();
        }
      }

      totalRRAnimFrame = requestAnimationFrame(frame);
    }
  }

  // ========================
  // SCOREBOARD COUNTS
  // ========================

  let wins = 0;
  let losses = 0;
  let draws = 0;

  sessionEntries.forEach(({ match: m }) => {
    if(m.result === "win") wins++;
    else if(m.result === "loss") losses++;
    else draws++;
  });

  if(winsCountEl) winsCountEl.textContent = wins;
  if(lossCountEl) lossCountEl.textContent = losses;
  if(drawCountEl) drawCountEl.textContent = draws;
  if(totalGamesEl) totalGamesEl.textContent = sessionEntries.length;

  refreshImprovementTimeline({ animate: true });
  updateNavRRToRank();
  updateNavRRToGoalRank();
  renderCoachReadinessUI();

  const model = getPlayerModel();
  refreshRRChartDataStatusFromLiveMatches?.(matches, getActiveProfile?.());
  updateCompass(model?.compass || {}, model);
  scheduleLoadoutValueTextFit();

}
// ========================
// IMPACT BAR UPDATE
// ========================

function updateImpactBar(percent){

  const fill = document.getElementById("impactBarFill");
  const label = document.getElementById("impactScoreLabel");
  if(!fill) return;
  if (label && label.parentElement !== fill) {
    fill.appendChild(label);
  }

  percent = Math.max(0, Math.min(100, percent));
  const scoreTop = percent > 0
    ? Math.max(14, Math.min(92, 100 - (percent / 2)))
    : 88;

  fill.style.setProperty("--impact-fill-inset", `${100 - percent}%`);
  fill.style.setProperty("--impact-score-top", `${scoreTop}%`);
  if (label) {
    const strong = label.querySelector("strong");
    if (strong) strong.textContent = percent > 0 ? `${Math.round(percent)}%` : "--%";
    label.classList.toggle("is-empty", percent <= 0);
    label.style.setProperty("--impact-score-top", `${scoreTop}%`);
  }
  updateImpactThresholdState(percent);
}

// ========================
// RECOMPUTE RR
// ========================

function recomputeFromMatches(){

  matches = (matches || []).map(hydrateMatchDerivedData);

  rrSum = 0;

  (matches || []).forEach(m => {

    rrSum += safeNumber(m.rr);

  });

  const sessionEntries = getSessionMatchEntries();
  sessionRRSum = sumRRForMatchEntries(sessionEntries);
  let wins = 0;
  let losses = 0;
  let draws = 0;

  sessionEntries.forEach(({ match: m }) => {
    if(m.result === "win") wins++;
    else if(m.result === "loss") losses++;
    else draws++;
  });

  if(winsCountEl) winsCountEl.textContent = wins;
  if(lossCountEl) lossCountEl.textContent = losses;
  if(drawCountEl) drawCountEl.textContent = draws;
  if(totalGamesEl) totalGamesEl.textContent = sessionEntries.length;

  if(totalRRDisplay && !Number.isFinite(Number(totalRRDisplay.dataset.value))){
    totalRRDisplay.textContent = sessionRRSum;
  }

  const p = getActiveProfile();

  if(p){

    p.matches = matches.slice();

    saveProfiles();

  }

  updateNavRRToRank();
  updateNavRRToGoalRank();
  renderCoachReadinessUI();
  refreshImprovementTimeline({ animate: true });
}

// ========================
// ADD MATCH (REAL CORE)
// ========================

function addRRChange(delta, meta = {}){

  if(chartBusy || chartAnimating) return;

  chartBusy = true;

  isUndoAnimating = false;
  undoDirection = false;

  const rr = safeNumber(delta);

  const addedMatch = {

    id: uuid(),

    rr,

    result:
      meta.result ||
      (rr > 0 ? "win" :
      rr < 0 ? "loss" : "draw"),

    agent:
      agentName?.textContent || "",

    focus:
      focusDisplay?.textContent || "",

    kills: meta.kills ?? null,
    deaths: meta.deaths ?? null,
    assists: meta.assists ?? null,
    acs: meta.acs ?? null,
    segments: Array.isArray(meta.segments) ? meta.segments : [],

    createdAt: nowISO()

  };
  matches.push(addedMatch);
  const activeProfile = getActiveProfile?.();
  if (activeProfile) markPersistentMatchRowsDirty(buildPersistentMatchArchiveRowId(currentAuthUser?.id, activeProfile, addedMatch, matches.length - 1));

  recomputeFromMatches();

  updateDisplays();

  renderChart(currentSize);
}

// ========================
// UNDO MATCH (ANIMATED)
// ========================

function undoLastMatch(){

  if(chartBusy || chartAnimating) return;
  if(!matches.length) return;

  chartBusy = true;

  isUndoAnimating = true;
  undoDirection = true;
  pendingUndoCommit = true;

  console.log("UNDO START");

  // render current chart and let reverse animation run first
  renderChart(currentSize);
}

// ========================
// RR â†’ RANK NAV
// ========================

function updateNavRRToRank(){
  const rankDisplayStatus = getRankDisplayStatus();
  const abs = computeCurrentRRAbsolute();
  const current = getTierRank(abs);
  const next = getNextTierRank(abs);
  const progress = getRankProgress();

  const currentIcon = document.getElementById("navCurrentTierIcon");
  const currentText = document.getElementById("navCurrentTierText");
  const nextIcon = document.getElementById("navNextTierIcon");
  const nextText = document.getElementById("navNextTierText");
  const bar = document.getElementById("navRRProgressBar");

  if(!current || !currentText || !nextText || !bar) return;

  if(!rankDisplayStatus.isRanked){
    currentText.textContent = rankDisplayStatus.displayLabel;
    nextText.textContent = rankDisplayStatus.nextRankText;
    if(currentIcon){
      currentIcon.hidden = true;
      currentIcon.removeAttribute("src");
      currentIcon.alt = rankDisplayStatus.displayLabel;
    }
    if(nextIcon){
      nextIcon.hidden = true;
      nextIcon.removeAttribute("src");
      nextIcon.alt = "";
    }
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, 0, "horizontal");
    return;
  }

  currentText.textContent = current.tierLabel;

  if(currentIcon){
    currentIcon.hidden = false;
    currentIcon.src = getRankIconUrl(current.tierLabel);
    currentIcon.alt = current.tierLabel;
  }

  if(next && next.tierLabel !== current.tierLabel){
    nextText.textContent = `${progress.rrToNext} RR`;
    if(nextIcon){
      nextIcon.hidden = false;
      nextIcon.src = getRankIconUrl(next.tierLabel);
      nextIcon.alt = next.tierLabel;
    }
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, Math.round(progress.pct * 100), "horizontal");
  } else {
    const radiantRR = current.tierLabel === "Radiant"
      ? getRankLocalRRForAbsoluteRR(abs, current)
      : null;
    nextText.textContent = radiantRR === null ? "Max Rank" : `Radiant ${radiantRR}`;
    if(nextIcon){
      nextIcon.hidden = false;
      nextIcon.src = getRankIconUrl(current.tierLabel);
      nextIcon.alt = current.tierLabel;
    }
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, 100, "horizontal");
  }
}

// ========================
// GOAL RANK SYSTEM
// ========================

function updateNavRRToGoalRank(){
  const profile = getActiveProfile();
  const rankDisplayStatus = getRankDisplayStatus(profile);
  const abs = computeCurrentRRAbsolute();
  const current = getTierRank(abs);
  const currentIcon = document.getElementById("navGoalCurrentIcon");
  const targetIcon = document.getElementById("navGoalTargetIcon");
  const targetRRText = document.getElementById("navGoalTargetRRText");
  const label = document.getElementById("navGoalTierText");
  const bar = document.getElementById("navRRGoalBar");

  if(!current || !label || !bar) return;

  if(targetRRText){
    targetRRText.textContent = "";
    targetRRText.hidden = true;
  }

  if(currentIcon){
    currentIcon.hidden = false;
    currentIcon.src = getRankIconUrl(current.tierLabel);
    currentIcon.alt = current.tierLabel;
  }

  if(profile && !rankDisplayStatus.isRanked){
    if(currentIcon){
      currentIcon.hidden = true;
      currentIcon.removeAttribute("src");
      currentIcon.alt = rankDisplayStatus.displayLabel;
    }
    if(targetIcon){
      targetIcon.hidden = true;
      targetIcon.removeAttribute("src");
      targetIcon.alt = "";
    }
    label.textContent = rankDisplayStatus.goalText;
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, 0, "horizontal");
    return;
  }

  if(!profile){
    label.textContent = "Set Goal";
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, 0, "horizontal");
    return;
  }

  const goalTarget = ensureProfileGoalRank(profile);
  if(!goalTarget?.bounds){
    label.textContent = "Invalid Goal";
    bar.style.width = "100%";
    applyStaticTrackGradient(bar, 0, "horizontal");
    return;
  }

  const { bounds, targetRR } = goalTarget;
  const comparableCurrentRR = abs;
  const rrNeeded = Math.max(0, targetRR - comparableCurrentRR);
  const span = Math.max(1, targetRR - current.min);
  const progressPct = rrNeeded <= 0
    ? 100
    : Math.max(0, Math.min(100, ((comparableCurrentRR - current.min) / span) * 100));

  if(targetIcon){
    targetIcon.hidden = false;
    targetIcon.src = getRankIconUrl(bounds.tierLabel);
    targetIcon.alt = bounds.tierLabel;
  }

  if(targetRRText && goalTarget.isRadiantPlus){
    targetRRText.textContent = `+ ${goalTarget.goalRR} RR`;
    targetRRText.hidden = false;
  }

  label.textContent =
    rrNeeded <= 0
      ? "Goal Reached"
      : `${rrNeeded} RR`;
  bar.style.width = "100%";
  applyStaticTrackGradient(bar, progressPct, "horizontal");
}

// ========================
// RR INPUT BUTTONS (REAL)
// ========================

function bindRRButtons(){

  addWinBtn?.addEventListener("click", () => {
    const val = safeNumber(rrInput?.value);
    addRRChange(Math.abs(val), { result: "win" });
  });

  addLossBtn?.addEventListener("click", () => {
    const val = safeNumber(rrInput?.value);
    addRRChange(-Math.abs(val), { result: "loss" });
  });

  addDrawBtn?.addEventListener("click", () => {
    addRRChange(0, { result: "draw" });
  });

  undoBtn?.addEventListener("click", () => {
    undoLastMatch();
  });

}

function renderChart(size = currentSize){

  cancelChartFrame();

  chartAnimating = false;
  const previousSize = currentSize;
  const animationMode = pendingChartAnimationMode;
  pendingChartAnimationMode = null;
  const requestedSize = normalizeChartWindowSize(size);
  const availabilityChartSource = getChartSourceEntries("5");
  const initialChartSource = getChartSourceEntries(requestedSize);
  const resolvedSize = getAvailableChartWindowSize(requestedSize, availabilityChartSource.matchCount);
  currentSize = resolvedSize;
  updateChartWindowControls(availabilityChartSource.matchCount, resolvedSize);

  const tooltipAllowedForScope = chartScopeAllowsTooltip(resolvedSize);
  const showDots = tooltipAllowedForScope;

  if(!chartRow) return;
  const renderToken = ++chartRenderToken;

  // ========================
  // RESPONSIVE WIDTH
  // ========================

const rect = chartRow.getBoundingClientRect();
const chartWidth = chartRow.clientWidth || chartRow.offsetWidth || rect.width;
const chartHeight = chartRow.clientHeight || chartRow.offsetHeight || rect.height;

if(chartWidth){
  CHART_W = chartWidth;
}

if(chartHeight){
  CHART_H = chartHeight;
}
  chartBusy = true;

  const chartSource = resolvedSize === requestedSize
    ? initialChartSource
    : getChartSourceEntries(resolvedSize);
  if (chartSource?.hasHenrikMatches || !(Array.isArray(matches) && matches.length)) {
    updateRRChartDataStatus(chartSource);
  } else {
    refreshRRChartDataStatusFromLiveMatches(matches, getActiveProfile?.());
  }
  const isLifetimeRankTimeline = String(resolvedSize).toLowerCase() === "all";
  chartRow.classList.toggle("is-lifetime-rank-chart", isLifetimeRankTimeline);
  const lifetimeRankSeries = isLifetimeRankTimeline ? buildLifetimeRankSeries(chartSource.entries) : null;
  const chartEntries = isLifetimeRankTimeline ? lifetimeRankSeries.entries : chartSource.entries;
  const chartMatchCount = chartEntries.length;
  const chartMatches = chartEntries.map(entry => entry.match);
  const cumulative = isLifetimeRankTimeline ? lifetimeRankSeries.slice.slice(1) : buildCumulativeRR(chartMatches);
  const chartWindow = isLifetimeRankTimeline
    ? { slice: lifetimeRankSeries.slice, entries: chartEntries }
    : getChartSliceWithEntries(cumulative, chartEntries, resolvedSize);
  const slice = chartWindow.slice;
  let visibleChartEntries = chartWindow.entries;
  const chartAxisMatchCount = chartMatchCount;
  const chartAxisTitle = buildChartAxisTitle(chartSource.scopeLabel || chartSource.seasonLabel || "Current Season", {
    lifetimeRankTimeline: isLifetimeRankTimeline,
    oldestRetainedDate: isLifetimeRankTimeline
      ? getOldestRetainedHenrikMatchDate(getActiveProfile?.())
      : null
  });
  const chartRenderSignature = `${chartSource.scopeLabel}|${resolvedSize}|${chartMatchCount}|${slice.join(",")}`;
  activeChartRenderSignature = chartRenderSignature;

  const isUndo = isUndoAnimating === true;
  const scopeChanged = String(resolvedSize) !== String(previousSize);
  const shouldAnimateIntro = Boolean(
    !isUndo && (
      animationMode === CHART_ANIMATION_MODE_EMPHASIS ||
      animationMode === CHART_ANIMATION_MODE_CONTINUOUS ||
      forceChartIntroAnimation ||
      scopeChanged
    )
  );
  const useContinuousIntro = animationMode === CHART_ANIMATION_MODE_CONTINUOUS;
  const shouldAnimateLatestOnly = Boolean(
    !isUndo && animationMode === CHART_ANIMATION_MODE_LATEST_ONLY
  );

  const shouldAnimate =
    isUndo ||
    shouldAnimateLatestOnly ||
    (!skipNextChartAnimation &&
     chartRenderSignature !== lastChartRenderSignature);

  if (!tooltipAllowedForScope || shouldAnimateIntro || shouldAnimate) {
    setChartTooltipSuppressed(true);
  } else {
    chartTooltipSuppressed = false;
  }
	 
  const isMobileLifetimeTimeline = isLifetimeRankTimeline && isMobileLayoutViewport();
  const isMobileChart = isMobileLayoutViewport();
  PAD_LEFT = isMobileChart
    ? Math.max(42, Math.min(48, CHART_W * 0.135))
    : CHART_W * (isLifetimeRankTimeline ? 0.12 : 0.055);
  PAD_RIGHT = isMobileLifetimeTimeline
    ? Math.max(8, CHART_W * 0.025)
    : CHART_W * 0.055;
  PAD_TOP = CHART_H * 0.08;
  PAD_BOTTOM = CHART_H * (isMobileLayoutViewport() ? 0.78 : 0.64);

// ========================
// NO MATCH PLACEHOLDER
// ========================

if(!chartEntries.length){
  updateRRMatchStats(null);
  chartRow.classList.remove("chart-intro-active");
  setChartTooltipSuppressed(true);
  forceChartIntroAnimation = false;
  lastChartRenderSignature = `empty:${resolvedSize}`;

  const min = -25;
  const max = 25;

  const y = v =>
    PAD_BOTTOM -
    ((v-min)/(max-min)) *
    (PAD_BOTTOM-PAD_TOP);

  let yTicks = "";

  for(let i=0;i<=4;i++){

    const val = min + ((max-min)/4)*i;
    const yy  = y(val);

    yTicks += `
<line
x1="${PAD_LEFT}"
y1="${yy}"
x2="${CHART_W-PAD_RIGHT}"
y2="${yy}"
stroke="rgba(148,163,184,0.25)"/>

<text
x="${PAD_LEFT-8}"
y="${yy+4}"
font-size="18"
fill="#94a3b8"
text-anchor="end">${Math.round(val)}</text>`;
  }

  let xTicks = "";
  const axisWindowSize = getChartAxisWindowSize(resolvedSize, 0);
  const normalizedSize = String(resolvedSize || "5").toLowerCase();

  for(let i=0;i<=4;i++){

    const xx =
      PAD_LEFT +
      ((CHART_W-PAD_LEFT-PAD_RIGHT)/4)*i;
    const tickValue = i === 4 && normalizedSize === "all"
      ? "Retained"
      : Math.round((axisWindowSize / 4) * i);

    xTicks += `
<text
x="${xx}"
y="${PAD_BOTTOM+28}"
font-size="18"
fill="#94a3b8"
text-anchor="middle">${tickValue}</text>`;
  }

  chartRow.innerHTML = `
<svg
width="${CHART_W}"
height="${CHART_H}"
viewBox="0 0 ${CHART_W} ${CHART_H}"
preserveAspectRatio="none">

<line
x1="${PAD_LEFT}"
y1="${y(0)}"
x2="${CHART_W-PAD_RIGHT}"
y2="${y(0)}"
stroke="rgba(148,163,184,.35)"
stroke-dasharray="6 6"/>

<line
x1="${PAD_LEFT}"
y1="${PAD_TOP}"
x2="${PAD_LEFT}"
y2="${PAD_BOTTOM}"
stroke="#94a3b8"
stroke-width="2"/>

<line
x1="${PAD_LEFT}"
y1="${PAD_BOTTOM}"
x2="${CHART_W-PAD_RIGHT}"
y2="${PAD_BOTTOM}"
stroke="#94a3b8"
stroke-width="2"/>

${yTicks}
${xTicks}
${chartAxisTitle}

</svg>`;

  chartBusy = false;
  lastMatchesLength = 0;
  return;
}

  // ========================
  // BUILD DATA
  // ========================

  const bounds = isLifetimeRankTimeline ? getLifetimeRankBounds(slice) : getChartBounds(slice);

  const y=makeChartY(
    bounds.minTick,
    bounds.maxTick
  );

  const points=buildChartPoints(slice,y,visibleChartEntries);
  const seasonBoundaries = isLifetimeRankTimeline
    ? buildLifetimeSeasonBoundaryMarkup(
        getLifetimeSeasonTransitions(chartSource.scopeEntries),
        points
      )
    : "";

  const xTicks=buildXTicks(
    points,
    slice.length,
    chartAxisMatchCount
  );

  const yTicks = isLifetimeRankTimeline
    ? buildLifetimeRankYTicks(bounds, y)
    : buildYTicks(bounds.minTick, bounds.maxTick, y);

  // ========================
  // SEGMENTS
  // ========================

  let segments="";
  let dots="";
  let rankMarkers="";
  const introTiming = getChartIntroTiming(resolvedSize, Math.max(0, points.length - 1), useContinuousIntro);
  const introSegmentDurationMs = introTiming.segmentMs;
  const introFinalPauseMs = introTiming.finalPauseMs;
  const introFinalSegmentDurationMs = introTiming.finalSegmentMs;
  const introDotPopDelayMs = 8;
  const introSettleMs = 220;

  for(let i=0;i<points.length-1;i++){

    const a=points[i];
    const b=points[i+1];

    const dx=b.x-a.x;
    const dy=b.y-a.y;

    const len=Math.sqrt(dx*dx+dy*dy);

    const color=b.rr>=0
      ? "#16a34a"
      : "#ef4444";

    const isLast=i===points.length-2;

    const animate=isLast && shouldAnimate && !shouldAnimateIntro;
    const introDelayMs = isLast
      ? (Math.max(0, points.length - 2) * introSegmentDurationMs) + introFinalPauseMs
      : i * introSegmentDurationMs;

    let cls="segment";
    let style="";

    if(shouldAnimateIntro){

      cls+=" chart-intro-segment";
      if(isLast && !useContinuousIntro){
        cls+=" chart-intro-segment-final";
      }
      style=`
--dash:${len};
stroke-dasharray:${len};
stroke-dashoffset:${len};
--intro-delay:${introDelayMs}ms;
--intro-segment-duration:${introSegmentDurationMs}ms;
--intro-final-segment-duration:${introFinalSegmentDurationMs}ms;
`;

    }else if(animate){

      cls+=" animate-segment";

      if(isUndo)
        cls+=" reverse";

      style=`
--dash:${len};
stroke-dasharray:${len};
stroke-dashoffset:${isUndo ? 0 : len};
`;

    }else{

      style=`
stroke-dasharray:${len};
stroke-dashoffset:0;
`;
    }

    segments+=`
<line class="${cls}"
x1="${a.x}" y1="${a.y}"
x2="${b.x}" y2="${b.y}"
stroke="${color}"
stroke-width="${LINE_WIDTH}"
stroke-linecap="round"
style="${style}"/>`;

  const dotRevealDelay = introDelayMs + (isLast ? introFinalSegmentDurationMs : introSegmentDurationMs) + introDotPopDelayMs;
if(showDots){
  dots += buildDotMarkup(b, {
    final: isLast,
    intro: shouldAnimateIntro,
    introDelayMs: dotRevealDelay
  });
}
  rankMarkers += buildRankChangeMarkerMarkup(b, {
    intro: shouldAnimateIntro,
    introDelayMs: dotRevealDelay + 90
  });
}
// ========================
// GRADIENT COLOR DETECT
// ========================

const hasNegative = points.some(p => p.value < 0);
const gradId = hasNegative ? "rrAreaGradRed" : "rrAreaGradGreen";

// ========================
// ZERO LINE
// ========================

const zeroY = y(0);

// ========================
// SEGMENT AREA GRADIENT
// ========================

let area = "";

for(let i = 0; i < points.length - 1; i++){

  const a = points[i];
  const b = points[i+1];

  const grad = b.value >= 0
    ? "rrAreaGradGreen"
    : "rrAreaGradRed";

  const path = `
M ${a.x} ${PAD_BOTTOM}
L ${a.x} ${a.y}
L ${b.x} ${b.y}
L ${b.x} ${PAD_BOTTOM}
Z
`;

  area += `
<path
d="${path}"
fill="url(#${grad})"
opacity=".35"
/>`;
}

 // ========================
// SVG BUILD
// ========================

chartRow.innerHTML = `
<svg
width="${CHART_W}"
height="${CHART_H}"
viewBox="0 0 ${CHART_W} ${CHART_H}"
preserveAspectRatio="none">

<defs>

<linearGradient id="rrAreaGradGreen" x1="0" y1="0" x2="0" y2="1">
<stop offset="0%" stop-color="#22c55e" stop-opacity=".35"/>
<stop offset="100%" stop-color="#22c55e" stop-opacity="0"/>
</linearGradient>

<linearGradient id="rrAreaGradRed" x1="0" y1="0" x2="0" y2="1">
<stop offset="0%" stop-color="#ef4444" stop-opacity=".35"/>
<stop offset="100%" stop-color="#ef4444" stop-opacity="0"/>
</linearGradient>

</defs>

<line x1="${PAD_LEFT}" y1="${PAD_TOP}"
x2="${PAD_LEFT}" y2="${PAD_BOTTOM}"
stroke="#94a3b8" stroke-width="2"/>

<line x1="${PAD_LEFT}" y1="${PAD_BOTTOM}"
x2="${CHART_W-PAD_RIGHT}" y2="${PAD_BOTTOM}"
stroke="#94a3b8" stroke-width="2"/>

${yTicks}
${xTicks}
${chartAxisTitle}
${area}
${seasonBoundaries}

<line id="chartCrosshair"
x1="0"
y1="0"
x2="0"
y2="${PAD_BOTTOM}"
stroke="rgba(250,204,21,.45)"
stroke-width="1.5"
opacity="0"/>

${segments}
${dots}
${rankMarkers}

</svg>`;

chartRow.classList.toggle("chart-intro-active", shouldAnimateIntro);
if (!shouldAnimateIntro) {
  chartRow.classList.remove("chart-intro-active");
}

tooltip   = document.getElementById("chartTooltip");
crosshair = chartRow.querySelector("#chartCrosshair");

// clear stale selection when chart rebuilds
selectedDot = null;

// ========================
// ANIMATION
// ========================

const seg = chartRow.querySelector(".animate-segment");

if(shouldAnimateIntro){

  setChartTooltipSuppressed(true);

  requestAnimationFrame(() => {
    if (renderToken !== chartRenderToken) return;
    chartRow.classList.add("chart-intro-active");
  });

  const finalDotRevealDelay = Math.max(
    0,
    (Math.max(0, points.length - 2) * introSegmentDurationMs) +
    introFinalPauseMs +
    introFinalSegmentDurationMs +
    introDotPopDelayMs
  );
  const introDuration = Math.max(
    820,
    finalDotRevealDelay +
    introSettleMs
  );
  window.setTimeout(() => {
    if (renderToken !== chartRenderToken) return;
    chartTooltipSuppressed = false;
    if (tooltipAllowedForScope) {
      autoSelectLatest({ popTooltip: true });
    } else {
      hideChartTooltip();
    }
  }, finalDotRevealDelay);
  window.setTimeout(() => {
    if (renderToken !== chartRenderToken) return;
    chartBusy = false;
    chartAnimating = false;
    lastChartRenderSignature = chartRenderSignature;
  }, introDuration);

  skipNextChartAnimation = false;
  lastMatchesLength = chartMatchCount;
  lastChartRenderSignature = chartRenderSignature;
  forceChartIntroAnimation = false;
  isUndoAnimating = false;
  undoDirection = false;

}else if(seg && shouldAnimate){

  setChartTooltipSuppressed(true);
  seg.style.animationPlayState = "paused";

requestAnimationFrame(() => {

  requestAnimationFrame(() => {  // âœ… second frame guarantees render

    if(!seg || !seg.isConnected){
      chartBusy = false;
      chartAnimating = false;
      chartTooltipSuppressed = !chartScopeAllowsTooltip(currentSize);
      return;
    }

    seg.style.animationPlayState = "running";

    // ðŸ›¡ï¸ SAFE LENGTH CHECK
    let len = 0;

    try{
      len = seg.getTotalLength();
    }catch(e){
      chartBusy = false;
      chartAnimating = false;
      chartTooltipSuppressed = !chartScopeAllowsTooltip(currentSize);
      return;
    }

    if(!len || !Number.isFinite(len)){
      chartBusy = false;
      chartAnimating = false;
      chartTooltipSuppressed = !chartScopeAllowsTooltip(currentSize);
      return;
    }

    followSegment(seg,isUndo);

  });

});

}else{

  chartTooltipSuppressed = !tooltipAllowedForScope;
  autoSelectLatest();
  if (!tooltipAllowedForScope) {
    hideChartTooltip();
  }
  placeStaticGoldDot();

  chartBusy = false;
  chartAnimating = false;

  skipNextChartAnimation = false;
  lastMatchesLength = chartMatchCount;
  lastChartRenderSignature = chartRenderSignature;
  forceChartIntroAnimation = false;

  isUndoAnimating = false;
  undoDirection = false;
}

// ========================
// CHART INTERACTION
// ========================

tooltip = document.getElementById("chartTooltip");
let chartPointerMoveRaf = 0;
let pendingChartPointerHit = null;

const flushChartPointerMove = () => {
  chartPointerMoveRaf = 0;
  const hit = pendingChartPointerHit;
  pendingChartPointerHit = null;
  if (chartTooltipSuppressed || !chartScopeAllowsTooltip(currentSize)) {
    hideChartTooltip();
    return;
  }
  if (!hit || selectedDot) return;

  const cx = Number(hit.getAttribute("cx"));
  const cy = Number(hit.getAttribute("cy"));

  if(crosshair){
    crosshair.style.opacity = 1;
    crosshair.setAttribute("x1", cx);
    crosshair.setAttribute("x2", cx);
    crosshair.setAttribute("y1", cy);
    crosshair.setAttribute("y2", PAD_BOTTOM);
  }

  positionTooltipToHit(hit);
  updateRRMatchStatsFromHit(hit);
};

chartRow.onpointermove = e => {
  if (chartTooltipSuppressed || !chartScopeAllowsTooltip(currentSize)) {
    hideChartTooltip();
    return;
  }
  const hit = getChartHitFromTarget(e.target);
  if(!hit) return;
  if(selectedDot) return;
  pendingChartPointerHit = hit;
  if (chartPointerMoveRaf) return;
  chartPointerMoveRaf = requestAnimationFrame(flushChartPointerMove);
};

chartRow.addEventListener("mouseleave", () => {
  if (chartPointerMoveRaf) {
    cancelAnimationFrame(chartPointerMoveRaf);
    chartPointerMoveRaf = 0;
  }
  pendingChartPointerHit = null;
  if(selectedDot) return;
  hideChartTooltip();
});

chartRow.onclick = e => {
  if (chartPointerMoveRaf) {
    cancelAnimationFrame(chartPointerMoveRaf);
    chartPointerMoveRaf = 0;
  }
  pendingChartPointerHit = null;
  if (chartTooltipSuppressed || !chartScopeAllowsTooltip(currentSize)) {
    hideChartTooltip();
    return;
  }
  const hit = getChartHitFromTarget(e.target);
  if(!hit) return;

  const dot = getChartDotFromHit(hit);
  if(!dot) return;

  if(selectedDot === dot){
    dot.classList.remove("rr-selected");
    selectedDot = null;
    autoSelectLatest();
    return;
  }

  document
    .querySelectorAll(".rr-selected")
    .forEach(d => d.classList.remove("rr-selected"));

  dot.classList.add("rr-selected");
  selectedDot = dot;

  const cx = Number(hit.getAttribute("cx"));
  const cy = Number(hit.getAttribute("cy"));

  if(crosshair){
    crosshair.style.opacity = 1;
    crosshair.setAttribute("x1", cx);
    crosshair.setAttribute("x2", cx);
    crosshair.setAttribute("y1", cy);
    crosshair.setAttribute("y2", PAD_BOTTOM);
  }

  positionTooltipToHit(hit, { pop: true });
  updateRRMatchStatsFromHit(hit);
  setSelectedTimelineContext(Number(hit?.dataset?.matchIndex), { animate: true });
};
}

function scheduleSelectedChartTooltipPosition() {
  if (selectedChartTooltipRaf) return;
  selectedChartTooltipRaf = window.requestAnimationFrame(() => {
    selectedChartTooltipRaf = 0;
    if(!selectedDot) return;
    if (!canRenderChartTooltip()) {
      hideChartTooltip();
      return;
    }
    const hit = getChartHitFromDot(selectedDot);
    if(!hit) return;
    positionTooltipToHit(hit);
    if (!isMobileLayoutViewport()) return;

    const tip = ensureChartTooltipLayer();
    const tipRect = tip?.getBoundingClientRect?.();
    const headerRect = document.querySelector(".app-header")?.getBoundingClientRect?.();
    const bottomShellRect = document.getElementById("mobileBottomShell")?.getBoundingClientRect?.();
    const viewportTop = window.visualViewport?.offsetTop || 0;
    const viewportBottom = viewportTop + (window.visualViewport?.height || window.innerHeight || 0);
    const overlapsHeader = Boolean(tipRect && headerRect
      && tipRect.bottom > headerRect.top
      && tipRect.top < headerRect.bottom);
    const overlapsBottomShell = Boolean(tipRect && bottomShellRect
      && tipRect.bottom > bottomShellRect.top
      && tipRect.top < bottomShellRect.bottom);
    const outsideViewport = Boolean(tipRect
      && (tipRect.bottom <= viewportTop || tipRect.top >= viewportBottom));
    if (overlapsHeader || overlapsBottomShell || outsideViewport) hideChartTooltip();
  });
}

window.addEventListener("scroll", scheduleSelectedChartTooltipPosition, { passive: true });
document.addEventListener("scroll", scheduleSelectedChartTooltipPosition, { capture: true, passive: true });
window.visualViewport?.addEventListener("scroll", scheduleSelectedChartTooltipPosition, { passive: true });
window.addEventListener("resize", scheduleSelectedChartTooltipPosition, { passive: true });

// ==============================
// GOLD DOT HELPERS
// ==============================

function placeStaticGoldDot(){

  const svg = chartRow?.querySelector("svg");
  if(!svg) return;

  // real gold endpoint already exists in chart markup
  if(svg.querySelector(".final-end")) return;

  const segments = svg.querySelectorAll(".segment");
  if(!segments || !segments.length) return;

  svg.querySelectorAll(".gold-follower").forEach(el=>el.remove());

  const lastSeg = segments[segments.length-1];

  const dot =
    document.createElementNS(
      "http://www.w3.org/2000/svg",
      "circle"
    );

  dot.setAttribute("cx", lastSeg.getAttribute("x2"));
  dot.setAttribute("cy", lastSeg.getAttribute("y2"));
  dot.setAttribute("r", 6);
  dot.setAttribute("fill", "#facc15");

  dot.classList.add("gold-follower");

  svg.appendChild(dot);
}

function autoSelectLatest(options = {}){
  const { popTooltip = false, updateStats = false } = options;
  const tooltipAllowed = chartScopeAllowsTooltip(currentSize);

  const gold = chartRow.querySelector(".final-end");
  const hit  = getChartHitFromDot(gold);

  if(!gold || !hit) {
    setSelectedTimelineContext(null, { animate: false });
    const fallback = refreshLatestRRMatchPanel?.();
    if (!fallback) updateRRMatchStats(null);
    return;
  }

  document
    .querySelectorAll(".rr-selected")
    .forEach(d => d.classList.remove("rr-selected"));

  gold.classList.add("rr-selected");
  selectedDot = gold;

  const cx = Number(hit.getAttribute("cx"));
  const cy = Number(hit.getAttribute("cy"));

  if(crosshair){
    crosshair.style.opacity = 1;
    crosshair.setAttribute("x1", cx);
    crosshair.setAttribute("x2", cx);
    crosshair.setAttribute("y1", cy);
    crosshair.setAttribute("y2", PAD_BOTTOM);
  }

  if (tooltipAllowed) {
    positionTooltipToHit(hit, { pop: popTooltip });
  } else {
    hideChartTooltip();
  }
  updateRRMatchStatsFromHit(hit);
  setSelectedTimelineContext(Number(hit?.dataset?.matchIndex), { animate: Boolean(updateStats) });
}

// ==============================
// GOLD DOT FOLLOWER
// ==============================

function followSegment(seg, reverse = false){

  const svg = seg.closest("svg");
  if(!svg) return;

  if(chartAnimating) return;
  chartAnimating = true;
  setChartTooltipSuppressed(true);

  svg.querySelectorAll(".gold-follower").forEach(el => el.remove());

  const len = seg.getTotalLength();
  if(!len || !Number.isFinite(len)){
    chartAnimating = false;
    chartBusy = false;
    chartTooltipSuppressed = !chartScopeAllowsTooltip(currentSize);
    return;
  }

const dot = document.createElementNS(
  "http://www.w3.org/2000/svg",
  "circle"
);

dot.setAttribute("r", 6);
dot.setAttribute("fill", "#facc15");
dot.classList.add("gold-follower");

// set initial position BEFORE appending
const initialPoint = reverse
  ? seg.getPointAtLength(len)
  : seg.getPointAtLength(0);

dot.setAttribute("cx", initialPoint.x);
dot.setAttribute("cy", initialPoint.y);

svg.appendChild(dot);

  const targetX = Number(seg.getAttribute("x2"));
  const targetY = Number(seg.getAttribute("y2"));
  const targetDot = Array.from(svg.querySelectorAll(".rr-dot, .final-end")).find((candidate) => {
    const cx = Number(candidate.getAttribute("cx"));
    const cy = Number(candidate.getAttribute("cy"));
    return Math.abs(cx - targetX) < 0.5 && Math.abs(cy - targetY) < 0.5;
  });

  if (targetDot instanceof SVGElement) {
    targetDot.style.opacity = "0";
    targetDot.dataset.chartHiddenDuringFollow = "1";
  }

  seg.style.animationPlayState = "running";

  let finished = false;

  function finishAnimation(){

    if(finished) return;
    finished = true;

    if(chartAnimFrame){
      cancelAnimationFrame(chartAnimFrame);
      chartAnimFrame = null;
    }

    const finalLen = reverse ? 0 : len;
    const finalPoint = seg.getPointAtLength(finalLen);

    dot.setAttribute("cx", finalPoint.x);
    dot.setAttribute("cy", finalPoint.y);
    dot.remove();

    if (targetDot instanceof SVGElement) {
      targetDot.style.removeProperty("opacity");
      delete targetDot.dataset.chartHiddenDuringFollow;
    }

    chartAnimating = false;

    // reverse undo commit happens ONLY after reverse animation finishes
    if(reverse && pendingUndoCommit){

      console.log("UNDO APPLY MATCH POP");

      pendingUndoCommit = false;

      matches.pop();

      recomputeFromMatches();
      updateDisplays();

      skipNextChartAnimation = true;
      isUndoAnimating = false;
      undoDirection = false;

      renderChart(currentSize);
      lastMatchesLength = getSessionMatchEntries().length;
      lastChartRenderSignature = activeChartRenderSignature;

      return;
    }

    chartBusy = false;
    lastMatchesLength = getSessionMatchEntries().length;
    lastChartRenderSignature = activeChartRenderSignature;
    skipNextChartAnimation = false;
    isUndoAnimating = false;
    undoDirection = false;

    chartTooltipSuppressed = false;
    if (!reverse && targetDot?.classList?.contains("final-end")) {
      if (chartScopeAllowsTooltip(currentSize)) {
        autoSelectLatest({ popTooltip: true });
      } else {
        hideChartTooltip();
      }
    }
  }

  function frame(){

    const dashOffset =
      parseFloat(getComputedStyle(seg).strokeDashoffset);

    if(!Number.isFinite(dashOffset)){
      finishAnimation();
      return;
    }

    // visible tip of the line is always len - dashOffset
    const pointLen = Math.max(0, Math.min(len, len - dashOffset));
    const point = seg.getPointAtLength(pointLen);

    dot.setAttribute("cx", point.x);
    dot.setAttribute("cy", point.y);

    // stop only when CSS animation has reached its real end
    const done = reverse
      ? dashOffset >= len - 0.5
      : dashOffset <= 0.5;

    if(done){
      finishAnimation();
      return;
    }

    chartAnimFrame = requestAnimationFrame(frame);
  }

  chartAnimFrame = requestAnimationFrame(frame);
}

