async function restoreCachedSignedInLocalState(user, options = {}) {
  if (!user?.id) return false;
  cacheLastKnownAuthUser(user);
  currentAuthUser = user;
  setAppEntryChoice("auth");
  closeAuthModal?.();
  updateAuthUI?.(user);

  logEntries = readLocalLogEntries({
    user,
    signedIn: true,
    profileId: activeProfileId
  });

  refreshActiveProfileDataSurfaces?.({ renderChart: true, refreshInsights: true });
  rebuildProfileListUI?.();
  updateProfileHeaderUI?.();
  renderLogFeed?.({ force: true });
  renderCoachReadinessUI?.();
  refreshRiotProfilePrompt?.();
  markAccountStateLoadComplete?.();
  startPersistentAccountAutoRefresh?.();
  notifyAuthReachabilityIssue(
    options.message || "Having trouble reaching your account right now — continuing with your local data.",
    { title: "Using saved account", reason: options.reason || "cached-auth-fallback", force: true }
  );
  hideLoginInitializationOverlay?.();
  return true;
}

function scheduleDesktopLoggingPagePrewarm(options = {}) {
  const immediate = Boolean(options?.immediate);
  if (desktopLoggingPagePrewarmed || isMobileLayoutViewport?.()) return;

  const warmLoggingPage = () => {
    desktopLoggingPagePrewarmFrame = 0;
    desktopLoggingPagePrewarmScheduled = false;
    if (desktopLoggingPagePrewarmed || isMobileLayoutViewport?.()) return;

    const loggingPage = document.getElementById("page-logging");
    if (!loggingPage || loggingPage.classList.contains("active")) return;

    const previous = {
      visibility: loggingPage.style.visibility,
      opacity: loggingPage.style.opacity,
      pointerEvents: loggingPage.style.pointerEvents,
      transform: loggingPage.style.transform,
      willChange: loggingPage.style.willChange
    };
    loggingPage.style.contentVisibility = "visible";
    loggingPage.style.visibility = "visible";
    loggingPage.style.opacity = "0.001";
    loggingPage.style.pointerEvents = "none";
    loggingPage.style.transform = "translate3d(0,0,0) scale(1)";
    loggingPage.style.willChange = "opacity, transform";

    const layoutRoots = loggingPage.querySelectorAll(
      ".logging-layout, .logging-card, .logging-form, .logging-hero, .logging-row, .notes-row, .logging-actions, .logging-feed-card"
    );
    void loggingPage.getBoundingClientRect().height;
    layoutRoots.forEach(root => { void root.getBoundingClientRect().height; });
    void loggingPage.offsetHeight;
    desktopLoggingPagePrewarmed = true;

    window.requestAnimationFrame(() => {
      window.requestAnimationFrame(() => {
        if (!loggingPage.isConnected) return;
        loggingPage.style.visibility = previous.visibility;
        loggingPage.style.opacity = previous.opacity;
        loggingPage.style.pointerEvents = previous.pointerEvents;
        loggingPage.style.transform = previous.transform;
        loggingPage.style.willChange = previous.willChange;
      });
    });
  };

  if (immediate) {
    if (desktopLoggingPagePrewarmFrame) {
      window.cancelAnimationFrame(desktopLoggingPagePrewarmFrame);
      desktopLoggingPagePrewarmFrame = 0;
    }
    warmLoggingPage();
    return;
  }
  if (desktopLoggingPagePrewarmScheduled) return;
  desktopLoggingPagePrewarmScheduled = true;
  desktopLoggingPagePrewarmFrame = window.requestAnimationFrame(warmLoggingPage);
}



async function initUserSession(initialSessionUser = null){
  if(!supabaseClient?.auth){
    updateAuthUI(null);
    hideLoginInitializationOverlay();
    return;
  }

  let cachedSessionUser = initialSessionUser || null;
  let startupAuthTimedOut = false;
  if (cachedSessionUser) {
    showLoginInitializationOverlay(
      "Restoring your saved session.",
      "Keeping the dashboard covered while your saved account and coaching pages are rebuilt."
    );
  } else {
    try {
      const session = await getSupabaseSession({
        label: "Startup cached auth session",
        reason: "startup-session",
        timeoutMs: AUTH_INIT_TIMEOUT_MS,
        playerMessage: "Having trouble reaching your account right now — continuing with your local data."
      });
      cachedSessionUser = session?.user || null;
    } catch (error) {
      if (isAuthTimeoutError(error)) startupAuthTimedOut = true;
      console.warn("Unable to read cached auth session", error);
    }
  }

  let user = null;
  try {
    user = await getSupabaseUser({
      label: "Startup auth verification",
      reason: "startup-user",
      timeoutMs: AUTH_INIT_TIMEOUT_MS,
      playerMessage: "Having trouble reaching your account right now — continuing with your local data."
    });
  } catch (error) {
    if (isAuthTimeoutError(error)) startupAuthTimedOut = true;
    console.warn("Unable to verify auth session", error);
  }
  const resolvedUser = user || cachedSessionUser || null;
  if (resolvedUser) {
    captureGuestRiotMigrationSnapshot?.("session-restore");
    setAppEntryChoice("auth");
    await initializeSignedInAccount(resolvedUser, { reason: "session-restore" });
    return;
  }

  if (startupAuthTimedOut) {
    const cachedAuth = readCachedAuthUserFromLocalStorage();
    if (cachedAuth?.user) {
      console.warn("Auth verification timed out; restoring cached signed-in local state", {
        source: cachedAuth.source,
        userId: cachedAuth.user.id
      });
      await restoreCachedSignedInLocalState(cachedAuth.user, {
        reason: "startup-auth-timeout",
        message: "Having trouble reaching your account right now — continuing with your saved local data."
      });
      return;
    }
  }

  await handleSignedInUser(null);
  hideLoginInitializationOverlay();
  window.setTimeout(() => {
    maybePromptGuestLinkedRiotProfileMigration?.();
  }, 360);

}

function hydrateMatchDerivedData(match = {}) {
  const compactRecord = match?.matchRecord?.schemaVersion
    ? globalThis.RankedCoachMatchRecord?.emptyRecord?.(match.matchRecord) || match.matchRecord
    : match?.matchRecord;
  const hydratedMatch = compactRecord && compactRecord !== match.matchRecord
    ? { ...match, matchRecord: compactRecord }
    : match;
  const projected = globalThis.RankedCoachRoundMetrics?.deriveAdvancedContextFromRoundByRound?.(hydratedMatch) || {};
  if (!Array.isArray(projected.rounds) || !projected.rounds.length) return hydratedMatch;
  const roundMetrics = globalThis.RankedCoachRoundMetrics?.computeMatchRoundMetrics?.(hydratedMatch) || null;
  return {
    ...hydratedMatch,
    roundMetrics,
    advanced: {
      ...(hydratedMatch?.advanced || {}),
      ...projected,
      manual: hydratedMatch?.advanced?.manual === true || hydratedMatch?.manual === true,
      roundsWon: hydratedMatch?.advanced?.roundsWon ?? compactRecord?.rounds?.won,
      roundsLost: hydratedMatch?.advanced?.roundsLost ?? compactRecord?.rounds?.lost
    }
  };
}


