if (!window.__vt_riotProfileSaveBound) {
  window.__vt_riotProfileSaveBound = true;

  document.addEventListener("click", async (e) => {

    if(e.target.id !== "saveRiotProfileBtn") return;

    const saveBtn = document.getElementById("saveRiotProfileBtn");
    const originalText = saveBtn?.textContent || "Save";

    const riotId = document.getElementById("riotIdInput")?.value?.trim();
    const region = document.getElementById("riotRegionInput")?.value?.trim();

    if(!riotId){
      alert("Enter Riot ID");
      return;
    }

    if (!requestSignInForRiotConnection?.({
      resumeAction: "riot-link",
      source: "riot-modal-save",
      reason: "riot-profile-save"
    })) {
      return;
    }

    try {
      if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.textContent = "Saving...";
      }

      const p = getActiveProfile();
      if(p){
        if (String(p.riotId || "").trim().toLowerCase() !== riotId.toLowerCase()) {
          p.puuid = "";
        }
        p.riotId = riotId;
        p.region = region || "NA";
        p.startingRRDate = "";
        p.startingRRSource = "";
        saveProfiles();
        updateProfileHeaderUI();
        scheduleRiotAutoSync();
      }

      if (supabaseClient?.auth) {
        const user = await getSupabaseUser({
          label: "Riot profile account verification",
          reason: "riot-profile-save",
          timeoutMs: AUTH_ACTION_TIMEOUT_MS,
          playerMessage: "Riot profile saved locally, but account sync is slow right now. RankedCoach will keep retrying."
        }).catch(() => null);

        if(user){
          const { error } = await supabaseClient
            .from("users_profiles")
            .upsert({
              user_id: user.id,
              riot_id: riotId,
              region: region || "NA",
              profile_json: getActiveProfile() || {},
              updated_at: nowISO()
            }, { onConflict: "user_id" });

          if(error){
            alert(error.message);
            return;
          }
        }
      }

      if (saveBtn) {
        saveBtn.textContent = "Syncing Riot Data...";
      }

      hideRiotProfilePrompt?.({ persist: true });
      closeRiotModal?.();
      await performRiotSync({
        silent: false,
        mode: "import",
        allowDemoFallback: false
      });
    } finally {
      if (saveBtn) {
        saveBtn.disabled = false;
        saveBtn.textContent = originalText;
      }
    }
  });
}

