function normalizeImportedMatchEntry(match = {}){
  const result = String(
    match?.result ||
    match?.metadata?.result ||
    "draw"
  ).toLowerCase();

  const createdAt =
    match?.createdAt ||
    match?.metadata?.playedAt ||
    nowISO();
  const core = getMatchCore(match);
  const isHenrikMatch = String(match?.source || match?.metadata?.source || "").toLowerCase() === "henrik_sync";
  const isDemoMatch = isDemoFixtureMatch(match);
  const importedRr = isHenrikMatch
    ? (isVerifiedHenrikRrMatch(match)
      ? getOptionalFiniteNumber(match?.verifiedRrDelta ?? match?.matchRecord?.rank?.rrDelta)
      : null)
    : getOptionalFiniteNumber(match?.rr);

  const metadata = {
    ...(match?.metadata || {}),
    result,
    playedAt: match?.metadata?.playedAt || createdAt
  };
  if (isDemoMatch && (match?.metadata?.demoAct || match?.demoAct || match?.metadata?.act || match?.act)) {
    metadata.demoAct = getDemoStatsActLabel(match?.metadata?.demoAct || match?.demoAct || match?.metadata?.act || match?.act);
  } else {
    delete metadata.demoAct;
  }

  return hydrateMatchDerivedData({
    ...match,
    rr: importedRr,
    kills: Number.isFinite(core?.kills) ? core.kills : safeNumber(match?.kills, 0),
    deaths: Number.isFinite(core?.deaths) ? core.deaths : safeNumber(match?.deaths, 0),
    assists: Number.isFinite(core?.assists) ? core.assists : safeNumber(match?.assists, 0),
    acs: Number.isFinite(core?.acs) ? core.acs : safeNumber(match?.acs ?? match?.adr, 0),
    result,
    createdAt,
    metadata
  });
}

function applyImportedMatches(matchList = [], options = {}){

  const profile = getActiveProfile();
  if(!profile) return;
  const hadNoMatchesBeforeImport = !Array.isArray(matches) || matches.length === 0;
  const sessionDateKey = getCurrentSessionDateKey();
  const importSource = options.source || "riot";
  const isRealSyncImport = ["riot", "henrik"].includes(importSource);
  const baselineMatches = isRealSyncImport
    ? purgeDemoFixtureMatches(matches || [])
    : (matches || []);

  const previousTotal = baselineMatches.reduce((sum, match) => sum + safeNumber(match?.rr), 0);
  const previousSessionTotal = sumRRForSession(baselineMatches, sessionDateKey);

  const normalized = (isRealSyncImport ? purgeDemoFixtureMatches(matchList) : (matchList || []))
    .filter(Boolean)
    .map(normalizeImportedMatchEntry)
    .map(match => isRealSyncImport ? markMatchStoredRawRehydrateCurrent(match) : match);
  normalized.sort((a, b) =>
    new Date(a?.createdAt || a?.metadata?.playedAt || 0).getTime() -
    new Date(b?.createdAt || b?.metadata?.playedAt || 0).getTime()
  );
  const nextTotal = normalized.reduce((sum, match) => sum + safeNumber(match?.rr), 0);
  const nextSessionTotal = sumRRForSession(normalized, sessionDateKey);

  if (["riot", "henrik"].includes(importSource)) {
    const todayKey = getCurrentDayKey();
    if (profile.startingRRDate !== todayKey) {
      const previousAbsolute = safeNumber(profile.startingRR) + previousTotal;
      profile.startingRR = Math.max(0, Math.round(previousAbsolute));
      profile.startingRRDate = todayKey;
      profile.startingRRSource = "riot-sync";
    }
  }

  if (previousSessionTotal !== nextSessionTotal) {
    writeRRTotalAnimationPayload(previousSessionTotal, nextSessionTotal);
  }

  profile.importSource = importSource;
  profile.lastSyncAt = nowISO();

  if(options.analytics){
    profile.trackerAnalytics = options.analytics;
  } else if (importSource === "henrik") {
    profile.trackerAnalytics = null;
  }

  if(options.source === "demo-fixture"){
    profile.startingRR = 320;
    profile.startingRRDate = "";
    profile.startingRRSource = "demo-progression";
    logEntries = buildDemoLogEntriesFromMatches(normalized);
    saveLogEntries();
  }

  commitProfileMatchesWithLoggingParity(profile, normalized, {
    source: importSource,
    animatePlaceholders: options.animatePlaceholders !== false,
    skipBackend: options.skipBackend === true
  });

  saveProfiles();
  let chartAnimationMode = null;
  if (hadNoMatchesBeforeImport && normalized.length > 0) {
    forceChartIntroAnimation = true;
    chartAnimationMode = CHART_ANIMATION_MODE_EMPHASIS;
  } else if (options.animationMode) {
    chartAnimationMode = options.animationMode;
  }
  if (options.deferSurfaceRefresh !== true) {
    refreshActiveProfileDataSurfaces({ chartAnimationMode });
  }
  scheduleRiotAutoSync();
}

async function importDemoMatches(options = {}){
  if (options.preferBuiltIn) {
    const matchList = buildClientTutorialDemoMatches(750);
    activeStatsActLabel = getDemoStatsActLabel("Season 2026 Act 3");
    activeStatsActKey = "";
    applyImportedMatches(matchList, {
      source: "demo-fixture",
      analytics: buildClientTutorialDemoAnalytics()
    });
    return {
      count: matchList.length,
      source: "demo-fixture",
      fallback: true
    };
  }

  try {
    const res = await fetchWithTimeout("/data/demo-import.json");
    const data = await res.json().catch(() => ({}));

    if(!res.ok){
      throw new Error(data?.error || `Demo import failed (${res.status})`);
    }

    const matchList = Array.isArray(data?.matches) ? data.matches : [];
    if(!matchList.length){
      throw new Error("Demo fixture did not return any matches");
    }

    applyImportedMatches(matchList, {
      source: data?.source || "demo-fixture",
      analytics: data?.analytics || null
    });

    return {
      count: matchList.length,
      source: data?.source || "demo-fixture"
    };
  } catch (error) {
    console.warn("Demo endpoint unavailable; using built-in tutorial fixture.", error);
    const matchList = buildClientTutorialDemoMatches(750);
    activeStatsActLabel = getDemoStatsActLabel("Season 2026 Act 3");
    activeStatsActKey = "";
    applyImportedMatches(matchList, {
      source: "demo-fixture",
      analytics: buildClientTutorialDemoAnalytics()
    });
    return {
      count: matchList.length,
      source: "demo-fixture",
      fallback: true
    };
  }
}

async function fetchWithTimeout(resource, options = {}, timeoutMs = RIOT_SYNC_FETCH_TIMEOUT_MS) {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), timeoutMs);

  try {
    return await fetch(resource, {
      ...options,
      signal: controller.signal
    });
  } catch (error) {
    if (error?.name === "AbortError") {
      throw new Error("Sync request timed out");
    }
    throw error;
  } finally {
    clearTimeout(timeoutId);
  }
}

async function importActiveProfileMatches(options = {}){
  const profile = getActiveProfile();
  if(!profile) throw new Error("No active profile");
  if(!profile.riotId) throw new Error("Set Riot ID first");
  const allowDemoFallback = options.allowDemoFallback !== false && isLocalDevelopmentHost();

  if (!isRiotSyncFeatureEnabled()) {
    if (allowDemoFallback) {
      return importDemoMatches();
    }
    throw new Error("Riot sync is waiting on Riot approval");
  }

  try {
    const storedRawPrep = prepareProfileStoredRawRehydrate(profile, {
      onProgress: options.onRehydrateProgress
    });
    const existingMatches = storedRawPrep.matches;
    if (storedRawPrep.changed) {
      commitProfileMatchesWithLoggingParity(profile, existingMatches, {
        source: "henrik",
        animatePlaceholders: false,
        skipBackend: true
      });
      saveProfiles();
    }
    const knownMatchIds = existingMatches
      .map(match => match?.matchId || match?.id || match?.metadata?.matchId)
      .filter(Boolean);
    const profileBackfillPrep = prepareProfileMatchBackfillScan(profile, existingMatches);
    const metadataRefreshMatchIds = profileBackfillPrep.metadataMatchIds;
    const weaponBackfillMatchIds = profileBackfillPrep.weaponMatchIds;
    const hsBackfillMatchIds = profileBackfillPrep.hsMatchIds;
    const needsHistoryVersionUpgrade = safeNumber(profile.henrikHistoryBackfillVersion) < HENRIK_HISTORY_BACKFILL_VERSION;
    const beginsNewHistoryVersion = needsHistoryVersionUpgrade
      && safeNumber(profile.henrikHistoryBackfillTargetVersion) !== HENRIK_HISTORY_BACKFILL_VERSION;
    if (beginsNewHistoryVersion) {
      profile.henrikHistoryCursor = 0;
      profile.henrikHistoryBackfillCompleteAt = "";
      profile.henrikHistoryBackfillTargetVersion = HENRIK_HISTORY_BACKFILL_VERSION;
    }
    const needsHistoryBackfill = needsHistoryVersionUpgrade || !profile.henrikHistoryBackfillCompleteAt;
    const historyStart = needsHistoryBackfill ? Math.max(0, safeNumber(profile.henrikHistoryCursor)) : 0;
    const historyLimit = needsHistoryBackfill ? HENRIK_HISTORY_BACKFILL_SIZE : 10;
    // A versioned history pass revisits retained records in chronological
    // pages, so sending every missing-payload id to the targeted search would
    // turn one migration into a redundant 1,000-match search. Outside that
    // pass, target the outstanding records directly.
    const storedRawRefreshMatchIds = needsHistoryBackfill
      ? []
      : (storedRawPrep.fetchMatchIds || []);
    // Keep every backfill reason behind one rotating cap. The old code capped
    // only stored raw payloads, allowing HS, weapon, and metadata scans to
    // enqueue an unbounded number of identical raw Henrik requests.
    const refreshPlan = buildProfileMatchRefreshPlan(profile, {
      metadataMatchIds: metadataRefreshMatchIds,
      weaponMatchIds: weaponBackfillMatchIds,
      hsMatchIds: hsBackfillMatchIds,
      storedRawMatchIds: storedRawRefreshMatchIds
    });
    const refreshMatchIds = refreshPlan.refreshMatchIds;
    const pullResult = await globalThis.RankedCoachRiotSync.pullMatches({
      riotId: profile.riotId,
      puuid: profile.puuid,
      region: normalizeHenrikRegion(profile.region),
      historyLimit,
      historyStart,
      knownMatchIds,
      refreshMatchIds,
      refreshSearchLimit: 1000,
      includeKnownMatches: needsHistoryVersionUpgrade,
      // Versioned history migrations intentionally revisit known retained
      // matches once so their raw Henrik payload can be stored for future
      // offline re-derives/backfills.
      hydrateRoundData: !needsHistoryBackfill
    });
    profile.puuid = pullResult?.puuid || profile.puuid || "";
    profile.lastSyncSource = "henrik";
    const matchSyncError = pullResult?.matchSyncError || null;
    if (matchSyncError) {
      profile.lastSyncErrorCode = String(matchSyncError.code || "henrik_request_failed");
      profile.lastSyncErrorAt = nowISO();
    } else {
      profile.lastSyncErrorCode = "";
      profile.lastSyncErrorAt = "";
    }
    saveProfiles();
    if (matchSyncError && safeNumber(pullResult?.checked) === 0) {
      const syncError = new Error(matchSyncError.message || "Riot match history is temporarily unavailable.");
      syncError.name = "RiotMatchSyncError";
      syncError.code = matchSyncError.code || "henrik_request_failed";
      syncError.status = safeNumber(matchSyncError.status);
      syncError.retryable = Boolean(matchSyncError.retryable);
      syncError.attempts = safeNumber(matchSyncError.attempts) || 1;
      throw syncError;
    }
    if (needsHistoryBackfill) {
      const nextCursor = historyStart + safeNumber(pullResult?.checked);
      profile.henrikHistoryCursor = nextCursor;
      profile.henrikHistoryWindowSize = Math.max(safeNumber(profile.henrikHistoryWindowSize), nextCursor);
      const reachedProviderWindow = nextCursor >= HENRIK_HISTORY_MAX_START;
      if (pullResult?.historyWindowComplete || reachedProviderWindow) {
        profile.henrikHistoryBackfillVersion = HENRIK_HISTORY_BACKFILL_VERSION;
        profile.henrikHistoryBackfillCompleteAt = nowISO();
        profile.henrikHistoryReachedLimit = reachedProviderWindow && !pullResult?.historyWindowComplete;
      }
    }
    const historyMigrationFinished = needsHistoryBackfill
      && (pullResult?.historyWindowComplete || profile.henrikHistoryReachedLimit === true);

    const canonicalRecords = Array.isArray(pullResult?.records) ? pullResult.records : [];
    const mmrHistory = Array.isArray(pullResult?.mmrHistory) ? pullResult.mmrHistory : [];
    const enrichMmr = globalThis.RankedCoachRiotSync?.enrichLegacyMatchesWithMmr;
    const unrecoveredWeaponBackfillIds = (Array.isArray(pullResult?.unresolvedRefreshMatchIds) ? pullResult.unresolvedRefreshMatchIds : [])
      .map(value => String(value || "").trim())
      .filter(value => weaponBackfillMatchIds.includes(value));
    const unrecoveredHsBackfillIds = (Array.isArray(pullResult?.unresolvedRefreshMatchIds) ? pullResult.unresolvedRefreshMatchIds : [])
      .map(value => String(value || "").trim())
      .filter(value => hsBackfillMatchIds.includes(value));
    const unrecoveredMetadataBackfillIds = (Array.isArray(pullResult?.unresolvedRefreshMatchIds) ? pullResult.unresolvedRefreshMatchIds : [])
      .map(value => String(value || "").trim())
      .filter(value => metadataRefreshMatchIds.includes(value));
    const unrecoveredStoredRawBackfillIds = (Array.isArray(pullResult?.unresolvedRefreshMatchIds) ? pullResult.unresolvedRefreshMatchIds : [])
      .map(value => String(value || "").trim())
      .filter(value => storedRawRefreshMatchIds.includes(value));
    if (!canonicalRecords.length) {
      let enrichedExisting = typeof enrichMmr === "function"
        ? enrichMmr(existingMatches, mmrHistory)
        : existingMatches;
      if (unrecoveredWeaponBackfillIds.length && pullResult?.refreshSearchComplete) {
        enrichedExisting = markWeaponBackfillUnavailable(enrichedExisting, unrecoveredWeaponBackfillIds);
      }
      if (unrecoveredHsBackfillIds.length && pullResult?.refreshSearchComplete) {
        enrichedExisting = markHsBackfillUnavailable(enrichedExisting, unrecoveredHsBackfillIds);
      }
      if (unrecoveredMetadataBackfillIds.length && pullResult?.refreshSearchComplete) {
        enrichedExisting = markMetadataBackfillUnavailable(enrichedExisting, unrecoveredMetadataBackfillIds);
      }
      if (unrecoveredStoredRawBackfillIds.length && pullResult?.refreshSearchComplete) {
        enrichedExisting = markStoredRawPayloadBackfillUnavailable(enrichedExisting, unrecoveredStoredRawBackfillIds);
      }
      if (historyMigrationFinished) {
        enrichedExisting = markStoredRawPayloadBackfillUnavailable(
          enrichedExisting,
          getMissingStoredRawPayloadMatchIds(enrichedExisting)
        );
      }
      profile.lastSyncAt = nowISO();
      commitProfileMatchesWithLoggingParity(profile, enrichedExisting, {
        source: "henrik",
        animatePlaceholders: options.mode === "refresh"
      });
      if (!needsHistoryBackfill || historyMigrationFinished) {
        const finalStoredRawPrep = prepareProfileStoredRawRehydrate(profile, { purgeDemo: false });
        if (finalStoredRawPrep.changed) {
          commitProfileMatchesWithLoggingParity(profile, finalStoredRawPrep.matches, {
            source: "henrik",
            animatePlaceholders: false,
            skipBackend: true
          });
        }
        prepareProfileMatchBackfillScan(profile, profile.matches, { purgeDemo: false });
      }
      saveProfiles();
      if (options.deferSurfaceRefresh !== true) {
        refreshActiveProfileDataSurfaces({
          chartAnimationMode: options.mode === "refresh"
            ? CHART_ANIMATION_MODE_LATEST_ONLY
            : null
        });
        await waitForActiveProfileSurfacePaint();
      }
      return {
        count: 0,
        checked: safeNumber(pullResult?.checked),
        source: "henrik",
        historyBackfilled: needsHistoryBackfill && Boolean(pullResult?.historyWindowComplete),
        rehydrated: storedRawPrep.rederived,
        failures: pullResult?.failures || [],
        syncError: matchSyncError,
        partial: Boolean(matchSyncError)
      };
    }

    const importedMatches = canonicalRecords.map(record =>
      globalThis.RankedCoachMatchRecord.toLegacyMatch(record)
    );
    const existingMatchIds = new Set(existingMatches
      .map(match => String(match?.matchId || match?.id || match?.metadata?.matchId || "").trim())
      .filter(Boolean));
    const newlyImportedMatches = importedMatches.filter(match => {
      const id = String(match?.matchId || match?.id || match?.metadata?.matchId || "").trim();
      return id && !existingMatchIds.has(id);
    });
    const mergedById = new Map(existingMatches.map(match => [String(match?.matchId || match?.id || ""), match]));
    importedMatches.forEach(match => {
      const id = String(match?.matchId || match?.id || "").trim();
      if (!id) return;
      mergedById.set(id, mergeImportedMatchWithExisting(mergedById.get(id), match));
    });
    const mergedMatches = Array.from(mergedById.values()).filter(Boolean);
    let matchList = typeof enrichMmr === "function"
      ? enrichMmr(mergedMatches, mmrHistory)
      : mergedMatches;
    if (unrecoveredWeaponBackfillIds.length && pullResult?.refreshSearchComplete) {
      matchList = markWeaponBackfillUnavailable(matchList, unrecoveredWeaponBackfillIds);
    }
    if (unrecoveredHsBackfillIds.length && pullResult?.refreshSearchComplete) {
      matchList = markHsBackfillUnavailable(matchList, unrecoveredHsBackfillIds);
    }
    if (unrecoveredMetadataBackfillIds.length && pullResult?.refreshSearchComplete) {
      matchList = markMetadataBackfillUnavailable(matchList, unrecoveredMetadataBackfillIds);
    }
    if (unrecoveredStoredRawBackfillIds.length && pullResult?.refreshSearchComplete) {
      matchList = markStoredRawPayloadBackfillUnavailable(matchList, unrecoveredStoredRawBackfillIds);
    }

    applyImportedMatches(matchList, {
      source: "henrik",
      deferSurfaceRefresh: options.deferSurfaceRefresh === true,
      animationMode: options.mode === "refresh"
        ? CHART_ANIMATION_MODE_LATEST_ONLY
      : null
    });

    if (historyMigrationFinished) {
      const unavailableRawPayloadIds = getMissingStoredRawPayloadMatchIds(profile.matches);
      if (unavailableRawPayloadIds.length) {
        const markedMatches = markStoredRawPayloadBackfillUnavailable(profile.matches, unavailableRawPayloadIds);
        commitProfileMatchesWithLoggingParity(profile, markedMatches, {
          source: "henrik",
          animatePlaceholders: false,
          skipBackend: true
        });
      }
    }

    const hasIncompleteFreshPayload = canonicalRecords.some(record => (
      isHenrikSyncRecord(record)
      && recordHasStoredRawPayload(record)
      && record?.rawPayloadComplete !== true
    ));
    if (hasIncompleteFreshPayload) {
      profile.storedRawIncompleteRetryCount = Math.min(
        RIOT_INCOMPLETE_RAW_RETRY_LIMIT,
        Math.max(0, safeNumber(profile.storedRawIncompleteRetryCount)) + 1
      );
    } else if (canonicalRecords.length) {
      profile.storedRawIncompleteRetryCount = 0;
    }

    // A completed regular sync can immediately stamp the confirmed profile
    // cache. During the paginated history migration we do this only on the
    // final page so the app does not repeat a full-history scan per batch.
    if (!needsHistoryBackfill || historyMigrationFinished) {
      const finalStoredRawPrep = prepareProfileStoredRawRehydrate(profile, { purgeDemo: false });
      if (finalStoredRawPrep.changed) {
        commitProfileMatchesWithLoggingParity(profile, finalStoredRawPrep.matches, {
          source: "henrik",
          animatePlaceholders: false,
          skipBackend: true
        });
      }
      prepareProfileMatchBackfillScan(profile, profile.matches, { purgeDemo: false });
      saveProfiles();
    }
    scheduleRiotAutoSync();

    if (!needsHistoryBackfill && newlyImportedMatches.length && options.deferSurfaceRefresh !== true) {
      refreshActiveProfileDataSurfaces({
        chartAnimationMode: options.mode === "refresh"
          ? CHART_ANIMATION_MODE_LATEST_ONLY
          : null
      });
      await waitForActiveProfileSurfacePaint();
      const latestNewMatch = newlyImportedMatches.slice().sort((a, b) =>
        new Date(a?.createdAt || a?.metadata?.playedAt || 0).getTime() -
        new Date(b?.createdAt || b?.metadata?.playedAt || 0).getTime()
      ).pop();
      if (latestNewMatch) {
        onMatchSaved(latestNewMatch, {
          ...options,
          importedCount: newlyImportedMatches.length,
          profile: getActiveProfile()
        });
      }
    }

    return {
      count: importedMatches.length,
      checked: safeNumber(pullResult?.checked),
      source: "henrik",
      historyBackfilled: needsHistoryBackfill && Boolean(pullResult?.historyWindowComplete),
      rehydrated: storedRawPrep.rederived,
      failures: pullResult?.failures || [],
      syncError: matchSyncError,
      partial: Boolean(matchSyncError)
    };
  } catch (error) {
    if (allowDemoFallback) {
      return importDemoMatches();
    }
    throw error;
  }
}

async function syncActiveProfileMatches(options = {}){
  const result = await importActiveProfileMatches({
    allowDemoFallback: options.allowDemoFallback !== false,
    mode: options.mode || "sync",
    deferSurfaceRefresh: options.deferSurfaceRefresh === true,
    onRehydrateProgress: options.onRehydrateProgress
  });
  if (options.deferSurfaceRefresh !== true) {
    refreshActiveProfileDataSurfaces?.({
      chartAnimationMode: result?.count ? CHART_ANIMATION_MODE_LATEST_ONLY : null,
      animatePlaceholders: false
    });
  }
  return {
    ...result,
    syncedAt: nowISO(),
    mode: options.mode || "sync"
  };
}

function clearRiotAutoSyncTimer() {
  if (riotAutoSyncTimer) {
    clearTimeout(riotAutoSyncTimer);
    riotAutoSyncTimer = null;
  }

  if (riotAutoSyncTicker) {
    clearInterval(riotAutoSyncTicker);
    riotAutoSyncTicker = null;
  }

  riotAutoSyncDeadline = 0;
}

function formatSyncCountdown(msRemaining) {
  const totalSeconds = Math.max(0, Math.ceil(msRemaining / 1000));
  const minutes = Math.floor(totalSeconds / 60);
  const seconds = totalSeconds % 60;
  return `${minutes}:${String(seconds).padStart(2, "0")}`;
}

function shouldShowIntervalCountdown(msRemaining) {
  const totalSeconds = Math.max(0, Math.ceil(msRemaining / 1000));
  return (
    (totalSeconds >= 118 && totalSeconds <= 120) ||
    (totalSeconds >= 88 && totalSeconds <= 90) ||
    (totalSeconds >= 58 && totalSeconds <= 60) ||
    (totalSeconds >= 28 && totalSeconds <= 30) ||
    totalSeconds <= 5
  );
}

function setProfileSyncStatus(timeValue, state = "idle", title = "", showTimer = false) {
  if (profileSyncCountdownEl) {
    profileSyncCountdownEl.textContent = timeValue;
  }

  if (profileSyncBtn) {
    profileSyncBtn.classList.remove("syncing", "counting", "needs-setup", "show-timer");
    if (state) {
      profileSyncBtn.classList.add(state);
    }
    if (showTimer) {
      profileSyncBtn.classList.add("show-timer");
    }

    const resolvedTitle = title || "Sync Riot data now";
    profileSyncBtn.title = resolvedTitle;
    profileSyncBtn.setAttribute("aria-label", resolvedTitle);
  }
}

function refreshProfileSyncCountdown() {
  if (riotSyncInFlight) {
    setProfileSyncStatus("", "syncing", "Syncing Riot data now", false);
    return;
  }

  if (!riotAutoSyncDeadline) {
    if (matchSyncConfigured === false) {
      setProfileSyncStatus("", "needs-setup", "Riot match sync is temporarily unavailable", false);
      return;
    }
    if (!hasSyncableRiotProfile()) {
      setProfileSyncStatus("", "needs-setup", "Add a Riot profile to sync Riot data", false);
      return;
    }

    if (!currentAuthUser) {
      setProfileSyncStatus("", "counting", "Manual Riot sync is available on this device. Sign in for desktop/mobile live sync.", false);
      return;
    }

    setProfileSyncStatus("", "counting", "Manual sync available. Auto sync will resume after the next schedule.", false);
    return;
  }

  const msRemaining = riotAutoSyncDeadline - Date.now();
  if (msRemaining <= 0) {
    setProfileSyncStatus("0:00", "counting", "Auto sync is about to run", true);
    return;
  }

  const countdownText = formatSyncCountdown(msRemaining);
  const showTimer = shouldShowIntervalCountdown(msRemaining);
  setProfileSyncStatus(
    showTimer ? countdownText : "",
    "counting",
    `Auto sync in ${countdownText}. Click to sync now and reset the timer.`,
    showTimer
  );
}

function startRiotAutoSyncCountdown() {
  if (riotAutoSyncTicker) {
    clearInterval(riotAutoSyncTicker);
  }

  refreshProfileSyncCountdown();

  if (!riotAutoSyncDeadline || riotSyncInFlight) {
    riotAutoSyncTicker = null;
    return;
  }

  riotAutoSyncTicker = setInterval(() => {
    refreshProfileSyncCountdown();

    if (!riotAutoSyncDeadline || riotSyncInFlight) {
      clearInterval(riotAutoSyncTicker);
      riotAutoSyncTicker = null;
    }
  }, 1000);
}

function hasSyncableRiotProfile() {
  const profile = getActiveProfile();
  return Boolean(String(profile?.riotId || "").trim());
}

async function isRiotSyncConfigured() {
  if (!isRiotSyncFeatureEnabled()) {
    return false;
  }

  try {
    const healthRes = await fetchWithTimeout("/api/henrik/health");
    const health = await healthRes.json().catch(() => ({}));
    matchSyncConfigured = Boolean(healthRes.ok && health?.configured !== false);
    return matchSyncConfigured;
  } catch (_error) {
    matchSyncConfigured = false;
    return false;
  }
}

function getPlayerFacingRiotSyncError(error = {}) {
  const code = String(error?.code || "").trim().toLowerCase();
  const status = safeNumber(error?.status);
  const rawMessage = String(error?.message || "").trim();
  if (status === 429 || code === "henrik_429" || /rate limit/i.test(rawMessage)) {
    return {
      title: "Riot sync paused",
      message: "Riot's data provider is busy right now — try again in a minute."
    };
  }
  if (status === 408 || status === 504 || ["henrik_408", "henrik_504", "henrik_timeout"].includes(code)) {
    return {
      title: "Riot sync paused",
      message: "Riot match data took too long to respond — try again in a minute."
    };
  }
  if (status >= 500 || ["henrik_500", "henrik_502", "henrik_503", "henrik_unavailable"].includes(code)) {
    return {
      title: "Riot sync paused",
      message: "Riot match data is temporarily unavailable — try again in a minute."
    };
  }
  if (code.startsWith("henrik_")) {
    return {
      title: "Riot sync paused",
      message: "Riot match data could not be refreshed right now. Try again shortly."
    };
  }
  return {
    title: "Riot sync needs attention",
    message: rawMessage || "Riot matches could not be synced. Try again shortly."
  };
}

function createRiotSyncTimeoutError(timeoutMs = RIOT_SYNC_TIMEOUT_MS) {
  const error = new Error(`Riot match data did not respond within ${Math.round(timeoutMs / 1000)} seconds.`);
  error.code = "henrik_timeout";
  error.status = 408;
  return error;
}

function withRiotSyncTimeout(promise, timeoutMs = RIOT_SYNC_TIMEOUT_MS) {
  let timer = 0;
  const timeout = new Promise((_, reject) => {
    timer = window.setTimeout(() => reject(createRiotSyncTimeoutError(timeoutMs)), timeoutMs);
  });
  return Promise.race([promise, timeout]).finally(() => {
    if (timer) window.clearTimeout(timer);
  });
}

async function performRiotSync(options = {}) {
  const {
    silent = false,
    mode = "sync",
    allowDemoFallback = true,
    verifyWarmup = true,
    prefillReflection = true,
    deferSurfaceRefresh = false
  } = options;
  const activeProfile = getActiveProfile();
  const hasRiotId = Boolean(String(activeProfile?.riotId || "").trim());
  const canUseDemoFallback = Boolean(allowDemoFallback && isLocalDevelopmentHost());

  if (riotSyncInFlight) {
    if (!silent) {
      alert("Riot sync is already in progress.");
    }
    scheduleRiotAutoSync();
    return null;
  }

  if (!currentAuthUser && !hasRiotId) {
    if (!silent) {
      openAuthModal?.();
    }

    clearRiotAutoSyncTimer();
    return null;
  }

  if (!currentAuthUser && hasRiotId) {
    requestSignInForRiotConnection?.({
      resumeAction: "sync-existing-riot",
      source: "riot-sync",
      reason: "guest-riot-sync",
      silent
    });
    clearRiotAutoSyncTimer();
    return null;
  }

  if (!hasRiotId) {
    if (!silent) {
      showRiotProfilePrompt?.({ force: true });
    }
    clearRiotAutoSyncTimer();
    return null;
  }

  maybeShowGuestCrossDeviceSyncNotice({ silent: true });

  if (!isRiotSyncFeatureEnabled() && !canUseDemoFallback) {
    setProfileSyncStatus("", "needs-setup", "Riot match sync is temporarily unavailable", false);
    clearRiotAutoSyncTimer();
    return null;
  }

  if (!canUseDemoFallback) {
    const configured = await isRiotSyncConfigured();
    if (!configured) {
      setProfileSyncStatus("", "needs-setup", "Riot match sync is temporarily unavailable", false);
      if (!silent) alert("Riot match sync is temporarily unavailable.");
      clearRiotAutoSyncTimer();
      return null;
    }
  }

  riotSyncInFlight = true;
  setProfileSyncStatus("", "syncing", "Syncing Riot data now", false);
  if (profileSyncBtn) profileSyncBtn.disabled = true;
  const showSyncLoading = !silent && !loginInitializationInFlight;
  let syncLoadingTimer = 0;
  if (showSyncLoading) {
    showAppLoadingVeil("Syncing Riot data now", {
      title: "Syncing your profile",
      progressLabel: "Riot sync",
      percent: 8,
      eventBanner: "game"
    });
    setAppLoadingVeilProgress(16, "Checking retained competitive history...");
  }

  try {
    if (showSyncLoading) setAppLoadingVeilProgress(28, "Resolving Riot match data...");
    const result = await withRiotSyncTimeout(
      syncActiveProfileMatches({
        mode,
        allowDemoFallback: canUseDemoFallback,
        deferSurfaceRefresh,
        onRehydrateProgress: progress => {
          options.onRehydrateProgress?.(progress);
          if (!showSyncLoading) return;
          const pct = 30 + Math.round((Math.max(0, Math.min(100, safeNumber(progress.percent))) / 100) * 32);
          setAppLoadingVeilProgress(pct, progress.message || "Updating retained match data...");
        }
      }),
      RIOT_SYNC_TIMEOUT_MS
    );
    if (showSyncLoading) setAppLoadingVeilProgress(82, "Refreshing your coaching pages...");
    const syncedProfile = getActiveProfile();
    if (syncedProfile) {
      syncedProfile.lastSyncAt = result?.syncedAt || nowISO();
      saveProfiles();
      if (verifyWarmup) void refreshWarmupAutoVerification(syncedProfile, { announce: !silent });
    }
    if (safeNumber(result?.count) > 0) {
      setAppLoadingEventBanner("game");
    }
    if (prefillReflection) prefillLatestImportedReflection();
    if (!deferSurfaceRefresh) {
      refreshActiveProfileDataSurfaces?.({
        reason: "riot-sync",
        animate: false,
        preserveActivePage: true
      });
    }

    if (!silent) {
      if (result?.syncError) {
        const playerError = getPlayerFacingRiotSyncError(result.syncError);
        const savedPrefix = result.count
          ? `${mode === "refresh" ? "Synced" : "Imported"} ${result.count} new competitive ${result.count === 1 ? "match" : "matches"}. `
          : "";
        setProfileSyncStatus("", "needs-setup", playerError.message, false);
        showToast(`${savedPrefix}${playerError.message}`, {
          title: result.count ? "Matches saved; sync paused" : playerError.title,
          durationMs: 4200
        });
      } else if (result?.source === "demo-fixture") {
        alert(`Live match sync is unavailable, so ${result.count} demo matches were loaded from the example dataset.`);
      } else {
        alert(result.count
          ? `${mode === "refresh" ? "Synced" : "Imported"} ${result.count} new competitive ${result.count === 1 ? "match" : "matches"}.`
          : "Your recent competitive matches are already up to date.");
      }
    }

    return result;
  } catch (err) {
    const playerError = getPlayerFacingRiotSyncError(err);
    setProfileSyncStatus("", "needs-setup", playerError.message, false);
    if (!silent) {
      showToast(playerError.message, {
        title: playerError.title,
        durationMs: 4200
      });
    }
    return null;
  } finally {
    if (syncLoadingTimer) {
      window.clearInterval(syncLoadingTimer);
      syncLoadingTimer = 0;
    }
    if (showSyncLoading) {
      setAppLoadingVeilProgress(100, "Sync complete.");
      window.setTimeout(() => hideAppLoadingVeil(), 180);
    }
    riotSyncInFlight = false;
    if (profileSyncBtn) profileSyncBtn.disabled = false;
    scheduleRiotAutoSync();
  }
}

async function syncProfileRetainedHistory(options = {}) {
  const profile = getActiveProfile();
  if (!profile?.riotId) {
    return { success: false, totalImported: 0, playerError: getPlayerFacingRiotSyncError({ message: "Add a Riot ID before syncing." }) };
  }
  const maxBatches = Math.max(1, Math.min(HENRIK_HISTORY_MAX_BATCHES, safeNumber(options.maxBatches, HENRIK_HISTORY_MAX_BATCHES)));
  const estimatedHistoryWindow = Math.max(
    HENRIK_HISTORY_BACKFILL_SIZE,
    Math.min(HENRIK_HISTORY_MAX_START, maxBatches * HENRIK_HISTORY_BACKFILL_SIZE)
  );
  let totalImported = 0;
  let totalChecked = 0;
  let lastResult = null;

  for (let batch = 0; batch < maxBatches; batch += 1) {
    const current = getActiveProfile();
    const retainedCount = Array.isArray(current?.matches) ? current.matches.length : 0;
    const batchStartPercent = Math.min(88, 12 + Math.round((Math.min(totalChecked, estimatedHistoryWindow) / estimatedHistoryWindow) * 72));
    options.onProgress?.({
      batch: batch + 1,
      maxBatches,
      retainedCount,
      checked: totalChecked,
      estimatedTotal: estimatedHistoryWindow,
      percent: batchStartPercent,
      message: batch === 0
        ? "Resolving the Riot account and checking competitive history..."
        : `Importing retained competitive history... ${retainedCount} matches ready, ${totalChecked} checked`
    });
    const result = await performRiotSync({
      silent: true,
      mode: options.mode || (batch === 0 ? "refresh" : "import"),
      allowDemoFallback: false,
      verifyWarmup: false,
      prefillReflection: false,
      deferSurfaceRefresh: true,
      onRehydrateProgress: progress => {
        const rehydratePercent = 8 + Math.round((Math.max(0, Math.min(100, safeNumber(progress.percent))) / 100) * 8);
        options.onProgress?.({
          batch: batch + 1,
          maxBatches,
          retainedCount,
          checked: totalChecked,
          estimatedTotal: estimatedHistoryWindow,
          percent: rehydratePercent,
          message: progress.message || "Updating retained match data..."
        });
      }
    });
    if (!result) {
      const latestProfile = getActiveProfile();
      const error = {
        code: latestProfile?.lastSyncErrorCode || "henrik_request_failed",
        message: "Riot match history could not be refreshed right now."
      };
      return { success: false, totalImported, totalChecked, lastResult, playerError: getPlayerFacingRiotSyncError(error) };
    }
    lastResult = result;
    totalImported += safeNumber(result.count);
    totalChecked += safeNumber(result.checked);
    const batchCompletePercent = Math.min(88, 12 + Math.round((Math.min(totalChecked, estimatedHistoryWindow) / estimatedHistoryWindow) * 76));
    options.onProgress?.({
      batch: batch + 1,
      maxBatches,
      retainedCount: Array.isArray(getActiveProfile()?.matches) ? getActiveProfile().matches.length : retainedCount,
      checked: totalChecked,
      estimatedTotal: estimatedHistoryWindow,
      percent: batchCompletePercent,
      message: `Checked ${totalChecked} retained competitive ${totalChecked === 1 ? "match" : "matches"} so far.`
    });
    const latestProfile = getActiveProfile();
    if (result.syncError) {
      prefillLatestImportedReflection();
      return {
        success: totalChecked > 0,
        partial: true,
        totalImported,
        totalChecked,
        lastResult,
        playerError: getPlayerFacingRiotSyncError(result.syncError)
      };
    }
    if (latestProfile?.henrikHistoryBackfillCompleteAt || safeNumber(result.checked) === 0) break;
    await new Promise(resolve => window.setTimeout(resolve, 220));
  }

  const syncedProfile = getActiveProfile();
  if (syncedProfile) {
    syncedProfile.lastDailyProfileSyncDate = formatLocalDateKey(new Date());
    saveProfiles();
    void refreshWarmupAutoVerification(syncedProfile, { announce: false });
  }
  const prefilled = prefillLatestImportedReflection();
  options.onProgress?.({
    batch: -1,
    maxBatches,
    retainedCount: Array.isArray(syncedProfile?.matches) ? syncedProfile.matches.length : 0,
    percent: 94,
    message: prefilled
      ? "Preparing your latest game in the reflection form..."
      : "Finalizing season stats and coaching reads..."
  });
  refreshActiveProfileDataSurfaces?.({
    reason: "retained-history-complete",
    chartAnimationMode: totalImported ? CHART_ANIMATION_MODE_LATEST_ONLY : null,
    animatePlaceholders: false,
    preserveActivePage: true
  });
  await waitForActiveProfileSurfacePaint?.();
  return { success: Boolean(lastResult), totalImported, totalChecked, lastResult, prefilled };
}

function scheduleDailyProfileSync() {
  if (dailyRiotSyncTimer) window.clearTimeout(dailyRiotSyncTimer);
  const now = new Date();
  const nextDay = new Date(now);
  nextDay.setHours(24, 0, 8, 0);
  dailyRiotSyncTimer = window.setTimeout(async () => {
    dailyRiotSyncTimer = null;
    const profile = getActiveProfile();
    if (profile?.riotId && profile.lastDailyProfileSyncDate !== formatLocalDateKey(new Date())) {
      await syncProfileRetainedHistory({ mode: "refresh", maxBatches: 1 });
    }
    scheduleDailyProfileSync();
  }, Math.max(1000, nextDay.getTime() - now.getTime()));
}

function scheduleRiotAutoSync() {
  clearRiotAutoSyncTimer();
  scheduleDailyProfileSync();

  if (!isRiotSyncFeatureEnabled()) {
    if (hasSyncableRiotProfile()) {
      setProfileSyncStatus("", "needs-setup", "Riot match sync is temporarily unavailable", false);
    }
    return;
  }

  if (matchSyncConfigured === false) {
    setProfileSyncStatus("", "needs-setup", "Riot match sync is temporarily unavailable", false);
    return;
  }

  const profile = getActiveProfile();
  const hasIncompleteRawPayloadRetry = Math.max(0, safeNumber(profile?.storedRawIncompleteRetryCount)) > 0
    && Math.max(0, safeNumber(profile?.storedRawIncompleteRetryCount)) < RIOT_INCOMPLETE_RAW_RETRY_LIMIT;
  const nextSyncDelay = hasIncompleteRawPayloadRetry
    ? RIOT_INCOMPLETE_RAW_RETRY_MS
    : RIOT_AUTO_SYNC_MS;
  riotAutoSyncDeadline = Date.now() + nextSyncDelay;
  startRiotAutoSyncCountdown();

  if (!hasSyncableRiotProfile()) {
    return;
  }

  riotAutoSyncTimer = setTimeout(() => {
    performRiotSync({
      silent: true,
      mode: "refresh",
      allowDemoFallback: false
    });
  }, nextSyncDelay);
}

